_rl = {}   # brute-force limiter: key -> [fail timestamps]


def rate_limited(key, limit=5, window=600):
    now = time.time()
    _rl[key] = [t for t in _rl.get(key, []) if now - t < window]
    return len(_rl[key]) >= limit


def rate_fail(key):
    _rl.setdefault(key, []).append(time.time())


def code_guess_blocked(who):
    """Wrong activation codes: 8 per caller and 40 across everyone per 10
    minutes, so changing the code or the name does not reset the count."""
    return rate_limited(("codeguess", who), limit=8) or rate_limited(("codeguess", "*"), limit=40)


def code_guess_fail(who):
    rate_fail(("codeguess", who))
    rate_fail(("codeguess", "*"))


def queue_push(uid, title, body, path=None, sticky=False, urgent=False, tag=None):
    """One line for the push notifier (it also writes the member's inbox). 2026-10-19: path = the page a tap opens,
    sticky = stays on screen until touched, tag = groups / replaces (the workshop AI uses "atelier")."""
    try:
        qf = os.path.join(DIR, "owl_push_queue.json")
        try:
            q = json.load(open(qf, encoding="utf-8"))
        except Exception:
            q = []
        it = {"uid": uid, "t": int(time.time()), "title": title, "body": body}
        if path is not None:
            it["path"] = path
        if sticky:
            it["sticky"] = True
        if urgent:
            it["urgent"] = True
        if tag:
            it["tag"] = tag
        q.append(it)
        json.dump(q, open(qf, "w", encoding="utf-8"), ensure_ascii=False)
    except Exception:
        pass


