def family_active(e, now=None):
    """2026-09-27 (owner): family = the Automatique package settled with the
    owner directly, 30 days at a time, renewed with a code. An old boolean
    'family' record still counts (grandfathered until it is dated)."""
    now = now or time.time()
    # 2026-10-03 (owner): with the profit share on, the package has no
    # end date - it runs while the monthly statements are settled
    if SHARE.on() and (e.get("family") or e.get("family_until")):
        return not e.get("share_blocked")
    if e.get("family_until"):
        return float(e["family_until"]) > now
    return bool(e.get("family"))


def has(uid, key):
    """2026-09-28 (owner): three separate keys.
    family   = the Automatique package (robot on the account) -> also manual
    manual   = signals + trade tool
    strategy = the full chart + the method - its own package, never
               included in family or manual, and not including them."""
    if uid in OWNER_UIDS:
        return True
    e = ent(uid)
    now = time.time()
    if key == "family":
        return family_active(e, now)
    if key == "manual":
        # 2026-10-17 (owner, catalogue review): Strategie includes Signal - the builder's member gets the signals too
        return family_active(e, now) or float(e.get("manual_until") or 0) > now or float(e.get("strategy_until") or 0) > now
    if key == "strategy":
        return float(e.get("strategy_until") or 0) > now
    return False


def _atomic_json(path, obj, **kw):
    """2026-10-16 (owner: "bad user experience" - activation showed 'Permission denied' on owl_entitlements.json):
    write to a temp file of THIS request, then swap it in, retrying ~3 s while Windows keeps the target open
    (a reader, or a double-tapped second request writing the same file)."""
    import threading as _th
    tmp = "%s.%d.%d.tmp" % (path, os.getpid(), _th.get_ident())
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(obj, f, **kw)
    for i in range(3):                   # os.replace itself waits 4 s since 2026-10-23 (_replace_retry)
        try:
            os.replace(tmp, path)
            return
        except PermissionError:
            time.sleep(0.1)
    os.replace(tmp, path)


def ent_grant(uid, pkg, days, src, usd=None):
    """Extend from the later of now / the current end (a renewal adds).
    2026-10-17 (owner: "I'm not spending money in this model, right?"): the grant records the MONEY RECEIVED for it
    (paid_usd over paid_days). The creator share accrues only on that money: a crypto payment carries its amount, a
    code is valued at the package price (the owner sells codes), and wallet days, welcome days, owner grants and the
    grandfathered first period carry 0 -> no share at all for them."""
    e = _ents()
    r = e.get(uid) or {}
    k = pkg + "_until"
    base = max(time.time(), float(r.get(k) or 0))
    r[k] = int(base + days * 86400)
    if pkg == "family":
        r["family"] = True           # legacy flag, kept in step with the date
    r["updated"] = int(time.time())
    r["src"] = src
    if usd is None:
        usd = 0.0
        if src == "code":
            try:
                usd = float(nest_config().get("family_usd") or 60) if pkg == "family" else float((PACKAGES.get(pkg) or {}).get("usd") or 0)
            except Exception:
                usd = 0.0
    if pkg == "family":
        r["paid_usd"] = round(float(usd or 0), 2); r["paid_days"] = int(days); r["paid_at"] = int(time.time())
    e[uid] = r
    _atomic_json(ENT_FILE, e, indent=1)
    return r


def ent_family(uid, on=True):
    """Revoke (on=False) or grant a family period (on=True -> +FAMILY_DAYS)."""
    if on:
        return ent_grant(uid, "family", FAMILY_DAYS, "code")
    e = _ents()
    r = e.get(uid) or {}
    r["family"] = False
    r["family_until"] = 0
    r["updated"] = int(time.time())
    e[uid] = r
    _atomic_json(ENT_FILE, e, indent=1)


