    _ltab = ("<h2 style=\"font-size:1rem;margin:22px 0 8px\">Sur la page d&rsquo;accueil</h2><table><tr><th>Jour</th>" + "".join("<th>%s</th>" % x for x in _ln) + "</tr>" + _lrows + "</table>")
