#tab-hist .grid .card .lbl{font-size:.64rem;letter-spacing:.1em;color:var(--muted);font-weight:700}
#tab-hist .grid .card .val{font-size:1.4rem;font-weight:700;letter-spacing:-.02em;margin-top:6px}
