ROBOT_REG = os.path.join(DIR, "robots", "robots.json")
ROBOT_MAX_PER_USER = 12


def _ascii(s):
    """an id from a name: accents folded (é -> e), not dropped"""
    import unicodedata as _ud
    return _ud.normalize("NFKD", str(s)).encode("ascii", "ignore").decode("ascii")

def robot_reg():
    try:
        return json.load(open(ROBOT_REG, encoding="utf-8"))
    except Exception:
        return {"parts": {}, "robots": []}


def robot_resolve(rid, robots, seen=None):
    seen = seen or set()
    r = robots.get(rid)
    if r is None or rid in seen:
        return {}
    seen.add(rid)
    out = robot_resolve(r.get("parent"), robots, seen) if r.get("parent") else {}
    for k, v in (r.get("parts") or {}).items():
        out[k] = v
    return out


def my_robot_payload(uid):
    """2026-10-13 (owner): the Robots tab is for every member - without Strategie they see THEIR robot (the one plugged
    on their account, the Owl when none is), its pieces in plain words and what it has done on this account. Building,
    testing and comparing stay in the Strategie offer."""
    reg = robot_reg()
    byid = {x["id"]: x for x in reg.get("robots") or []}
    try:
        PK = json.load(open(os.path.join(DIR, "owl_packages.json"), encoding="utf-8"))
    except Exception:
        PK = {}
    pl = (PK.get("robot_plugs") or {}).get(uid)
    rid = (pl or {}).get("robot") or "owl"
    r0 = byid.get(rid) or byid.get("owl") or {}
    R = robot_resolve(rid, byid)
    P = {x["id"]: x for x in reg.get("pieces") or []}

    def piece(slot, pid):
        x = P.get(pid) or {}
        return {"slot": slot, "id": pid, "name_fr": x.get("name_fr") or pid, "name_en": x.get("name_en") or x.get("name_fr") or pid,
                "plain_fr": x.get("plain_fr") or "", "plain_en": x.get("plain_en") or x.get("plain_fr") or ""}
    parts = []
    for slot in ("entry", "filters", "stop", "exit", "recovery"):
        v = R.get(slot)
        for pid in (v if isinstance(v, list) else [v] if v else []):
            parts.append(piece(slot, pid))
    try:
        nd = json.load(open(os.path.join(DIR, "nest_data", "%s.json" % uid), encoding="utf-8"))
        ss = nd.get("since_start") or {}
    except Exception:
        ss = {}
    return {"limited": True,
            "mine": {"id": rid, "name_fr": r0.get("name_fr") or rid, "name_en": r0.get("name_en") or r0.get("name_fr") or rid,
                     "plain_fr": r0.get("plain_fr") or "", "plain_en": r0.get("plain_en") or r0.get("plain_fr") or "",
                     "parts": parts, "since": {k: ss.get(k) for k in ("n", "won", "net", "days", "first")}}}


def robot_now(uid, ms, has_open, preview=None):
    """2026-10-13 (owner): En direct follows the robot PLUGGED on the account. Which robot (the Owl when none is
    plugged), and - for a plugged robot - each of its pieces, met or not, decided by the live bot's own functions
    (robots/robot_live.py filters_ok) on the same inputs the bot reads (the chart file's vol_now / vol_ref /
    moves_2h, the pullback side). Read-only: nothing here changes what the bot does."""
    try:
        PK = json.load(open(os.path.join(DIR, "owl_packages.json"), encoding="utf-8"))
        pl = (PK.get("robot_plugs") or {}).get(uid)
        reg = robot_reg()
        byid = {x["id"]: x for x in reg.get("robots") or []}
        if preview:
            if preview not in byid:
                return {"id": "?", "err": "unknown"}
            pl = {"robot": preview}
        rid = (pl or {}).get("robot") or "owl"
        r0 = byid.get(rid) or byid.get("owl") or {}
        out = {"id": rid, "name_fr": r0.get("name_fr") or rid, "name_en": r0.get("name_en") or r0.get("name_fr") or rid}
        if not pl:
            return out
        R = robot_resolve(rid, byid)
        P = {x["id"]: x for x in reg.get("pieces") or []}
        rules = PKG.for_account(uid).get("robot_rules") or {}
        if preview:
            try:
                rules = robot_package(dict(byid[rid], resolved=R), reg.get("pieces") or [], "base", None).get("robot_rules") or {}
            except ValueError as e:
                out["not_live"] = str(e)
                rules = {}
            out["preview"] = True
        ms = ms or {}
        vn, vr = ms.get("vol_now"), ms.get("vol_ref")
        rv = (float(vn) / max(float(vr), 1e-9)) if (vn and vr) else None
        mv = ms.get("moves_2h")
        now = datetime.now(timezone.utc)
        _rp = os.path.join(DIR, "robots")
        if _rp not in sys.path:
            sys.path.insert(0, _rp)
        import robot_live as _RLS
        items = []

        def nm(pid):
            x = P.get(pid) or {}
            return x.get("name_fr") or pid, x.get("name_en") or x.get("name_fr") or pid

        # entry: what it waits for (met = a trade is open)
        ep = R.get("entry")
        if ep:
            ev = ((rules.get("entry") or {}).get("event")) or "bos"
            w = {"choch": ("attend un CHoCH", "waits for a CHoCH"), "any": ("attend une cassure ou un CHoCH", "waits for a break or a CHoCH")}.get(
                ev, ("attend une cassure (BOS)", "waits for a break (BOS)"))
            f, e = nm(ep)
            items.append({"k": "entry", "fr": f, "en": e, "ok": True if has_open else None,
                          "why_fr": "un trade est ouvert" if has_open else w[0], "why_en": "a trade is open" if has_open else w[1]})
            out["entry_event"] = ev
        # filters: each piece on its own
        for fp in R.get("filters") or []:
            x = P.get(fp) or {}
            f, e = nm(fp)
            eng, rule = x.get("engine") or {}, x.get("rule")
            ok, wf, we, ck = None, "", "", ""
            if rule:
                ok, why = _RLS.filters_ok({"filters": [rule]}, now.hour, now.weekday(), rv, mv)
                k = rule.get("kind")
                if ok:
                    wf, we = {"hours": ("dans ses heures (%s h - %s h UTC)" % (rule.get("from"), rule.get("to")),
                                        "inside its hours (%s - %s UTC)" % (rule.get("from"), rule.get("to"))),
                              "weekdays": ("un de ses jours", "one of its days"),
                              "pace": ("rythme du marché dans sa plage", "market pace inside its range"),
                              "moves": ("assez de grands mouvements", "enough big moves")}.get(k, ("ok", "ok"))
                else:
                    wf = why
                    we = {"hours": "outside its hours (%s - %s UTC)" % (rule.get("from"), rule.get("to")),
                          "weekdays": "not one of its days", "pace": "market pace outside its range",
                          "moves": "not enough big moves"}.get(k, why)
            elif eng.get("gate") == "trend":
                t, sd = ms.get("pb_trend"), ms.get("pb_side")
                ok = t in (1, -1) and sd != "wrong"
                ck = "trend" if t not in (1, -1) else "side"
                wf, we = (("tendance claire, prix du bon côté", "clear trend, price on the right side") if ok else
                          (("le prix doit repasser sa dernière cassure", "price must come back past its last break") if t in (1, -1)
                           else ("pas de tendance claire", "no clear trend")))
            elif eng.get("storm"):
                ok = rv is None or rv < float(eng["storm"])
                ck = "calm"
                wf, we = ("pas de tempête", "no storm") if ok else ("marché trop rapide", "market too fast")
            elif eng.get("movement"):
                ok = mv is None or int(mv) >= int(eng["movement"])
                ck = "awake"
                wf, we = ("le marché bouge", "the market is moving") if ok else ("pas de grand mouvement depuis 2 h", "no big move for 2 h")
            elif eng.get("nerv_gate"):
                ok = rv is None or rv <= 1.0
                ck = "calm"
                wf, we = ("marché calme", "calm market") if ok else ("marché nerveux", "nervous market")
            else:
                continue
            items.append({"k": "filter", "fr": f, "en": e, "ok": bool(ok), "why_fr": wf, "why_en": we, "ck": ck})
        # exit: only says something while a trade is open
        xp = R.get("exit")
        if xp and has_open:
            f, e = nm(xp)
            x = rules.get("exit") or {}
            bits_f, bits_e = [], []
            if x.get("choch"):
                bits_f.append("CHoCH contre le trade"); bits_e.append("a CHoCH against the trade")
            if x.get("target"):
                bits_f.append("objectif %sR" % x["target"]); bits_e.append("target %sR" % x["target"])
            if x.get("time_min"):
                bits_f.append("durée max %d min" % int(x["time_min"])); bits_e.append("max %d min" % int(x["time_min"]))
            items.append({"k": "exit", "fr": f, "en": e, "ok": None,
                          "why_fr": "surveille : " + (" ou ".join(bits_f) or "son objectif"), "why_en": "watching: " + (" or ".join(bits_e) or "its target")})
        out["pieces"] = items
        return out
    except Exception as ex:
        return {"id": "?", "err": str(ex)[:80]}


TESTS_PAUSED = os.path.join(DIR, "robots", "tests_paused.json")    # exists = no robot / market test starts (luck tests apart)


def _proc_freeze(pid, freeze):
    """suspend / resume one process (Windows)"""
    import ctypes
    h = ctypes.windll.kernel32.OpenProcess(0x0800, False, int(pid))      # PROCESS_SUSPEND_RESUME
    if not h:
        return False
    try:
        return (ctypes.windll.ntdll.NtSuspendProcess if freeze else ctypes.windll.ntdll.NtResumeProcess)(h) == 0
    finally:
        ctypes.windll.kernel32.CloseHandle(h)


def tests_control(on, who="kino"):
    """2026-10-19 (owner: "give him power to act on tests directly"): pause or resume the nest's robot / market tests.
    Luck tests are never touched. Pause = the running test runners are frozen where they are and no new run starts;
    resume = they continue exactly where they were, and the queue is kicked."""
    if on:
        if not os.path.exists(TESTS_PAUSED):
            return {"ok": True, "state": "running", "already": True}
        try:
            P = json.load(open(TESTS_PAUSED, encoding="utf-8")).get("suspended_pids") or []
        except Exception:
            P = []
        back = [p for p in P if _proc_freeze(p, False)]
        os.remove(TESTS_PAUSED)
        robot_runner_kick()
        robot_fast_kick()
        return {"ok": True, "state": "running", "resumed": len(back)}
    if os.path.exists(TESTS_PAUSED):
        return {"ok": True, "state": "paused", "already": True}
    P = []
    try:
        import subprocess
        out = subprocess.run(["powershell", "-NoProfile", "-Command", "Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -like "
                              "'*robot_runner.py*' } | ForEach-Object { $_.ProcessId }"],
                             capture_output=True, text=True, timeout=30, creationflags=0x08000000).stdout
        for ln in out.splitlines():
            if ln.strip():
                pid = ln.strip()
                if pid.isdigit() and _proc_freeze(int(pid), True):
                    P.append(int(pid))
    except Exception:
        pass
    json.dump({"since": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), "why": "paused by %s" % who, "suspended_pids": P},
              open(TESTS_PAUSED, "w", encoding="utf-8"), indent=1)
    return {"ok": True, "state": "paused", "frozen": len(P)}


def robot_runner_kick():
    """test the queued robots now, in the background, unless a run is already going"""
    if os.path.exists(TESTS_PAUSED):          # 2026-10-19 (owner): "pause any test other than the BTC" - requests queue
        return
    try:
        lk = os.path.join(DIR, "robots", "runner.lock")
        if os.path.exists(lk) and time.time() - os.path.getmtime(lk) < 3 * 3600:
            return
        import subprocess
        st = os.path.join(os.path.dirname(DIR), "study")
        subprocess.Popen(["pythonw", "robot_runner.py"], cwd=st, creationflags=0x08000000 | 0x00004000)   # below normal: bots + chat first
    except Exception:
        pass


def builder_payload(user, detail):
    """the builder side of the Robots view: the parts, the composed robots (with their test result
    against their parent), and where the main robot is plugged (one line per account)"""
    reg = robot_reg()
    me = user.get("id")
    R = [r for r in reg.get("robots") or [] if detail or r.get("by_uid") == me
         or r.get("public", r.get("by") in ("owner", "claude", "chercheur"))]
    byid = {r["id"]: r for r in reg.get("robots") or []}
    _pcs = {p["id"]: p for p in reg.get("pieces") or []}
    out = []
    for r in R:
        x = {k: v for k, v in r.items() if k not in ("by_uid",)}
        x["resolved"] = robot_resolve(r["id"], byid)
        x["mine"] = r.get("by_uid") == me
        x["can_edit"] = _robot_mine(user, r) and r.get("id") != "owl"
        x["public"] = bool(r.get("public", r.get("by") in ("owner", "claude", "chercheur")))
        x["live_capable"] = robot_live_capable(x["resolved"], _pcs)
        if r.get("stage") == "queued":
            _q = [y["id"] for y in reg.get("robots") or [] if y.get("stage") == "queued"]
            x["ahead"] = _q.index(r["id"]) if r["id"] in _q else 0
        if r.get("plug") and not detail and r.get("by_uid") == me and str(r["plug"].get("where", "")).startswith("acct:"):
            x["plug"] = dict(r["plug"], where="acct:mine")
        try:
            if r.get("id") == "owl-choch" and r.get("result"):
                j = json.load(open(os.path.join(os.path.dirname(DIR), r["result"]), encoding="utf-8"))
                row = (j.get("rows") or {}).get("0.35") or {}
                x["test"] = {"robot": row.get("owner_robot"), "parent_result": row.get("today"), "days": j.get("days"), "window_utc": j.get("window_utc"),
                             "parts_only": {"exit": row.get("exit_choch"), "recovery": row.get("money_all_bos"), "no_stop": row.get("owner_no_stop")}}
            else:
                j = json.load(open(os.path.join(DIR, "robots", "results", r["id"] + ".json"), encoding="utf-8"))
                x["test"] = {"robot": j.get("robot"), "parent_result": j.get("parent_result"), "days": j.get("days"), "window_utc": j.get("window_utc")}
        except Exception:
            x["test"] = None
        if r.get("id") == "owl" and not x.get("test"):
            _ot = _robot_test("owl")
            if _ot.get("net") is not None:
                x["test"] = {"robot": {k: v for k, v in _ot.items() if k not in ("balance", "window_utc", "days", "generated_at")},
                             "parent_result": None, "days": _ot.get("days"), "window_utc": _ot.get("window_utc")}
        x["mtests"] = _robot_mtests(r["id"])
        x["mhist"] = _robot_mhist(r["id"])
        # 2026-10-22 (owner: "still says pas encore testé in some places"): a robot built for gold is tested on gold - its
        # stage stays 'draft' (only a Bitcoin test moves it), so every page showed "Pas encore testé". Pages get "tested"
        # once a market test is done; the registry's own stage is untouched (stage_raw)
        if x.get("stage") == "draft" and any(m.get("state") == "done" and (m.get("robot") or {}).get("trades") for m in x["mtests"] or []):
            x["stage_raw"] = "draft"
            x["stage"] = "tested"
        if x.get("test"):
            for k in ("robot", "parent_result"):
                if x["test"].get(k):
                    x["test"][k] = {kk: vv for kk, vv in x["test"][k].items() if kk != "pnls"}
            # 2026-10-17: the Bitcoin row carries its random-entry control too (own + parent's), same file family
            x["test"]["ctl"] = _random_ctl(r["id"], "BTCUSD")
            x["test"]["parent_ctl"] = _random_ctl(r.get("parent") or "owl", "BTCUSD") if r.get("id") != "owl" else None
        out.append(x)
    try:
        PK = json.load(open(os.path.join(DIR, "owl_packages.json"), encoding="utf-8"))
    except Exception:
        PK = {"accounts": {}}
    plugs = []
    i = 0
    for u in users():
        uid = u.get("id")
        pk = (PK.get("accounts") or {}).get(uid)
        if not pk:
            continue
        # 2026-10-14 (owner): "users should not see each other's accounts" - a member gets only THEIR account's
        # plug (no list, no count of the others); the owner keeps the whole view
        if not detail and uid != me:
            continue
        lab, alive, why = bot_on(uid)
        rob = "owl"
        if pk.startswith("robot-") and pk[6:] in byid:
            rob = pk[6:]
            pk = robot_resolve(rob, byid).get("money") or "base"
        nm = ROBOT_NAMES.get(pk, (pk, pk))
        plugs.append({"account": (_strat_account_label(u, i, detail) if detail else {"fr": "Votre compte", "en": "Your account"}), "robot": rob, "money": "pkg-" + pk, "money_fr": nm[0], "money_en": nm[1],
                      "market": "BTCUSD", "alive": (bool(alive) if lab else None), "uid": uid if detail else None,
                      "plugged": rob != "owl", "restart_auto": uid in BOT_VARIANT,
                      "real": "trial" not in str(u.get("mt5_server") or "").lower() and u.get("mt5_server") is not None})
        if not (u.get("reference") or uid == "u224016179" or u.get("public")):
            i += 1
    # 2026-10-18 (owner upgrade list): is the robot running anywhere? (a member sees yes/no, never the others' count)
    try:
        _cnt = {}
        for _u in users():
            _pk = (PK.get("accounts") or {}).get(_u.get("id"))
            if not _pk or _u.get("public"):
                continue
            _rb = _pk[6:] if _pk.startswith("robot-") and _pk[6:] in byid else "owl"
            _cnt[_rb] = _cnt.get(_rb, 0) + 1
            for _mx in ((PK.get("market_plugs") or {}).get(_u.get("id")) or {}).values():     # 2026-10-22: robots on other markets
                if _mx.get("robot") in byid:
                    _cnt[_mx["robot"]] = _cnt.get(_mx["robot"], 0) + 1
        _rp = PK.get("robot_plugs") or {}
        for _x in out:
            _x["running"] = _cnt.get(_x["id"], 0) if detail else bool(_cnt.get(_x["id"]))
            _ats = [str(v.get("at") or "") for v in _rp.values() if isinstance(v, dict) and v.get("robot") == _x["id"]]
            if _ats:
                _x["plugged_at"] = max(_ats)          # the latest plug on any account (a date only, never whose)
    except Exception:
        pass
    # money pieces = the packages (generic names); a dead package is not offered
    try:
        _pk = json.load(open(os.path.join(DIR, "owl_packages.json"), encoding="utf-8"))
    except Exception:
        _pk = {"packages": {}, "accounts": {}}
    used_acc = set((_pk.get("accounts") or {}).values())
    pieces = [dict(p) for p in reg.get("pieces") or [] if piece_visible(user, p, detail)]
    for name, pk in (_pk.get("packages") or {}).items():
        if not isinstance(pk, dict) or "mort" in str(pk.get("label") or ""):
            continue
        nm = ROBOT_NAMES.get(name, (name, name, "", ""))
        pieces.append({"id": name, "type": "money", "name_fr": nm[0], "name_en": nm[1], "plain_fr": nm[2], "plain_en": nm[3],
                       "status": "live" if (name in used_acc or name == "base") else "tested", "live": True, "by": "owner", "version": 1, "pkg": "pkg-" + name})
    for pc in pieces:
        pc["used_by"] = [x["id"] for x in out if (pc["id"] in (x["resolved"].get("filters") or [])) or pc["id"] in
                         [x["resolved"].get(k) for k in ("entry", "stop", "exit", "recovery", "money")]]
        pc.pop("engine", None)
        pc["mine"] = bool(pc.get("by_uid")) and pc.get("by_uid") == me
        pc["can_edit"] = bool(pc.get("rule")) and (pc["mine"] or bool(is_admin(user)))
        pc.pop("by_uid", None)
    try:
        # 2026-10-17 (owner): the robot's own page says whether it is on the place (publish row in "Gerer mon robot")
        import owl_market as _OMKT
        _LS = _OMKT.data().get("listings") or {}
        for x in out:
            _L = _LS.get(x.get("id"))
            x["market"] = ({"price_usd": _L.get("price_usd") or 0, "free": not _L.get("price_usd"), "paused": bool(_L.get("paused")), "alias": _L.get("alias"),
                            "followers": len(_OMKT.followers(x.get("id")))} if _L and not _L.get("hidden") else None)
    except Exception:
        pass
    _can = bool((is_admin(user) or has(me, "strategy")) and not user.get("public"))
    if not _can:
        # readers (demo, Signal, Automatique): the names and plain words, never the rules or the edit rights
        for pc in pieces:
            pc.pop("rule", None); pc["can_edit"] = False
        for x in out:
            x["can_edit"] = False
        plugs = []                     # which accounts run which robot names members: never shown to readers
    _kb = {}
    try:                                   # 2026-10-23 (owner, upgrade 5): Kino's calls, visible and honest
        _rc()
        import kino_inner as _KIb
        _dd = _KIb._load()
        _B = [b for b in _dd.get("bets") or [] if b.get("done")]
        _kb = {"n": len(_B), "right": sum(1 for b in _B if b.get("right")), "by": _KIb.hunch_score().get("by") or {},
               "last": [{"t": int(b.get("t") or 0), "sym": b.get("sym"), "nm": b.get("nm"), "text": str(b.get("text") or "")[:160], "right": bool(b.get("right"))}
                        for b in sorted(_B, key=lambda x: -float(x.get("t") or 0))[:12]],
               "tests": [{"label": x.get("label"), "bet": x.get("bet"), "right": bool(x.get("right")), "net": x.get("net")} for x in (_dd.get("test_bet_log") or [])[-8:]]}
    except Exception:
        _kb = {}
    return {"pieces": pieces, "robots": out, "plugs": plugs, "can_create": _can, "kino_bets": _kb,
            "admin": bool(is_admin(user)), "targets": robot_targets(user, detail), "test_min": ROBOT_TEST_MIN,
            "max": ROBOT_MAX_PER_USER, "running": os.path.exists(os.path.join(DIR, "robots", "runner.lock"))}


def robot_create(user, body, dry=False):
    """a new robot from the builder: a parent + the parts it replaces + a name; queued for its test"""
    import re as _re
    reg = robot_reg()
    rob = reg.get("robots") or []
    me = user.get("id")
    if not dry and sum(1 for r in rob if r.get("by_uid") == me) >= ROBOT_MAX_PER_USER and not is_admin(user):
        return {"ok": False, "err": "limit"}
    name = str(body.get("name") or "").strip()[:40]
    if len(name) < 2:
        return {"ok": False, "err": "name"}
    parent = str(body.get("parent") or "owl")
    if parent not in {r["id"] for r in rob}:
        return {"ok": False, "err": "parent"}
    P = body.get("parts") or {}
    clean = {}
    PCS = {p["id"]: p for p in reg.get("pieces") or []}
    usable = lambda pid, typ: (pid in PCS and PCS[pid].get("type") == typ and PCS[pid].get("status") not in ("pending", "to_build")
                               and piece_visible(user, PCS[pid], is_admin(user)))
    for k in ("entry", "stop", "exit", "recovery"):
        if P.get(k):
            if not usable(P[k], k):
                return {"ok": False, "err": k}
            clean[k] = P[k]
    if "filters" in P:
        F = [f for f in (P.get("filters") or []) if isinstance(f, str)]
        if len(set(F)) != len(F) or any(not usable(f, "filter") for f in F):
            return {"ok": False, "err": "filters"}
        clean["filters"] = F
    if P.get("money"):
        try:
            pk = json.load(open(os.path.join(DIR, "owl_packages.json"), encoding="utf-8")).get("packages") or {}
        except Exception:
            pk = {}
        if P["money"] not in pk or "mort" in str((pk.get(P["money"]) or {}).get("label") or ""):
            return {"ok": False, "err": "money"}
        clean["money"] = P["money"]
    if not clean:
        return {"ok": False, "err": "same"}
    if dry:
        return {"ok": True, "parts": clean}
    base = _re.sub(r"[^a-z0-9]+", "-", _ascii(name).lower()).strip("-")[:24] or "robot"
    rid, n = base, 2
    ids = {r["id"] for r in rob}
    while rid in ids:
        rid = "%s-%d" % (base, n); n += 1
    rob.append({"id": rid, "name_fr": name, "name_en": name, "parent": parent, "parts": clean,
                "by": "owner" if is_admin(user) else "member", "by_uid": me,
                "created": datetime.now(timezone.utc).strftime("%Y-%m-%d"), "stage": "draft", "public": bool(is_admin(user))})
    reg["robots"] = rob
    _robot_save(reg)
    return {"ok": True, "id": rid}


# ---- 2026-10-12 (owner): members manage their robots - edit, delete, public/private, where to run it ----
def robot_live_capable(parts, pieces=None):
    """True when the live bot can already run every piece of the robot (robots.json v2 'live' flag) - such a
    robot becomes a money package + a plug once the owner approves. 2026-10-19 (owner): only the market structure is
    fixed - a robot may drop the storm piece (the live bot reads storm_ceiling)."""
    P = pieces if pieces is not None else {p["id"]: p for p in robot_reg().get("pieces") or []}
    for k in ("entry", "stop", "exit", "recovery"):
        v = parts.get(k)
        if v is not None and not ((P.get(v) or {}).get("live") or (P.get(v) or {}).get("rule")):
            return False
    F = parts.get("filters")
    if F is not None and any(not ((P.get(f) or {}).get("live") or (P.get(f) or {}).get("rule")) for f in F):
        return False
    return True


def robot_targets(user, detail):
    """where a member may ask to run a robot: a twin (no money), the demo, their own account(s); and a market"""
    T = [{"id": "twin", "fr": "Jumeau sans argent", "en": "Twin without money"},
         {"id": "demo", "fr": "Compte démo", "en": "Demo account"}]
    try:
        PK = json.load(open(os.path.join(DIR, "owl_packages.json"), encoding="utf-8")).get("accounts") or {}
    except Exception:
        PK = {}
    i = 0
    for u in users():
        uid = u.get("id")
        if uid not in PK:
            continue
        lab = _strat_account_label(u, i, detail)
        if not (u.get("reference") or uid == "u224016179" or u.get("public")):
            i += 1
        if detail or uid == user.get("id"):
            T.append({"id": "acct:" + uid if detail else "acct:mine", "fr": lab["fr"], "en": lab["en"], "account": True})
    M = [{"sym": s["sym"], "fr": s["fr"], "en": s["en"]} for s in chart_symbols()]
    return {"where": T, "markets": M}


def _robot_save(reg):
    # 2026-10-20 (owner screenshot: "test n'a pas pu démarrer (piece: [WinError 5] Access is denied")): the test runner
    # had the registry open - retry the swap instead of failing the member's test
    _atomic_json(ROBOT_REG, reg, ensure_ascii=False, indent=1)


def _robot_mine(user, r):
    return bool(r) and (is_admin(user) or (r.get("by_uid") and r.get("by_uid") == user.get("id")))


def robot_update(user, body):
    reg = robot_reg()
    rob = reg.get("robots") or []
    r = next((x for x in rob if x.get("id") == body.get("id")), None)
    if not _robot_mine(user, r) or r.get("id") == "owl":
        return {"ok": False, "err": "not_yours"}
    if "public" in body:
        r["public"] = bool(body["public"])
    if "archived" in body:                      # 2026-10-18: archived robots leave the lists, keep their history
        if body["archived"] and r.get("id") == _acct_cur_robot(user):
            return {"ok": False, "err": "on_account"}
        if body["archived"]:
            r["archived"] = True
            r["public"] = False
        else:
            r.pop("archived", None)
    if body.get("name"):
        nm = str(body["name"]).strip()[:40]
        if len(nm) >= 2:
            r["name_fr"] = r["name_en"] = nm
    if "parts" in body:
        chk = robot_create(user, {"name": r.get("name_fr") or "x", "parent": r.get("parent") or "owl", "parts": body.get("parts") or {}}, dry=True)
        if not chk.get("ok"):
            return chk
        if chk["parts"] != r.get("parts"):
            r["parts"] = chk["parts"]
            r["stage"] = "draft"
            r.pop("tested_at", None)
            try:
                os.remove(os.path.join(DIR, "robots", "results", r["id"] + ".json"))
            except Exception:
                pass
    if "plug" in body:
        p = body.get("plug")
        if not p:
            r.pop("plug", None)
        else:
            tg = robot_targets(user, is_admin(user))
            wh = str(p.get("where") or "")
            mk = str(p.get("market") or "BTCUSD").upper()
            if wh not in {t["id"] for t in tg["where"]} or mk not in {m["sym"] for m in tg["markets"]}:
                return {"ok": False, "err": "where"}
            if wh == "acct:mine":
                wh = "acct:" + str(user.get("id"))
            r["plug"] = {"where": wh, "market": mk, "date": datetime.now(timezone.utc).strftime("%Y-%m-%d"), "status": "requested"}
    _robot_save(reg)
    return {"ok": True, "id": r["id"]}


ROBOT_TEST_MIN = 5          # one robot next to its parent on the 42-day bench, minutes (measured 4-5)


def robot_test(user, body):
    """the member starts the test of their robot; it joins the queue (one test at a time)"""
    reg = robot_reg()
    rob = reg.get("robots") or []
    r = next((x for x in rob if x.get("id") == body.get("id")), None)
    if not _robot_mine(user, r) or r.get("id") == "owl":
        return {"ok": False, "err": "not_yours"}
    if r.get("stage") in ("tested", "paper", "demo", "real") and body.get("again"):
        if r.get("retest"):
            return {"ok": True, "already": True}
        r["retest"] = True
        r["queued_at"] = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        _robot_save(reg)
        robot_runner_kick()
        return {"ok": True, "minutes": ROBOT_TEST_MIN}
    if r.get("stage") not in ("draft", "error"):
        return {"ok": False, "err": "state"}
    r["stage"] = "queued"
    r["queued_at"] = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    _robot_save(reg)
    robot_runner_kick()
    pos = [x["id"] for x in rob if x.get("stage") == "queued"].index(r["id"])
    return {"ok": True, "ahead": pos, "minutes": ROBOT_TEST_MIN * (pos + 1)}


# ---- 2026-10-25 (owner): the TESTS space - build, test on any recorded dates, follow the progress, see the proof ----
TICK_MANIFEST = os.path.join(os.path.dirname(DIR), "study", "ticks", "manifest.json")
BACKTEST_PROOF = os.path.join(DIR, "lab", "backtest_proof.json")


def _tests_data_window():
    """the recorded days a test can use (every broker tick of those days is on disk)"""
    try:
        m = json.load(open(TICK_MANIFEST, encoding="utf-8"))
        d = sorted(k for k, v in (m.get("days") or {}).items() if v.get("n"))
        return (d[0], d[-1]) if d else (None, None)
    except Exception:
        return (None, None)


def _test_summary(res):
    rb = (res or {}).get("robot") or {}
    if rb.get("net") is None:
        return None
    return {"net": rb.get("net"), "trades": rb.get("trades"), "wins": rb.get("wins"), "win_rate": rb.get("win_rate"),
            "dip": rb.get("cc_dd"), "h1": rb.get("first_half"), "h2": rb.get("later_half"), "pf": rb.get("profit_factor"),
            "best": rb.get("best"), "worst": rb.get("worst"), "streak": rb.get("max_loss_streak"),
            "curve": (rb.get("curve") or [])[-120:], "days": res.get("days"), "window": res.get("window_utc"),
            "when": str(res.get("generated_at") or "")[:16].replace("T", " "), "range": res.get("range"),
            "parent_net": ((res.get("parent_result") or {}).get("net")), "cap": float(res.get("balance") or 200)}


def _test_cap(body):
    """2026-10-25 (owner): the member picks the starting capital (200 $ by default, the account balance, or any amount)"""
    try:
        c = round(float(body.get("cap") or 200), 2)
    except Exception:
        c = 200.0
    return min(1000000.0, max(10.0, c))


def _member_balance(user):
    try:
        return round(float(json.load(open(os.path.join(DIR, "nest_data", user.get("id") + ".json"), encoding="utf-8")).get("balance") or 0), 2) or None
    except Exception:
        return None


def tests_overview(user, body):
    """every robot of this member (+ the Owl as the reference), its last full test, its date-range tests, the queue"""
    reg = robot_reg()
    rob = reg.get("robots") or []
    uid = user.get("id")
    mine = [r for r in rob if r.get("by_uid") == uid or (is_admin(user) and r.get("by_uid") in (None, "", uid))]
    mine = [r for r in mine if r.get("id") != "owl"]
    owl = next((r for r in rob if r.get("id") == "owl"), None)
    queued = [r["id"] for r in sorted([x for x in rob if x.get("stage") == "queued" or x.get("retest") or x.get("range_jobs")],
                                      key=lambda x: str(x.get("queued_at") or ""))]
    running = None
    try:
        lk = os.path.join(DIR, "robots", "runner.lock")
        running = os.path.exists(lk) and time.time() - os.path.getmtime(lk) < 3 * 3600
    except Exception:
        pass
    out = []
    for r in ([owl] if owl else []) + sorted(mine, key=lambda x: str(x.get("created") or ""), reverse=True):
        rid = r["id"]
        res = None
        try:
            res = json.load(open(os.path.join(DIR, "robots", "results", rid + ".json"), encoding="utf-8"))
        except Exception:
            pass
        if res is None and rid == "owl":
            # the Owl is the bench's parent: its newest Bitcoin run sits next to every robot tested against it
            try:
                _best = None
                for f in os.listdir(os.path.join(DIR, "robots", "results")):
                    if f.endswith(".json") and "@" not in f:
                        j = json.load(open(os.path.join(DIR, "robots", "results", f), encoding="utf-8"))
                        if j.get("parent") == "owl" and j.get("parent_result") and (_best is None or str(j.get("generated_at")) > str(_best.get("generated_at"))):
                            _best = j
                if _best:
                    res = dict(_best, robot=_best["parent_result"], parent_result=None)
            except Exception:
                pass
        rng = []
        try:
            for f in sorted(os.listdir(os.path.join(DIR, "robots", "results", "ranges"))):
                if f.startswith(rid + "__") and f.endswith(".json"):
                    j = json.load(open(os.path.join(DIR, "robots", "results", "ranges", f), encoding="utf-8"))
                    rng.append({"range": j.get("range"), "error": j.get("error"), "test": _test_summary(j)})
        except Exception:
            pass
        pend = [{"from": j.get("from"), "to": j.get("to"), "at": j.get("at"), "cap": float(j.get("cap") or 200)} for j in (r.get("range_jobs") or [])]
        # 2026-10-25 (owner: merge the Zone de test here): the same robot on other markets of the member's broker
        mk = []
        try:
            for f in os.listdir(os.path.join(DIR, "robots", "results")):
                if f.startswith(rid + "@") and f.endswith(".json"):
                    j = json.load(open(os.path.join(DIR, "robots", "results", f), encoding="utf-8"))
                    t = _test_summary(j)
                    if t:
                        sy = j.get("market") or f[len(rid) + 1:-5]
                        lk = None
                        try:
                            lk = (_luck_of(rid, sy) or {}).get("state")
                        except Exception:
                            pass
                        mk.append({"sym": sy, "name": j.get("market_name") or sy, "test": t, "luck": lk,
                                   "per30": round(float(t["net"]) * 30.0 / max(1.0, float(t.get("days") or 30)), 2)})
            if r.get("test") is not None or res:
                pass
        except Exception:
            pass
        if res and _test_summary(res):
            _tb = _test_summary(res)
            lkb = None
            try:
                lkb = (_luck_of(rid, "BTCUSD") or {}).get("state")
            except Exception:
                pass
            mk.append({"sym": "BTCUSD", "name": "Bitcoin", "test": _tb, "luck": lkb,
                       "per30": round(float(_tb["net"]) * 30.0 / max(1.0, float(_tb.get("days") or 30)), 2)})
        mk.sort(key=lambda x: -x["per30"])
        mjobs = [{"sym": q.get("sym"), "state": q.get("state"), "at": q.get("at"), "first_build": q.get("first_build"), "cap": float(q.get("cap") or 200)}
                 for q in _mq_load() if q.get("rid") == rid and q.get("state") in ("queued", "building", "testing")]
        state = ("queued" if (r.get("stage") == "queued" or r.get("retest") or pend) else r.get("stage") or "draft")
        if state != "queued" and any(q.get("rid") == rid and q.get("state") in ("queued", "building", "testing") for q in _mq_load()):
            state = "queued"
        pos = queued.index(rid) if rid in queued else None
        out.append({"id": rid, "name": r.get("name_fr") or r.get("name") or rid, "market": r.get("market") or "BTCUSD",
                    "ref": rid == "owl", "state": state, "queued_at": r.get("queued_at"), "ahead": pos,
                    "eta_min": (ROBOT_TEST_MIN * ((pos or 0) + 1)) if pos is not None else None,
                    "test": _test_summary(res), "ranges": rng[-8:], "pending": pend, "markets": mk, "market_jobs": mjobs})
    a, b = _tests_data_window()
    return {"ok": True, "robots": out, "data_from": a, "data_to": b, "running": bool(running), "test_min": ROBOT_TEST_MIN,
            "balance": _member_balance(user), "admin": bool(is_admin(user))}


def test_range(user, body):
    """a test of one of this member's robots on chosen dates (inside the recorded window)"""
    reg = robot_reg()
    rob = reg.get("robots") or []
    r = next((x for x in rob if x.get("id") == body.get("id")), None)
    if not (r and (r.get("id") == "owl" and is_admin(user) or _robot_mine(user, r))):
        return {"ok": False, "err": "not_yours"}
    a, b = str(body.get("from") or "")[:10], str(body.get("to") or "")[:10]
    lo, hi = _tests_data_window()
    if not (re.match(r"^\d{4}-\d{2}-\d{2}$", a) and re.match(r"^\d{4}-\d{2}-\d{2}$", b)) or a > b:
        return {"ok": False, "err": "dates"}
    if lo and (a < lo or b > hi):
        return {"ok": False, "err": "outside", "data_from": lo, "data_to": hi}
    cap = _test_cap(body)
    jobs = [j for j in (r.get("range_jobs") or []) if not (j.get("from") == a and j.get("to") == b and float(j.get("cap") or 200) == cap)]
    if len(jobs) >= 4:
        return {"ok": False, "err": "too_many"}
    jobs.append({"from": a, "to": b, "cap": cap, "at": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")})
    r["range_jobs"] = jobs
    r.setdefault("queued_at", jobs[-1]["at"])
    _robot_save(reg)
    robot_runner_kick()
    return {"ok": True, "minutes": ROBOT_TEST_MIN}


def test_cancel(user, body):
    """2026-10-25 (owner: "I can't stop a test from the UI"): withdraw a date-range test (or a queued full test).
    A test already running finishes its few minutes, but its result is thrown away (the runner checks before writing)."""
    reg = robot_reg()
    rob = reg.get("robots") or []
    r = next((x for x in rob if x.get("id") == body.get("id")), None)
    if not (r and (r.get("id") == "owl" and is_admin(user) or _robot_mine(user, r))):
        return {"ok": False, "err": "not_yours"}
    if body.get("sym"):
        # 2026-10-25 (owner: "once we launch the test no more way to stop it?"): a test on another market.
        # Queued: it never starts. Preparing or testing: the runner drops it at its next step / before writing.
        sym, cap = str(body.get("sym")), _test_cap(body)
        q = _mq_load()
        hit = [x for x in q if x.get("rid") == r["id"] and x.get("sym") == sym and float(x.get("cap") or 200) == cap
               and x.get("state") in ("queued", "building", "testing")]
        if not hit:
            return {"ok": False, "err": "gone"}
        for x in hit:
            x["state"] = "cancelled"
            x["cancelled_at"] = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        json.dump(q, open(ROBOT_MQ + ".tmp", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
        os.replace(ROBOT_MQ + ".tmp", ROBOT_MQ)
        return {"ok": True}
    a, b = str(body.get("from") or "")[:10], str(body.get("to") or "")[:10]
    if a and b:
        before = len(r.get("range_jobs") or [])
        cap = _test_cap(body)
        r["range_jobs"] = [j for j in (r.get("range_jobs") or []) if not (j.get("from") == a and j.get("to") == b and float(j.get("cap") or 200) == cap)]
        if len(r["range_jobs"]) == before:
            return {"ok": False, "err": "gone"}
    else:
        if r.get("retest"):
            r.pop("retest", None)
        elif r.get("stage") == "queued":
            r["stage"] = "draft"
        else:
            return {"ok": False, "err": "gone"}
    _robot_save(reg)
    return {"ok": True}


