def _subjects_today(uid):
    try:
        _rc()
        import kino_spark as _KSs
        now = time.time()
        T = [x for x in (_KSs._u(_KSs._load(), uid).get("topics") or []) if now - float(x.get("t") or 0) < 86400]
        if not T:
            return ""
        return "SUBJECTS HE ALREADY RAISED ON HIS OWN TODAY (with the time): " + " | ".join(
            "%s: %s" % (time.strftime("%H:%M", time.gmtime(float(x["t"]))), str(x.get("text") or x.get("key") or "")[:90].replace("\n", " ")) for x in T[-14:])
    except Exception:
        return ""


def _judge_providers(c, m):
    """2026-10-24: the room the judge reads - the ledgers and the member's own words, assembled by code"""
    uid = c.get("uid")
    P = {}
    try:
        P["state"] = lambda: _state_text(uid, c)
        P["jobs"] = lambda: __import__("kino_deed").jobs_block(c)
        P["constraints"] = lambda: __import__("kino_ear").constraints_block(uid, c.get("lang") or "fr")
        P["told"] = lambda: __import__("kino_voice").told_block(uid, c.get("lang") or "fr")
        P["topics"] = lambda: _subjects_today(uid)
        P["feedback"] = lambda: __import__("kino_feedback").block(uid)
        P["recent_other"] = lambda: [tx for t_, tx in _recent_ai_texts(uid, 18) if not any(mm.get("text") == tx for mm in (c.get("msgs") or [])[-40:])]
        P["local_hour"] = _local_hour(uid)
        P["hours"] = _their_hours_text(uid)          # 2026-10-24: the judge closed a lively chat at "23 h" = this member's busiest hour
        P["self_said"] = lambda: __import__("kino_said").block(16)      # 2026-10-25: what he has said about himself stays true
        _seen = time.time() - _LAST_SEEN.get(uid, 0)
        P["presence"] = ("in the app right now" if _seen < 120 else "seen %d min ago" % (_seen // 60) if _seen < 86400 else "away")
        if c.get("robot"):
            P["check_state"] = _check_state(c, _user_by_id(uid))
        try:
            _nd = json.load(open(os.path.join(DIR, "nest_data", uid + ".json"), encoding="utf-8"))
            _ol = _nd.get("open_list") or []
            P["fresh"] = "THEIR ACCOUNT NOW: balance %.2f $, today %+.2f $, week %+.2f $; open trades: %s" % (
                float(_nd.get("balance") or 0), float(_nd.get("today") or 0), float(_nd.get("week") or 0),
                "; ".join("%s %s at %s now %+.2f $" % ("SELL" if str(x.get("d")) == "V" else "BUY", x.get("sym") or "BTCUSD", x.get("e"), float(x.get("pl") or 0)) for x in _ol[:3]) or "none")
        except Exception:
            pass
        if m.get("correction") or m.get("fix"):
            P["target"] = next((x for x in reversed(c.get("msgs") or []) if x.get("role") == "ai" and x.get("text") and not x.get("correction") and not x.get("fix")), None)
    except Exception:
        pass
    return P


def _named_test_watch(cid, uid, rid, name, t0):
    """a named robot's test (not the chat's): poll the registry up to 60 min; when tested_at moves past the launch, close the job,
    post the figures as a system line and let Kino tell it (event)"""
    import calendar as _cal
    for _ in range(120):
        time.sleep(30)
        try:
            r = next((x for x in robot_reg().get("robots") or [] if x.get("id") == rid), None)
            ta = str((r or {}).get("tested_at") or "")
            if ta and _cal.timegm(time.strptime(ta[:19], "%Y-%m-%dT%H:%M:%S")) >= t0 - 60:
                try:
                    j = json.load(open(os.path.join(DIR, "robots", "results", rid + ".json"), encoding="utf-8")).get("robot") or {}
                except Exception:
                    j = {}
                __import__("kino_deed").finish(cid, "test", "done", "")
                en = False
                try:
                    en = (json.load(open(_chat_path(cid), encoding="utf-8")).get("lang") == "en")
                except Exception:
                    pass
                line = ("Result for %s: %+.2f $ over %s trades, %d%% won, worst dip %.0f $." if en else "Résultat pour %s : %+.2f $ sur %s trades, %d %% gagnés, pire creux %.0f $.") % (
                    name, float(j.get("net") or 0), j.get("trades"), round(100 * float(j.get("win_rate") or 0)), float(j.get("cc_dd") or 0))
                _chat_mut(cid, lambda cc: _chat_msg(cc, "sys", text=line))
                _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1
                threading.Thread(target=_chat_quick, args=(cid, _user_by_id(uid), "TEST RESULT ARRIVED for the robot '%s' (%s): %s It is %s. Tell them in one or two lines with your "
                                                                              "take, the figures exactly as given; close your bet on it if you made one (resolved)." % (
                                                                                  name, rid, line, "YOUR OWN robot" if "Kino" in name else "their robot")),
                                 kwargs={"notify": True}, daemon=True).start()
                return
        except Exception:
            pass
    try:
        __import__("kino_deed").finish(cid, "test", "failed", "no result after 60 min")
    except Exception:
        pass


def _deed_do(cid, uid, todo):
    """2026-10-24 (engine 2): the actions a bubble claimed without a job behind them - started once the bubble is saved"""
    try:
        H = _commit_H()
        c = H["chat"](cid) or {}
        for k in todo:
            if k == "test":
                _t = c.get("test") or {}
                if _t.get("state") in ("queued", "running"):
                    continue                      # the reply's own act / the regex already queued it
                try:                              # 2026-10-24: a test done in the last 6 h on the same robot is not re-run (13:17 re-ran a 12:48 test)
                    import calendar as _cal
                    _at = _cal.timegm(time.strptime(str(_t.get("at") or "")[:19], "%Y-%m-%dT%H:%M:%S"))
                    if _t.get("state") == "done" and time.time() - _at < 6 * 3600 and _t.get("rev") == c.get("rev"):
                        continue
                except Exception:
                    pass
                H["act_test"](cid, uid)
            elif isinstance(k, str) and k.startswith("test:"):   # 2026-10-24: the test of a NAMED robot (theirs or Kino's own), not the chat's
                _nm = k[5:].strip().lower()
                _u = _user_by_id(uid)
                _rid = None
                for r_ in (_state_data(uid, c).get("robots") or []):
                    if _nm and (_nm == str(r_.get("name") or "").lower() or _nm in str(r_.get("name") or "").lower()):
                        _rid = r_["id"]
                        break
                if not _rid:
                    __import__("kino_deed")._log(cid, "TEST_NAME_UNKNOWN", k)
                    continue
                if _rid == c.get("robot_id"):
                    H["act_test"](cid, uid)
                    continue
                try:
                    _en = c.get("lang") == "en"
                    _nmf = next((r_.get("name") for r_ in _state_data(uid, c).get("robots") or [] if r_["id"] == _rid), _rid)
                    _tr = robot_test(_u, {"id": _rid, "again": True})
                    if _tr.get("ok"):
                        __import__("kino_deed").start(uid, cid, "test", _nmf)
                        _chat_mut(cid, lambda cc: _chat_msg(cc, "test", text=(("Test started for %s: about %d minutes. I'll tell you what it gives." % (_nmf, int(_tr.get("minutes") or 5))) if _en
                                                                             else ("Test lancé pour %s : environ %d minutes. Je te dis ce que ça donne." % (_nmf, int(_tr.get("minutes") or 5))))))
                        # 2026-10-24 16:10: the Nasdaq test finished at 15:11 and the ledger still said "queued since 67 min" at 16:18 - a
                        # named robot's result never reaches the chat (result cards are only for the chat's robot). A watcher closes the job
                        # and brings the figures in as an event Kino announces.
                        threading.Thread(target=_named_test_watch, args=(cid, uid, _rid, _nmf, time.time()), daemon=True).start()
                    else:
                        __import__("kino_deed").start(uid, cid, "test", _nmf, state="failed", err=str(_tr.get("err") or "")[:60])
                        _chat_mut(cid, lambda cc: _chat_msg(cc, "sys", text=(("The test of %s could not start (%s)." % (_nmf, _tr.get("err"))) if _en
                                                                            else ("Le test de %s n'a pas pu partir (%s)." % (_nmf, _tr.get("err"))))))
                except Exception as e:
                    __import__("kino_deed")._log(cid, "TEST_NAME_ERROR", "%s %s" % (k, type(e).__name__))
            elif k == "luck":                     # the judge: the luck test of this chat's robot (same path as the build turn's act)
                if c.get("robot_id"):
                    _u = _user_by_id(uid)
                    try:
                        lr = robot_control(_u, {"id": c["robot_id"], "sym": _chat_market(c)})
                        _en = c.get("lang") == "en"
                        if lr.get("ok"):
                            _chat_mut(cid, lambda cc: _chat_msg(cc, "sys", text=("Luck test queued: 100 random robots on the same days." if _en else
                                                                                  "Test de chance en file : 100 robots au hasard sur les mêmes jours.")))
                        else:
                            _why = {"not_winning": ("its test there is not positive with 20+ trades", "son test là-bas n'est pas positif avec 20 trades ou plus"),
                                    "busy": ("another luck test is running in the nest", "un autre test de chance tourne dans le nid"),
                                    "done": ("it already has one", "il en a déjà un"), "market": ("that market is not prepared", "ce marché n'est pas préparé")}.get(
                                lr.get("err"), (str(lr.get("err") or "?"), str(lr.get("err") or "?")))
                            _chat_mut(cid, lambda cc: _chat_msg(cc, "sys", text=("No luck test: %s." % _why[0]) if _en else ("Pas de test de chance : %s." % _why[1])))
                    except Exception:
                        pass
            elif k == "fires":                    # 2026-10-24: the robot changed, no moments card yet -> post it
                _u = _user_by_id(uid)
                if _check_state(c, _u) == "none":
                    _r = chat_fires(_u, {"id": cid}) or {}
                    if _r.get("ok"):
                        _en = c.get("lang") == "en"
                        _chat_mut(cid, lambda cc: _chat_msg(cc, "sys", text=(
                            "Before the test: the last 5 moments where your robot would have traded are below - ✅ or ❌ under each one, then it runs."
                            if _en else "Avant le test : les 5 derniers moments où ton robot aurait tradé sont juste en dessous - ✅ ou ❌ sous chacun, puis il part.")))
            elif k == "build":
                H["build"](cid, uid)
            elif k == "ghost":
                if c.get("robot"):
                    _kino_act(cid, _user_by_id(uid), "ghost", c.get("lang") == "en")
    except Exception:
        pass


