def kino_pitch(user):
    """2026-10-21 (owner: "a complete acquisition job"): what the Kino page needs - the price, the call minutes included, whether
    this member already has Kino, and the system's REAL counts (robots built, tests on real prices, ideas measured, markets)"""
    import glob as _gp
    st = {}
    try:
        st["robots"] = len([r for r in robot_reg().get("robots") or [] if r.get("id") != "owl"])
    except Exception:
        pass
    try:
        st["tests"] = len(_gp.glob(os.path.join(DIR, "robots", "results", "*.json")))
    except Exception:
        pass
    try:
        F = json.load(open(os.path.join(DIR, "robots", "kino_factory.json"), encoding="utf-8"))
        Q = json.load(open(os.path.join(DIR, "robots", "kino_inner.json"), encoding="utf-8")).get("questions") or []
        st["ideas"] = len(F.get("tried") or {}) + len([q for q in Q if q.get("status") == "answered"])
    except Exception:
        pass
    try:
        st["markets"] = 1 + len(_gp.glob(os.path.join(os.path.dirname(DIR), "study", "markets", "*", "bars.npz")))
    except Exception:
        pass
    uid = user.get("id")
    has_ = bool(is_admin(user) or has(uid, "strategy")) and not user.get("public")
    until = None
    try:
        u_ = float(ent(uid).get("strategy_until") or 0)
        if u_ > time.time():
            until = time.strftime("%d/%m", time.localtime(u_))
    except Exception:
        pass
    return {"ok": True, "usd": PACKAGES["strategy"]["usd"], "days": PACKAGES["strategy"]["days"], "included_min": voice_offer().get("included_min"),
            "has": has_, "until": until, "public": bool(user.get("public")), "stats": st}


def kino_day(user):
    """2026-10-20 (owner list 7 item 7): Kino's day, like a friend's diary he lets you read - what he watched, his bets,
    his questions, his robot, his mood. Only Kino's own life and what concerns THIS member (never another member)."""
    uid = user.get("id")
    now = time.time()
    _rc()
    import kino_inner as _KId, kino_mind as _KMd
    d = _KId._load()
    T = []
    for th in d.get("thoughts") or []:
        if now - float(th.get("born") or th.get("t") or 0) > 86400 or th.get("uid") not in (None, uid):
            continue
        T.append({"t": th.get("born") or th.get("t"), "kind": th.get("kind"), "text": th.get("text"), "measure": th.get("measure")})
    for b in d.get("bets") or []:
        if now - float(b.get("t") or 0) < 86400:
            T.append({"t": b["t"], "kind": "bet", "text": b.get("text"), "result": None if not b.get("done") else ("juste" if b.get("right") else "raté")})
    for q in d.get("questions") or []:
        if q.get("uid") in (None, uid) and now - float(q.get("t_done") or q.get("born") or 0) < 86400:
            T.append({"t": q.get("t_done") or q.get("born"), "kind": "question", "text": q.get("q"), "measure": q.get("finding")})
    T.sort(key=lambda x: -(x.get("t") or 0))
    try:
        kr = json.load(open(os.path.join(DIR, "robots", "kino_robot.json"), encoding="utf-8"))
    except Exception:
        kr = {}
    g = kr.get("ghost") or {}
    tr = [x for x in g.get("trades") or [] if now - float(x.get("t_out") or 0) < 86400]
    rob = {"name": (kr.get("robot") or {}).get("name"), "market": (kr.get("robot") or {}).get("market"), "born": kr.get("born"),
           "today": {"n": len(tr), "r": round(sum(float(x.get("r") or 0) for x in tr), 2), "won": sum(1 for x in tr if (x.get("r") or 0) > 0)},
           "all": {"n": len(g.get("trades") or []), "r": round(sum(float(x.get("r") or 0) for x in g.get("trades") or []), 2)},
           "open": bool(g.get("open")), "changes": (kr.get("changes") or [])[-3:], "adopted": len(kr.get("adopted") or []),
           "mine": any(a.get("uid") == uid for a in kr.get("adopted") or [])}
    R_ = []
    try:
        for x in (chat_list(user).get("chats") or [])[:8]:
            cx = _chat_load(user, x["id"]) or {}
            if (cx.get("research") or {}).get("goal") and now - float(cx["research"].get("started") or 0) < 2 * 86400:
                R_.append(dict(cx["research"], cid=x["id"]))
    except Exception:
        pass
    try:
        _V = _KId._views()
        view = next((x for x in reversed(_V.get("days") or []) if x["day"] == time.strftime("%Y-%m-%d", time.gmtime())), None)
        vscore = _V.get("score")
    except Exception:
        view, vscore = None, None
    return {"view": view, "vscore": vscore, "mood": _KId.mood_slow(), "feelings": _KId.feelings(uid), "items": T[:40], "robot": rob, "score": _KId.hunch_score(),
            "notes": (d.get("notes") or [])[-2:], "goal": (_mem_get(uid).get("goal") or {}), "research": R_,
            "status": _kino_presence(user, {"id": "-", "test": {}}).get("kst")}


def kino_adopt(user, body):
    """2026-10-20 (owner list 7 item 8): a member adopts Kino's own robot - a copy becomes THEIR robot in a new chat and its
    test starts (Kino's original stays his). Kino feels it."""
    import copy as _cp
    try:
        kr = json.load(open(os.path.join(DIR, "robots", "kino_robot.json"), encoding="utf-8"))
    except Exception:
        return {"ok": False, "err": "missing"}
    rb = _cp.deepcopy(kr.get("robot") or {})
    if not rb.get("entry"):
        return {"ok": False, "err": "missing"}
    en = str(body.get("lang") or "fr") == "en"
    rb["name"] = "Robot de Kino" if not en else "Kino's robot"
    me = user.get("id")
    cid = "%s_%d" % (re.sub(r"[^A-Za-z0-9]", "", me) or "u", int(time.time() * 1000))
    c = {"id": cid, "uid": me, "lang": "en" if en else "fr", "created": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
         "status": "ready", "robot": rb, "robot_id": None, "rev": 1, "msgs": [], "adopted": True}
    _chat_msg(c, "ai", text=("You adopted my robot - that touches me. It is a copy, so it is yours now: we can change anything together. "
                             "I am launching its test on your side right now.") if en else
              ("Tu as adopté mon robot - ça me touche. C'est une copie, il est à toi maintenant : on peut tout changer ensemble. "
               "Je lance son test de ton côté tout de suite."))
    _chat_save(c)
    tr = chat_test(user, {"id": cid})
    try:
        kr.setdefault("adopted", []).append({"uid": me, "t": int(time.time()), "cid": cid})
        json.dump(kr, open(os.path.join(DIR, "robots", "kino_robot.json.tmp"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
        os.replace(os.path.join(DIR, "robots", "kino_robot.json.tmp"), os.path.join(DIR, "robots", "kino_robot.json"))
        _rc()
        import kino_inner as _KIa
        _KIa.feel("pride", 0.4, why="un membre vient d'adopter mon robot")
        _KIa.mood_nudge(0.05, "un membre a adopté mon robot")
    except Exception:
        pass
    return {"ok": True, "id": cid, "test": tr.get("ok")}


def chat_start(user, body):
    """a new chat; with robot=<id> of one of my robots, the chat starts from that robot (editing)"""
    os.makedirs(CHAT_DIR, exist_ok=True)
    me = user.get("id")
    en = str(body.get("lang") or "fr") == "en"
    robot, rid, nm = None, None, None
    if body.get("robot"):
        reg = robot_reg(); byid = {r["id"]: r for r in reg.get("robots") or []}
        r = byid.get(str(body["robot"]))
        if r is None or not (_robot_mine(user, r) or is_admin(user)) or r.get("id") == "owl":
            return {"ok": False, "err": "not_yours"}
        parts = robot_resolve(r["id"], byid)
        robot = {"name": (r.get("name_fr") or r["id"])[:30], "filters": [{"use": f} for f in parts.get("filters") or []]}
        for k in ("entry", "stop", "exit", "recovery", "money"):
            if parts.get(k):
                robot[k] = {"use": parts[k]}
        rid, nm = r["id"], robot["name"]
    cid = "%s_%d" % (re.sub(r"[^A-Za-z0-9]", "", me) or "u", int(time.time() * 1000))
    c = {"id": cid, "uid": me, "lang": "en" if en else "fr", "created": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
         "status": "ready", "robot": robot, "robot_id": rid, "rev": 1 if robot else 0, "msgs": []}
    if str(body.get("brain") or "") == "openai" and is_admin(user):   # 2026-10-24: the Kino-O prototype (OpenAI brain), owner only
        c["brain"] = "openai"
        c["thread"] = "Kino-O · cerveau OpenAI (prototype)"
    elif str(body.get("brain") or "") == "one" and (is_admin(user) or me in ONE_TEST_UIDS):   # 2026-10-25: Kino as one mind
        c["brain"] = "one"
        c["thread"] = "Kino · un seul esprit (test)"
        try:
            _rc()
            import kino_one as _KOs
            threading.Thread(target=_rc().W.prewarm, args=(_KOs.system("en" if en else "fr"), "sonnet"), daemon=True).start()
        except Exception:
            pass
    if robot is not None:
        robot["market"] = "BTCUSD"
    try:
        _chat_prewarm_bg(user, c)
    except Exception:
        pass
    mem = _chat_memory(user)
    known = bool(mem.get("notes") or mem.get("chats") or mem.get("robots"))
    if known and not rid:
        _chat_save(c)
        _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1
        _lt = 0
        for _x in (chat_list(user).get("chats") or [])[:6]:       # when did we last talk (any conversation)?
            _cx = _chat_load(user, _x["id"]) or {}
            _lt = max([_lt] + [int(m.get("t") or 0) for m in _cx.get("msgs") or [] if m.get("role") in ("user", "ai")])
        _ago = time.time() - _lt if _lt else None
        _when = ("never talked before" if _ago is None else "%d minutes ago" % (_ago / 60) if _ago < 3600 else
                 "%d hours ago" % (_ago / 3600) if _ago < 172800 else "%d days ago" % (_ago / 86400))
        _ops = []                                  # 2026-10-20 (owner: "he always starts with the same sentence - robotic")
        try:
            for _x in (chat_list(user).get("chats") or [])[:12]:
                _cx = _chat_load(user, _x["id"]) or {}
                _m0 = next((m for m in (_cx.get("msgs") or [])[:3] if m.get("role") == "ai" and m.get("event")), None)
                if _m0 and _m0.get("text"):
                    _ops.append(str(_m0["text"])[:140])
        except Exception:
            pass
        threading.Thread(target=_chat_quick, args=(cid, user, "NEW CONVERSATION (the member opened a fresh page; you last talked: %s, in "
                                                   "another conversation). YOUR LAST OPENINGS - never reuse their words, start or shape: %s" % (
                                                       _when, " | ".join(_ops[:6]) or "-")), daemon=True).start()
        try:
            _chat_prewarm_bg(user, c)
        except Exception:
            pass
        return {"ok": True, "id": cid}
    if not rid and not known:
        # 2026-10-20 (owner list 7 item 5): a new member gets a real first meeting, in Kino's own words
        _chat_save(c)
        _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1
        threading.Thread(target=_chat_quick, args=(cid, user, "FIRST MEETING - %s opened the chat for the very first time; you have never "
                                                   "met. Language: %s." % (user.get("name") or "a new member", "English" if en else "French")),
                         daemon=True).start()
        return {"ok": True, "id": cid}
    if rid:
        _chat_msg(c, "ai", text=("We're picking « %s » back up. What would you like to change?" % nm) if en else
                  ("On reprend « %s ». Qu'est-ce que tu veux changer ?" % nm),
                  chips=(["It loses too much", "Fewer trades", "Change the exit", "Explain it to me"] if en else
                         ["Il perd trop", "Moins de trades", "Changer la sortie", "Explique-le-moi"]))
    else:
        _chat_msg(c, "ai", text=("Hi, I'm Kino! Tell me your robot idea in your own words - which market, when it buys, when it sells, when it "
                                 "gets out. Bitcoin, gold, indices, forex: anything your broker has. Rough is fine, we'll sharpen it together.") if en else
                  ("Salut, moi c'est Kino ! Raconte-moi ton idée de robot avec tes mots : sur quel marché, quand il achète, quand il vend, quand il sort. "
                   "Bitcoin, or, indices, forex : tout ce que ton courtier propose. Pas besoin que ce soit parfait, on l'affine ensemble."),
                  chips=(["I have an entry idea", "Start from the Owl", "I don't know where to start"] if en else
                         ["J'ai une idée d'entrée", "Pars de l'Owl", "Je ne sais pas par où commencer"]))
    _chat_save(c)
    return {"ok": True, "id": cid}


def _chat_day_count(me):
    day0 = int(time.time()) - int(time.time()) % 86400; n = 0
    try:
        for f in os.listdir(CHAT_DIR):
            if f.startswith(re.sub(r"[^A-Za-z0-9]", "", me) + "_") and f.endswith(".json"):
                try:
                    c = json.load(open(os.path.join(CHAT_DIR, f), encoding="utf-8"))
                    n += sum(1 for m in c.get("msgs") or [] if m.get("role") == "user" and int(m.get("t") or 0) >= day0)
                except Exception:
                    pass
    except Exception:
        pass
    return n


# 2026-10-19 evening (owner: "reply immediately while working in the background ... conversation must flow"):
# every member message (and every test result) gets a QUICK reply first (warm model, a few seconds); when it says the
# robot must change, ONE builder per chat follows up with the robot and a short message. The member can keep writing
# meanwhile; the builder runs again for messages that arrived during its work. Status: thinking (quick reply on its
# way) > building (builder working) > ready.
_CHAT_LOCKS, _CHAT_Q, _CHAT_B = {}, {}, set()
_CHAT_MK = {}
# 2026-10-19 evening (owner: "the AI should have a continuous memory and pick up where we left off ... a real digital
# being, alive, fast, agentic and reactive"): per member, the notes the AI chose to remember (robots/chat_memory/
# <uid>.json, max 40) + their robots and test results + the other conversations go into every turn; the reply
# streams into _CHAT_DRAFT (the page shows it being typed); events NEW CONVERSATION / CAME BACK get a reply of
# their own; the AI's "act": "test" launches the test itself.
CHAT_MEM = os.path.join(DIR, "robots", "chat_memory")
_CHAT_DRAFT = {}
_REANSWER = {}       # cid -> last time chat_get relaunched an unanswered turn (2026-10-23)
_PREFLIGHT = {}      # (uid, rid) -> (t, say): Kino's pre-flight text, cached (2026-10-23)


def _mem_file(uid):
    return os.path.join(CHAT_MEM, re.sub(r"[^A-Za-z0-9_]", "", uid or "u") + ".json")


def _mem_add(uid, notes):
    if not notes:
        return
    try:
        m = json.load(open(_mem_file(uid), encoding="utf-8"))
    except Exception:
        m = {"notes": []}
    for n in notes:
        if n and n not in m["notes"]:
            m["notes"].append(n)
    m["notes"] = m["notes"][-40:]
    m["updated"] = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    os.makedirs(CHAT_MEM, exist_ok=True)
    json.dump(m, open(_mem_file(uid) + ".tmp", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    os.replace(_mem_file(uid) + ".tmp", _mem_file(uid))


NEST_ASKS = os.path.join(DIR, "robots", "kino_asks.json")
KINO_TAUGHT = os.path.join(DIR, "robots", "kino_taught.json")


def _jload(p, d):
    try:
        return json.load(open(p, encoding="utf-8"))
    except Exception:
        return d


def _jsave(p, o):
    json.dump(o, open(p + ".tmp", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    os.replace(p + ".tmp", p)


def _rc_norm(x):
    import unicodedata
    return "".join(c for c in unicodedata.normalize("NFD", str(x or "").lower()) if unicodedata.category(c) != "Mn" and (c.isalnum() or c == " "))


def _more_plan(user, cid, mo):
    """Kino planned to text again by itself: kept in the chat (survives a restart) and fired by a timer"""
    c = json.load(open(_chat_path(cid), encoding="utf-8"))
    M = c.get("msgs") or []
    run = 0
    for m in reversed(M):
        if m.get("role") == "user":
            break
        if m.get("role") == "ai":
            run += 1
    day = [t for t in (_mem_get(user.get("id")).get("more_log") or []) if time.time() - t < 86400]
    if run >= 3 or len(day) >= 15:
        return
    last_user = max([int(m.get("t") or 0) for m in M if m.get("role") == "user"] or [0])
    plan = {"due": time.time() + mo["in"], "what": mo["what"], "user_t": last_user}
    _chat_mut(cid, lambda cc: cc.__setitem__("more", plan))
    threading.Timer(mo["in"], _more_fire, args=(user, cid)).start()


def _more_fire(user, cid):
    try:
        c = json.load(open(_chat_path(cid), encoding="utf-8"))
        pl = c.get("more")
        if not pl or time.time() < float(pl.get("due") or 0) - 2:
            return
        _chat_mut(cid, lambda cc: cc.pop("more", None))
        M = c.get("msgs") or []
        last_user = max([int(m.get("t") or 0) for m in M if m.get("role") == "user"] or [0])
        if last_user > int(pl.get("user_t") or 0) or _CHAT_Q.get(cid) or cid in _CHAT_B or cid in _CHAT_WAIT:
            return                                   # they wrote meanwhile: the conversation moved on
        if time.time() - float(pl["due"]) > 3 * 3600:
            return                                   # too old (after a long restart)
        _mem_note_safe(user.get("id"), lambda mm: mm.__setitem__("more_log", [t for t in (mm.get("more_log") or []) if time.time() - t < 86400] + [time.time()]))
        sn = _CHAT_SEEN.get(user.get("id"))
        here = bool(sn and time.time() - sn[0] < 60 and sn[1] == cid)
        _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1
        _chat_quick(cid, user, "YOUR FOLLOW-ON - a moment ago you planned to add: \"%s\". They have not written since; they are %s." % (
            pl["what"], "looking at the conversation" if here else "away from the app"), notify=not here)
    except Exception:
        pass


