_STOP = set("dans pour avec mais plus tout tous cette comme quand alors donc sont elle elles nous vous leur leurs être avoir fait faire "
             "this that with from have what when then your their there they them will would could should about just like".split())


def _related_snippets(user, cid):
    """2026-10-20 (owner list 8 item 7): what they said on the same subject in their OTHER conversations (30 days) - so Kino
    links them like a friend who remembers ("tu disais la même chose il y a 3 jours...")"""
    me = user.get("id")
    try:
        c = json.load(open(_chat_path(cid), encoding="utf-8"))
    except Exception:
        return []
    last = " ".join(str(m.get("text") or "") for m in (c.get("msgs") or [])[-4:] if m.get("role") in ("user", "ai"))
    kw = set(w for w in re.findall(r"[a-zà-ÿ0-9]{4,}", last.lower()) if w not in _STOP)
    if len(kw) < 2:
        return []
    now = time.time()
    hits = []
    for f in os.listdir(CHAT_DIR):
        if not f.endswith(".json") or f[:-5] == cid or not f.startswith(re.sub(r"[^A-Za-z0-9]", "", me) + "_"):
            continue
        try:
            x = json.load(open(os.path.join(CHAT_DIR, f), encoding="utf-8"))
        except Exception:
            continue
        if x.get("uid") != me:
            continue
        for m in x.get("msgs") or []:
            if m.get("role") not in ("user", "ai") or now - int(m.get("t") or 0) > 30 * 86400:
                continue
            t = str(m.get("text") or "")
            sc = len(kw & set(re.findall(r"[a-zà-ÿ0-9]{4,}", t.lower())))
            if sc >= 3 or (sc >= 2 and m["role"] == "user"):
                hits.append((sc + (1 if m["role"] == "user" else 0), int(m.get("t") or 0), (x.get("robot") or {}).get("name") or "?", m["role"], t))
    hits.sort(key=lambda h: (-h[0], -h[1]))
    out, seen = [], set()
    for sc, t, nm, role, txt in hits:
        if nm in seen and len(out) >= 2:
            continue
        seen.add(nm)
        out.append("%s, chat '%s', %s: %s" % (time.strftime("%d/%m", time.gmtime(t)), nm, "they said" if role == "user" else "you said", txt[:220]))
        if len(out) >= 3:
            break
    return out


def _luck_rows():
    """the luck-test queue with each one's state (study/luck)"""
    out = []
    try:
        sd = os.path.join(os.path.dirname(DIR), "study", "luck")
        for e in json.load(open(os.path.join(sd, "queue.json"), encoding="utf-8"))[-20:]:
            st = {}
            try:
                st = json.load(open(os.path.join(sd, "%s_%s.status.json" % (e["rid"], e["sym"])), encoding="utf-8"))
            except Exception:
                pass
            done = st.get("state") in ("pass", "fail", "data_changed") and str(st.get("updated") or "") >= e["at"]
            out.append({"rid": e["rid"], "sym": e["sym"], "state": st.get("state") if (done or st.get("state") == "running") else "queued",
                        "n": st.get("n"), "beats": st.get("beats"), "eta_h": st.get("eta_h"), "updated": st.get("updated")})
    except Exception:
        pass
    return out


_WAIT_RE = re.compile(r"(dès qu(e|'il|'ils|'elle)[^.?!]{0,60}(tombe|sort|est sorti|sont sortis|est là|sont là|est prêt|fini)|"
                      r"(test|résultat|chiffre)[^.?!]{0,60}(sorti|tombé|tombe|sort)|revérifier le test|when (it|the test|the result) (lands|is out))", re.I)
_NOTHING_NEW_RE = re.compile(r"(pas encore (de |sorti|tombé|là)|toujours pas|rien de neuf|aucun chiffre|n'est (toujours |pas )?(encore )?pas sorti|"
                             r"attend (encore|toujours|son tour)|prépare encore|still (nothing|waiting)|not out yet|nothing new)", re.I)


def _waiting_promise(text):
    """a promise that only waits for a test / result that is announced anyway when it lands"""
    return bool(_WAIT_RE.search(str(text or "")))


