def _chat_lock(cid):
    return _CHAT_LOCKS.setdefault(cid, threading.Lock())


_CHAT_WAIT, _CHAT_TYPING, _CHAT_PENDING = set(), {}, {}
_LAST_PROMISE_FIRE = {}      # cid -> when a promise reminder last fired (2026-10-23 23:33: four in 12 min, nine messages)


def _chat_status(cid):
    if _CHAT_Q.get(cid):
        return "thinking"
    if cid in _CHAT_WAIT:
        return "listening"            # 2026-10-19 (owner item 1): Kino waits for the member to finish their burst
    return "building" if cid in _CHAT_B else "ready"


_CTX = {}          # cid -> (t, pieces, owl, markets, memory, member) - prepared during the burst wait (2026-10-20 speed)


def _ctx_prefetch(user, cid):
    try:
        c = json.load(open(_chat_path(cid), encoding="utf-8"))
        _CTX[cid] = (time.time(), _chat_pieces(user), _ai_owl(), _chat_markets(user), _chat_memory(user, cid), _chat_member(user, c))
        _chat_prewarm(user, c, _CTX[cid][1:])
    except Exception:
        pass


_STABLE = {}       # uid -> (t, stable block) - 2026-10-23: the member's facts in the system prompt (cached by the API)


def _chat_prewarm(user, c, ctx=None):
    """2026-10-23 (cost): the warm pool is keyed by the whole system prompt, which now ends with this member's facts
    (robot_chat.stable_block). A key is warmed while they open or type, so a changed fact (a closed trade, a test result) is
    met by a warm process and not a 12 s cold start. The facts are rebuilt at most once a minute per member here."""
    uid = (user.get("id"), (c or {}).get("id"))          # the MARKETS block names the chat's market: one key per chat
    try:
        if ctx is None:
            x = _STABLE.get(uid)
            if x and time.time() - x[0] < 60:
                st = x[1]
            else:
                _STABLE[uid] = (time.time(), "")             # taken: a second caller meanwhile warms nothing
                ctx = (_chat_pieces(user), _ai_owl(), _chat_markets(user), _chat_memory(user, (c or {}).get("id")), _chat_member(user, c or {}))
        if ctx is not None:
            pieces, owl, markets, memory, member = ctx
            st = _rc().stable_block(member, owl, pieces, markets, _rc().chat_market(c or {}), (c or {}).get("lang") or "fr",
                                    memory, (user.get("id"), (c or {}).get("id")))
            _STABLE[uid] = (time.time(), st)
        if st:
            _rc().prewarm(st)
    except Exception:
        pass


def _chat_prewarm_bg(user, c):
    threading.Thread(target=_chat_prewarm, args=(user, c), daemon=True).start()


_CTX_T = {}        # cid -> the prefetch thread running now (2026-10-23 speed: ctx=2.3-12 s per reply in kino_timing.log)


def _ctx_get(user, cid, c):
    """the context prepared during the burst wait. 2026-10-23: the prefetch takes 2-5 s on the live box and the burst wait is
    0.9-1.8 s, so it was almost never ready - and everything was rebuilt here, in the member's wait, while the prefetch
    finished for nobody. Now this waits for the running prefetch (up to 6 s) before rebuilding."""
    x = _CTX.pop(cid, None)
    if x and time.time() - x[0] < 20:
        return x[1:]
    th = _CTX_T.get(cid)
    if th is not None and th.is_alive():
        th.join(6)
        x = _CTX.pop(cid, None)
        if x and time.time() - x[0] < 20:
            return x[1:]
    return (_chat_pieces(user), _ai_owl(), _chat_markets(user), _chat_memory(user, cid), _chat_member(user, c))


def _chat_listen(cid, user):
    """read a burst like a person: wait until the member stopped writing (2.5 s without a new message or a typing signal,
    20 s at most), then answer everything at once"""
    if cid in _CHAT_WAIT:
        return
    _CHAT_WAIT.add(cid)
    t0 = time.time()
    try:
        _c1 = json.load(open(_chat_path(cid), encoding="utf-8"))
    except Exception:
        _c1 = {}
    if _c1.get("brain") == "one":                     # 2026-10-25: the one mind's facts + memory, built while they finish typing
        threading.Thread(target=_one_prefetch, args=(user, cid), daemon=True).start()
    else:
        _CTX_T[cid] = threading.Thread(target=_ctx_prefetch, args=(user, cid), daemon=True)
        _CTX_T[cid].start()
    try:
        while time.time() - t0 < 20:
            c = json.load(open(_chat_path(cid), encoding="utf-8"))
            lu = max([int(m.get("t") or 0) for m in c.get("msgs") or [] if m.get("role") in ("user", "show", "image", "doc")] or [0])
            lt_ = str(((c.get("msgs") or [{}])[-1]).get("text") or "").strip()
            done_ = len(lt_) >= 12 and (lt_[-1:] in "?!.)" or ord(lt_[-1:] or " ") > 0x2600)     # it looks finished
            _vc = bool(((c.get("msgs") or [{}])[-1]).get("voice")) and _LIVE_CID.get(user.get("id")) == cid
            if time.time() - max(lu, _CHAT_TYPING.get(cid, 0)) >= (0.15 if _vc else 0.9 if done_ else 1.8):
                break
            time.sleep(0.25)
    except Exception:
        pass
    _CHAT_WAIT.discard(cid)
    try:
        _cl = json.load(open(_chat_path(cid), encoding="utf-8"))
        _lm = ((_cl.get("msgs") or [{}])[-1])
        if _lm.get("role") == "user" and _lm.get("voice") and _LIVE_CID.get(user.get("id")) == cid:
            _voice_brain(cid, user)                     # 2026-10-21: the call brain (fast), full brain only when needed
            return
    except Exception:
        pass
    _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1
    _chat_quick(cid, user)


