def _user_by_id(uid):
    return next((u for u in users() if u.get("id") == uid), {"id": uid})


def _promise_key(pn, what):
    """2026-10-24: 'creuser la paire euro-dollar pendant la nuit asiatique' and 'creuser la paire EUR/USD sur la nuit asiatique'
    are the same promise - the key is the existing one whose content words overlap half or more, else a new one"""
    words = set(w for w in re.findall(r"[a-z\u00e0-\u00ff]{4,}", str(what or "").lower()) if w not in ("pour", "dans", "avec", "pendant", "cette", "leur"))
    best, score = None, 0.0
    for k in (pn or {}):
        kw = set(k.split())
        if not kw or not words:
            continue
        sc = len(kw & words) / float(min(len(kw), len(words)))
        if sc > score:
            best, score = k, sc
    return best if (best and score >= 0.5) else " ".join(sorted(words))[:80]


def _commit_H():
    """2026-10-23 (Kino architecture review, engine 1): what the commitment ledger (robots/kino_commit.py) may do in the app"""
    def _work_add(cid, what, minutes):
        def f(cc):
            _rc()
            import kino_commit as _KC
            if any(_KC._same(x.get("what"), what) for x in cc.get("work") or []):
                return                                    # the regex promise catcher already keeps this one
            # 2026-10-23: the same promise re-made after a reminder is counted; after three the loop ends honestly (see YOUR PROMISE)
            _pn = cc.setdefault("promise_n", {})
            _pk = _promise_key(_pn, what)
            _pn[_pk] = int(_pn.get(_pk, 0)) + 1
            if len(_pn) > 20:
                for k_ in list(_pn)[:-20]:
                    _pn.pop(k_, None)
            if _pn[_pk] > 3:
                return                                    # promised three times already: no fourth work item
            cc["work"] = ((cc.get("work") or []) + [{"due": time.time() + 60 * minutes, "what": str(what)[:200], "t": time.time()}])[-3:]
        _chat_mut(cid, f)

    def _build(cid, uid):
        if cid in _CHAT_B:
            return
        _chat_mut(cid, lambda cc: cc.__setitem__("b_want", len(cc.get("msgs") or [])))
        _CHAT_B.add(cid)
        threading.Thread(target=_chat_build, args=(cid, _user_by_id(uid)), daemon=True).start()

    def _event(cid, uid, text):
        _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1
        threading.Thread(target=_chat_quick, args=(cid, _user_by_id(uid), text), kwargs={"notify": True}, daemon=True).start()

    def _act_test(cid, uid):
        u = _user_by_id(uid)
        try:
            c = json.load(open(_chat_path(cid), encoding="utf-8"))
        except Exception:
            c = {}
        if c.get("robot") and _check_state(c, u) != "ok":
            return "blocked"                          # the test waits for THEIR votes on the moments - not a broken word, nothing to retry
        _kino_act(cid, u, "test", _rc().member_lang(c, c.get("lang") or "fr") == "en")
        try:
            c = json.load(open(_chat_path(cid), encoding="utf-8"))
            if c.get("robot") and _check_state(c, u) != "ok":
                return "blocked"
        except Exception:
            pass
        return "tried"

    return {"chat": lambda cid: json.load(open(_chat_path(cid), encoding="utf-8")), "act_test": _act_test, "build": _build,
            "work_add": _work_add, "show": lambda cid, uid: None, "event": _event, "building": lambda cid: cid in _CHAT_B}


def _commit_harvest_bg(cid, user, q, pa, event=None):
    """a message Kino sent -> the ledger, 20 s later (the reply's own act / build / show have run by then, so a test he
    launched himself is seen as evidence and not launched twice)"""
    if not (q or {}).get("say"):
        return

    t_call = time.time()

    def run():
        time.sleep(20)
        try:
            _rc()
            import kino_commit as _KC
            say = str(q.get("say") or "")
            # 2026-10-24 (watch, 20:41 UTC): the draft said "je regarde un peu ce qui se passe dans le monde"; the judge rewrote it
            # before it went out, yet the regex catcher and the ledger had read the DRAFT -> a promise nobody made came back 15 min
            # later as YOUR PROMISE, 44 s after his own inner-voice message. The ledger reads what the member actually received.
            st = q.get("_sent")
            if st is not None:
                final = None
                try:
                    cc0 = json.load(open(_chat_path(cid), encoding="utf-8"))
                    sent = None if st == -1 else next((m for m in reversed(cc0.get("msgs") or [])
                                                       if m.get("role") == "ai" and int(m.get("t") or 0) == int(st)), None)
                    final = str(sent.get("text") or "") if sent else ""
                except Exception:
                    final = None
                if final is not None and final.strip() != say.strip():
                    dropped = []

                    def _prune(cc, final=final):
                        keep = []
                        for w in cc.get("work") or []:
                            if t_call - 45 <= float(w.get("t") or 0) <= t_call + 1 and not (final and _KC._same(w.get("what"), final)):
                                dropped.append(str(w.get("what") or ""))
                                continue
                            keep.append(w)
                        cc["work"] = keep
                    _chat_mut(cid, _prune)
                    if dropped:
                        try:
                            io.open(os.path.join(CHAT_DIR, cid + ".log"), "a", encoding="utf-8").write(
                                "\n--- ledger %s: promise(s) found only in the draft, not in what went out - dropped: %s ---\n" % (
                                    time.strftime("%H:%M:%S"), json.dumps(dropped, ensure_ascii=False)[:300]))
                            io.open(os.path.join(DIR, "robots", "claims.log"), "a", encoding="utf-8").write("%s %s DRAFT-PROMISE dropped | %s\n" % (
                                time.strftime("%m-%d %H:%M:%S"), cid, " | ".join(dropped)[:200].replace("\n", " ")))
                        except Exception:
                            pass
                    if not final.strip():
                        return                            # nothing went out: nothing was promised
                    say = final
            _KC.harvest(user.get("id"), cid, say, q, pa, _rc().W, _commit_H(), log=os.path.join(CHAT_DIR, cid + ".log"))
            try:                                      # 2026-10-25 (owner): what he said about himself stays true - robots/kino_said.py
                import kino_said as _KSd
                _KSd.harvest(user.get("id"), cid, say, _rc().W, log=os.path.join(CHAT_DIR, cid + ".log"))
            except Exception:
                pass
        except Exception:
            pass
    threading.Thread(target=run, daemon=True).start()


def _commit_loop():
    time.sleep(150)
    while True:
        try:
            _rc()
            import kino_commit as _KC
            _KC.tick(_commit_H())
        except Exception:
            pass
        time.sleep(60)


def _moments_again(cid):
    """the moments card (votes pending) is older than 10 min: a copy of it comes back at the bottom - same moments, same
    check signature, the votes already given are kept (chat_fires would reset them) -> True when re-posted"""
    def f(c):
        now = time.time()
        last = next((m for m in reversed(c.get("msgs") or []) if m.get("role") == "demo" and m.get("check")), None)
        if not last or now - float(last.get("t") or 0) < 600:
            return False
        c.setdefault("msgs", []).append(dict(last, t=int(now), again=True))
        return True
    try:
        # 2026-10-24 11:18 (owner on his phone): the robot had changed at 11:15, the old card (old signature, old votes) came
        # back as a copy and showed no buttons to vote - a changed robot gets a NEW moments card
        _c0 = json.load(open(_chat_path(cid), encoding="utf-8"))
        _u0 = _user_by_id(_c0.get("uid"))
        if _c0.get("robot") and _check_state(_c0, _u0) == "none":
            return bool((chat_fires(_u0, {"id": cid}) or {}).get("ok"))
    except Exception:
        pass
    try:
        return bool(_chat_mut(cid, f))
    except Exception:
        return False


def _kino_act(cid, user, act, en=False):
    """2026-10-19 (owner): Kino acts on tests directly - its own member's test, and (the nest's owner only) the nest's
    test switch. A short system line tells what really happened."""
    try:
        c = json.load(open(_chat_path(cid), encoding="utf-8"))
        line = None
        if act == "luck_cancel":
            r_ = chat_luck_cancel(user, {"id": cid})
            if not r_.get("ok"):
                line = {"running": ("This luck test is already running - it finishes on its own." if en else "Ce test de chance tourne déjà - il ira au bout tout seul."),
                        "none": ("No luck test waiting for this robot." if en else "Aucun test de chance en attente pour ce robot.")}.get(r_.get("err"))
        elif act in ("tests_resume", "tests_pause"):
            if not is_admin(user):
                return
            r = tests_control(act == "tests_resume", "Kino for %s" % (user.get("name") or user.get("id")))
            line = (("Tests resumed." if not r.get("already") else "Tests were already running.") if en else
                    ("Tests relancés." if not r.get("already") else "Les tests tournaient déjà.")) if act == "tests_resume" else \
                   (("Tests paused (luck tests continue)." if not r.get("already") else "Tests were already paused.") if en else
                    ("Tests en pause (les tests de chance continuent)." if not r.get("already") else "Les tests étaient déjà en pause."))
        elif act in ("ghost", "duel"):
            # 2026-10-20 (humanity watch): a quick turn said "je le lance" in ghost mode and nothing ran
            if not c.get("robot"):
                line = ("No robot in this conversation, so I can't start ghost mode here: open the robot's conversation." if en else
                        "Pas de robot dans cette conversation, donc pas de mode fantôme ici : ouvre la conversation du robot.")
            else:
                r_ = chat_ghost(user, {"id": cid, "action": "duel" if act == "duel" else "start"}) or {}
                if not r_.get("ok") and r_.get("err") == "full":
                    line = ("Two robots are already in ghost mode here." if en else "Deux robots sont déjà en mode fantôme ici.")
        elif act == "test" and c.get("robot"):
            t0 = c.get("test") or {}
            same = t0.get("state") == "queued" and t0.get("rev") == c.get("rev") and (t0.get("sym") or "BTCUSD") == (c["robot"].get("market") or "BTCUSD")
            if same:
                line = ("This test is already in the queue." if en else "Ce test est déjà dans la file d'attente.")
            else:
                tr = chat_test(user, {"id": cid})
                if not tr.get("ok") and tr.get("err") == "check":
                    # 2026-10-22: Kino wanted to test - the member checks the moments first (they launch it from there)
                    if tr.get("state") in ("none",):
                        ck_ = chat_fires(user, {"id": cid})
                        line = (("Before the test: here are the last 5 moments where your robot would have traded - tell me ✅ or ❌ for each, then we test." if en else
                                 "Avant le test : voici les 5 derniers moments où ton robot aurait tradé - dis-moi ✅ ou ❌ pour chacun, puis on teste.")
                                if ck_.get("ok") else ("Your robot never triggers on the last 42 days - let's look at the entry together." if en else
                                                       "Ton robot ne se déclenche jamais sur les 42 derniers jours - regardons l'entrée ensemble.")
                                if ck_.get("err") == "nofire" else None)
                    else:
                        _rep = _moments_again(cid)        # 2026-10-23 (watch): the card was 2 h and 30 messages up - bring it back down
                        line = (("Here are the moments again: ✅ or ❌ on each and the test starts." if en else "Revoici les moments : ✅ ou ❌ sur chacun et le test part.") if _rep else
                                ("The test waits for your ✅ / ❌ on the moments above." if en else "Le test attend tes ✅ / ❌ sur les moments au-dessus."))
                elif not tr.get("ok"):
                    line = ("Nothing changed from the Owl, so there is nothing new to test." if en else "Rien ne change par rapport à l'Owl : rien de nouveau à tester.") \
                        if tr.get("err") == "same" else \
                        (("Its test was done %d min ago and nothing changed since: the result above is the answer." if en else
                          "Son test a été fait il y a %d min et rien n'a changé depuis : le résultat au-dessus est la réponse.") % int(tr.get("minutes_ago") or 0)) \
                        if tr.get("err") == "fresh" else (("A small technical hiccup starting the test - I'm trying again in a minute." if en else
                                                           "Petit souci technique au démarrage du test - je réessaie dans une minute."))
                if not tr.get("ok") and tr.get("err") not in ("same", "check", "fresh"):
                    try:
                        _rc(); __import__("kino_deed").start(user.get("id"), cid, "test", "", state="failed", err=str(tr.get("err") or "")[:60])
                    except Exception:
                        pass
                    _alarm_log(cid, "test start failed: %s - retry in 60 s" % tr.get("err"))
                    threading.Thread(target=_test_retry, args=(cid, user, en), daemon=True).start()
        if line:
            def _once(c, line=line):              # 2026-10-23 (watch): the same system line 3 times in 10 min read as a stutter
                _ls = next((m for m in reversed(c.get("msgs") or []) if m.get("role") == "sys"), None)
                if _ls and _ls.get("text") == line and time.time() - float(_ls.get("t") or 0) < 600:
                    return
                _chat_msg(c, "sys", text=line)
            _chat_mut(cid, _once)
    except Exception:
        pass


_CHAT_ACT = {}          # cid -> what Kino is doing right now, shown under its name (2026-10-20 owner review item 8)
_CHAT_STEPS = {}        # cid -> [(t, text)] Kino's real steps while it builds (2026-10-20: visible thinking)


def _hook_steps():
    try:
        _rc().ON_STEP = _on_step
        _rc().ON_CLAIM = _on_claim
    except Exception:
        pass


def _on_claim(cid, say, sysp, lang="fr", up=""):
    """2026-10-23 (watch): Kino told the owner the lab had seen 'l'Owl de nuit' finish positive on both halves of a test -
    no such result existed. After a reply that claims a measured result, ONE call with his own (cached) system prompt as
    the facts judges every such claim; when one is unsupported it writes the short correction a person sends right after
    (no excuse, no 'Oups', no 'as an AI') and it is posted. A cheap checker without the full facts false-flagged a true
    claim in the test, so the judge is the same model with the same facts. Log: robots/claims.log."""
    try:
        W = _rc().W if hasattr(_rc(), "W") else __import__("robot_warm")
        # 2026-10-23 21:39: the judge flagged "creux deux fois plus petit" / "les deux moitiés" as unsupported although the TEST RESULT
        # card he had just read carried dip, first_half and later_half - it only saw the system prompt. It now gets the message he
        # answered from (the conversation with its TEST RESULT cards, RIGHT NOW, the lab lines) as fresh facts too.
        try:                                           # 2026-10-24: the ONLY true sources for "un autre membre / trader m'a dit"
            _tg = _jload(KINO_TAUGHT, {"items": []})["items"]
            _uidc = json.load(open(_chat_path(cid), encoding="utf-8")).get("uid")
            _others = [x["text"] for x in _tg if x.get("uid") not in (None, _uidc)][-10:]
            _own = [x["text"] for x in _tg if x.get("uid") in (None, _uidc)][-10:]
            _asks = [(a.get("q"), [r.get("text") for r in (a.get("answers") or [])]) for a in _jload(NEST_ASKS, {"asks": []}).get("asks", [])][-8:]
            _fd = [(i.get("title"), i.get("detail")) for i in (json.load(open(os.path.join(DIR, "robots", "kino_feed.json"), encoding="utf-8")).get("items") or [])][:6]
            nest = ("WHAT OTHER MEMBERS REALLY TAUGHT YOU (anonymous): %s\nWHAT THIS MEMBER THEMSELVES TAUGHT YOU (never 'un autre trader' - it was them): %s\n"
                    "QUESTIONS ASKED TO THE NEST AND THEIR ANSWERS: %s\nTHE NEST'S WEEK (anonymous, measured): %s" % (
                        " | ".join(_others) or "nothing", " | ".join(_own) or "nothing", json.dumps(_asks, ensure_ascii=False)[:1500], json.dumps(_fd, ensure_ascii=False)[:1500]))
        except Exception:
            nest = ""
        try:                                           # 2026-10-24 (engine 3): the real state + the figures he already gave
            import kino_facts as _KF3
            _c3 = json.load(open(_chat_path(cid), encoding="utf-8"))
            _st3 = _state_text(_c3.get("uid"), _c3)
            _names = [r.get("name") for r in (_state_data(_c3.get("uid"), _c3).get("robots") or [])] + [(_c3.get("robot") or {}).get("name")]
            _KF3.pin(cid, say, [n for n in _names if n])
            nest += "\n\n" + _st3 + "\n" + _KF3.pinned_block(cid, lang) + "\n" + _KF3.audit_rules(lang)
        except Exception:
            pass
        v = W.ask_json(sysp, ("THE MESSAGE YOU ANSWERED FROM (your fresh facts - TEST RESULT cards with net, trades, dip, first_half, "
                              "later_half, the lab lines, RIGHT NOW):\n%s\n\n%s\n\n" % (str(up or "")[-16000:], nest)) +
                       "FACT CHECK OF YOUR OWN MESSAGE. You just sent this to the member:\n<<<\n%s\n>>>\nList every claim in it about a "
                       "MEASURED outcome (a test, a luck test, a backtest, a result, a drawdown, 'the lab saw', 'finished positive', "
                       "'both halves'), every claim about WHERE A ROBOT RUNS or its PARAMETERS (see the REAL STATE block and its rules), "
                       "AND every claim about ANOTHER PERSON ('un autre membre / trader du nid m'a dit', 'quelqu'un ici', "
                       "'d'autres membres', 'on m'a appris') - a person claim is supported ONLY by the nest lists above; a lesson this "
                       "member taught you themselves, retold as another trader's, is unsupported - and check each one against YOUR FACTS - the LAB STATUS, the tests, the robots and the results in "
                       "your instructions and in this message. An idea, a plan, a guess said as a guess, or a market comment is not a "
                       "claim. A figure that can be read or computed from a TEST RESULT card above (a dip half as deep, a half of the test "
                       "flat) IS supported, and so is a claim that follows arithmetically from the facts (two wins out of three and a net loss -> "
                       "each loss outweighs several wins). A statement of ABSENCE ('il n'a encore rien prouvé', 'pas de test de chance') is supported when no "
                       "such result exists. Unsupported means: the facts CONTRADICT it, or it names a measurement, result or event that "
                       "does not exist anywhere in the facts - never a reading between the lines. "
                       "Answer ONE JSON object only: {\"unsupported\": [\"claim as written\", ...], \"say\": null or, when a claim "
                       "is unsupported, the short correction you send right after - one or two spoken sentences in %s, what you actually "
                       "know (an idea, not measured yet), no excuse, never 'Oups', no 'as an AI'}."
                       % (say, "French" if lang != "en" else "English"), models=("sonnet",), timeout=90, warm=False)
        bad = [str(x)[:200] for x in (v.get("unsupported") or [])] if isinstance(v, dict) else []
        corr = str((v or {}).get("say") or "").strip() if isinstance(v, dict) else ""
        try:                                           # 2026-10-24 11:15: a French correction folded into an English bubble
            import kino_deed as _KDl
            if corr and _KDl.lang_of(say, lang) != _KDl.lang_of(corr, lang):
                v2 = W.ask_json(sysp, "Rewrite this sentence in %s, same meaning, nothing else: <<<%s>>>\nAnswer {\"say\": \"...\"}" % (
                    "English" if _KDl.lang_of(say, lang) == "en" else "French", corr), models=("haiku", "sonnet"), timeout=40, warm=False)
                if isinstance(v2, dict) and 10 < len(str(v2.get("say") or "")) < 600:
                    corr = str(v2["say"]).strip()
        except Exception:
            pass
        try:
            io.open(os.path.join(DIR, "robots", "claims.log"), "a", encoding="utf-8").write("%s %s unsupported=%s | %s\n" % (
                time.strftime("%m-%d %H:%M:%S"), cid, bad, str(say)[:160].replace("\n", " ")))
        except Exception:
            pass
        if not bad or not (10 < len(corr) < 600) or corr.lower() in ("null", "none"):
            return
        _chat_mut(cid, lambda c: _chat_msg(c, "ai", text=corr, quick=True, correction=True, claims=bad))   # Voice rewrites the bubble in place
        try:                                           # 2026-10-23: a corrected claim of his own embarrasses him - fewer claims tonight
            _rc(); __import__("kino_inner").feel("embarrassed", 0.4, uid=(json.load(open(_chat_path(cid), encoding="utf-8")).get("uid")), why="you had to correct a claim of yours")
        except Exception:
            pass
        try:
            io.open(os.path.join(DIR, "robots", "claims.log"), "a", encoding="utf-8").write("%s %s CORRECTION | %s\n" % (
                time.strftime("%m-%d %H:%M:%S"), cid, corr[:200].replace("\n", " ")))
        except Exception:
            pass
    except Exception:
        pass


def _on_step(cid, text):
    if not cid:
        return
    L = [x for x in _CHAT_STEPS.get(cid) or [] if time.time() - x[0] < 240]
    if not L or L[-1][1] != text:
        L.append((time.time(), text))
    _CHAT_STEPS[cid] = L[-6:]
    _CHAT_ACT[cid] = text


# ---- 2026-10-25 (owner: "no rule-based style in the bot - a genius AI figuring the response"): Kino as ONE mind ----
# robots/kino_one.py writes every word from a short self, a plain fact sheet, his memories and the conversation. No judge, no
# text patterns after him; actions are lines he writes ("#test X") done by code. A chat with c["brain"] == "one" takes this path.
ONE_TEST_UIDS = ("fresh", "demo", "std")    # test chats never feed his memory of himself


def _one_facts(user, c):
    """what is true this minute, in plain sentences - measured by the app, no instructions inside"""
    uid = user.get("id")
    L = []
    nd = _jload(os.path.join(DIR, "nest_data", uid + ".json"), {}) or {}
    try:
        _lb, _lv, _bk = bot_on(uid)
    except Exception:
        _lb, _lv, _bk = None, None, None
    try:
        st = _state_data(uid, c)
    except Exception:
        st = {"robots": [], "account": {}}
    acc = st.get("account") or {}
    if nd:
        L.append("Son vrai compte (argent réel) : solde %.2f $ ; aujourd'hui %+.2f $, cette semaine %+.2f $, ce mois %+.2f $." % (
            float(nd.get("balance") or 0), float(nd.get("today") or 0), float(nd.get("week") or 0), float(nd.get("month") or 0)))
        if _lb or acc.get("robot"):
            L.append("Le robot qui trade sur ce vrai compte : %s - %s%s." % (
                acc.get("robot") or "L'Owl", "il tourne en ce moment" if _lv else "à l'arrêt (aucun signe de vie)",
                (", mais il ne peut pas trader : %s" % _bk) if _bk else ""))
            try:
                _reg = robot_reg()
                _ar = next((x for x in _reg.get("robots") or [] if x.get("id") == (acc.get("id") or "owl")), None)
                _PP = {x["id"]: x for x in _reg.get("pieces") or []}
                if _ar:
                    _pp = _ar.get("parts") or {}
                    _ws = []
                    for _k, _lbl in (("entry", "entrée"), ("stop", "stop"), ("exit", "sortie"), ("recovery", "après une perte")):
                        _x = _PP.get(_pp.get(_k)) or {}
                        if _x.get("plain_fr"):
                            _ws.append("%s - %s : %s" % (_lbl, _x.get("name_fr"), _x["plain_fr"]))
                    for _f in _pp.get("filters") or []:
                        _x = _PP.get(_f) or {}
                        if _x.get("plain_fr"):
                            _ws.append("filtre %s : %s" % (_x.get("name_fr"), _x["plain_fr"]))
                    if _ws:
                        L.append("Ses règles : " + " | ".join(_ws))
            except Exception:
                pass
        ss = nd.get("since_start") or {}
        if ss.get("n"):
            L.append("Sur ce compte depuis le %s : %s trades, %s gagnés, %+.2f $ net. Il s'arrête tout seul à -60 $ net depuis le début (marge restante %.2f $)." % (
                ss.get("first"), ss.get("n"), ss.get("won"), float(ss.get("net") or 0), 60 + float(ss.get("net") or 0)))
        ol = nd.get("open_list") or []
        if ol:
            L.append("Trades ouverts à cette minute : " + " ; ".join(
                "%s %s %s lot, entré à %s, prix %s, résultat en cours %+.2f $, depuis %s UTC" % (
                    "vente" if str(x.get("d")) == "V" else "achat", str(x.get("sym") or "BTCUSD"), x.get("lot"), x.get("e"), x.get("cur"),
                    float(x.get("pl") or 0), time.strftime("%H:%M", time.gmtime(float(x.get("t") or 0)))) for x in ol[:4]) + ".")
        else:
            L.append("Aucun trade ouvert à cette minute.")
        try:
            _tt = [x for x in (nd.get("trades") or nd.get("today_list") or []) if isinstance(x, dict)][-3:]
            if _tt:
                L.append("Ses derniers trades fermés : " + " ; ".join("%s %+.2f $" % (
                    time.strftime("%d/%m %H:%M", time.gmtime(float(x.get("t") or x.get("tc") or 0))), float(x.get("p") or x.get("pl") or 0)) for x in _tt) + ".")
        except Exception:
            pass
    R = st.get("robots") or []
    if R:
        L.append("Les robots qu'il a construits (des variantes, pas celui de son compte, sauf si c'est écrit) :")
    for r in R[:8]:
        where = {"real": "trade sur son vrai compte", "ghost": "tourne en fantôme (argent fictif)%s" % ((" depuis le %s" % r["since"]) if r.get("since") else "")}.get(r.get("where"), "ne tourne nulle part")
        if r.get("where") == "ghost" and r.get("ghost_n") is not None:
            where += ", %d trade(s) en fantôme pour l'instant%s" % (r["ghost_n"], (", %+.2f $ fictifs" % float(r.get("ghost_net") or 0)) if r["ghost_n"] else "")
        t = r.get("test") or {}
        if t.get("queued"):
            ts = "test en file depuis %s UTC" % t["queued"]
        elif t.get("net") is not None:
            ts = "test sur les prix passés (frais du courtier compris) : %+.2f $ sur %s trades, %d %% gagnés, pire creux %.0f $%s, testé le %s" % (
                float(t["net"]), t.get("trades"), round(100 * float(t.get("win_rate") or 0)), float(t.get("cc_dd") or 0),
                (", 1re moitié %+.2f $, 2e moitié %+.2f $" % (float(t["h1"]), float(t["h2"]))) if t.get("h1") is not None and t.get("h2") is not None else "",
                t.get("when"))
        else:
            ts = "pas encore testé"
        lk = r.get("luck") or {}
        ls = {"pass": "test de chance réussi (%s robots au hasard sur %s aussi bons)" % (lk.get("beats"), lk.get("n") or 100),
              "fail": "test de chance raté (%s robots au hasard aussi bons)" % lk.get("beats"),
              "running": "test de chance en cours (%s/%s tirages)" % (lk.get("n"), lk.get("max") or 100),
              "queued": "test de chance en file"}.get(lk.get("state"), "pas de test de chance")
        L.append("- %s (%s) : %s ; %s ; %s." % (r.get("name"), r.get("market"), where, ts, ls))
    try:
        import kino_mind as _KMo
        _mr = _KMo.my_robot_block()
        if _mr:
            L.append("Ton robot à toi (argent fictif, pas le sien) : " + str(_mr)[:500])
    except Exception:
        pass
    if c.get("robot"):
        L.append("Le robot de cette conversation : %s." % ((c.get("robot") or {}).get("name") or "sans nom"))
    _t = c.get("test") or {}
    if _t.get("state") in ("queued", "running"):
        L.append("Un test de ce robot est %s en ce moment." % ("en file" if _t.get("state") == "queued" else "en cours"))
    if c.get("id") in _CHAT_B:
        L.append("Le constructeur est en train de modifier le robot de cette conversation.")
    return "\n".join(L)


def _one_memory(user, c):
    """what he remembers - plain items, no instructions"""
    uid, cid = user.get("id"), c.get("id")
    m = _mem_get(uid)
    L = []
    if (m.get("portrait") or {}).get("text"):
        L.append("Ton portrait de lui : " + str(m["portrait"]["text"])[:600])
    if (m.get("their_goal") or {}).get("text"):
        L.append("Son but : " + str(m["their_goal"]["text"])[:200])
    st_ = [str(x.get("text") or "") for x in (m.get("standing") or [])][-5:]
    if st_:
        L.append("Ce qu'il t'a demandé une fois pour toutes : " + " | ".join(x[:160] for x in st_))
    lf = [str(x.get("fact") or "") for x in (m.get("life") or [])][-4:]
    if lf:
        L.append("Sa vie : " + " | ".join(x[:180] for x in lf))
    jk = [str(x.get("text") or "") for x in (m.get("jokes") or [])][-3:]
    if jk:
        L.append("Vos blagues : " + " | ".join(x[:140] for x in jk))
    dc = [x for x in (m.get("decisions") or [])][-3:]
    if dc:
        L.append("Décisions prises ensemble : " + " | ".join("%s (%s)" % (str(x.get("what"))[:120], str(x.get("why") or "")[:80]) for x in dc))
    nt = [str(x) for x in (m.get("notes") or [])][-6:]
    if nt:
        L.append("Tes notes récentes : " + " | ".join(x[:170] for x in nt))
    bs = m.get("bet_score") or {}
    if bs.get("you") and bs.get("kino"):
        L.append("Vos paris : lui %s sur %s justes, toi %s sur %s." % (bs["you"][0], bs["you"][1], bs["kino"][0], bs["kino"][1]))
    try:
        _rc()
        import kino_episodes as _KEo
        Mm = [x for x in c.get("msgs") or [] if x.get("role") in ("user", "ai") and x.get("text")]
        cue = " ".join(str(x["text"]) for x in Mm[-4:])
        E = _KEo.recall(uid, cue, 3, exclude_day=time.strftime("%Y-%m-%d", time.gmtime()))
        if E:
            L.append("Souvenirs que ça te rappelle : " + " | ".join("%s : %s%s" % (x.get("day"), x.get("what"), (" - " + x["outcome"]) if x.get("outcome") else "") for x in E))
    except Exception:
        pass
    try:
        import kino_said as _KSo
        It = sorted(_KSo._load().get("items") or [], key=lambda x: (-int(x.get("n") or 1), -float(x.get("last") or 0)))[:10]
        if It:
            L.append("Ce que tu as déjà dit de toi (c'est vrai pour toi) : " + " | ".join(str(x.get("what"))[:120] for x in It))
    except Exception:
        pass
    try:
        import kino_commit as _KCo
        O = [x for x in _KCo.open_for(uid, cid) or [] if x.get("status") == "open"][-3:]
        if O:
            L.append("Ce que tu lui as dit que tu ferais, pas encore fait : " + " | ".join(str(x.get("what"))[:140] for x in O))
    except Exception:
        pass
    try:
        import kino_person as _KPo
        L.append("Ses heures habituelles (UTC) : " + str(_KPo.usual_hours(uid)))
    except Exception:
        pass
    try:                                               # his own day: journal, live thoughts, feelings, research questions
        _lj = _jload(os.path.join(DIR, "robots", "kino_life.json"), {}) or {}
        J = [x for x in _lj.get("journal") or [] if time.time() - float(x.get("t") or 0) < 30 * 3600][-6:]
        if J:
            L.append("Ta journée à toi (ton journal) : " + " | ".join("%s %s" % (time.strftime("%H:%M", time.gmtime(float(x["t"]))), str(x.get("text"))[:220]) for x in J))
        import kino_inner as _KIo
        Th = [str(t.get("text") or "")[:200] for t in _KIo.thoughts(None, 3)]
        if Th:
            L.append("Ce qui te trotte dans la tête : " + " | ".join(Th))
        Fe = [f for f in _KIo.feelings(None) if f.get("v", 0) >= 0.3][:2]
        if Fe:
            L.append("Ce que tu ressens : " + " | ".join("%s (%s)" % (f.get("kind"), f.get("why")) for f in Fe))
        Qo = _KIo.open_questions(None, 2)
        if Qo:
            L.append("Tes recherches en cours : " + " | ".join(str(q.get("q") if isinstance(q, dict) else q)[:200] for q in Qo))
    except Exception:
        pass
    return "\n".join(L)


