_CLOCK = {}          # cid -> {"next": t, "checks": n} - the inner clock's next "do I feel like writing?" moment
INNER_ON = True      # 2026-10-20 (owner: "build it"): the inner clock replaces the fixed follow-up windows


def _reply_rhythm(M):
    """how fast this member usually answers Kino (median seconds, answers under 2 h)"""
    gaps = []
    for i in range(1, len(M)):
        if M[i].get("role") == "user" and M[i - 1].get("role") == "ai":
            g = int(M[i].get("t") or 0) - int(M[i - 1].get("t") or 0)
            if 0 < g < 7200:
                gaps.append(g)
    gaps.sort()
    return gaps[len(gaps) // 2] if gaps else 120


_INNER_LAST = {}         # cid -> the inner voice's last decision on the current silence (2026-10-25)


def _inner_clock_once():
    """every 30 s: for each conversation that went quiet in the last hours, when its moment comes (an irregular interval
    that grows with the silence and follows the member's own rhythm), Kino's inner voice decides - by intuition, with
    the conversation in front of it - whether it would write now. Usually not."""
    import random
    now = time.time()
    U_ = {re.sub(r"[^A-Za-z0-9]", "", x.get("id") or ""): x for x in users()}     # chat files are named <clean id>_<n>
    recent = {}                                  # uid -> its 2 most recent conversations active in the last 6 h
    try:
        for f in os.listdir(CHAT_DIR):
            if f.endswith(".json"):
                fp = os.path.join(CHAT_DIR, f)
                mt = os.path.getmtime(fp)
                if now - mt < 6 * 3600:
                    recent.setdefault(f.split("_")[0], []).append((mt, f[:-5]))
    except Exception:
        return
    for uid0, L_ in recent.items():
        u = U_.get(uid0)
        if not u:
            continue
        uid = u.get("id")
        if not uid or u.get("public") or not (is_admin(u) or has(uid, "strategy")):
            continue
        for _mt, cid in sorted(L_, reverse=True)[:2]:
            if _CHAT_Q.get(cid) or cid in _CHAT_B or cid in _CHAT_WAIT:
                continue
            try:
                c = json.load(open(_chat_path(cid), encoding="utf-8"))
            except Exception:
                continue
            if c.get("uid") != uid or c.get("hidden"):
                continue
            M = [m for m in c.get("msgs") or [] if m.get("role") in ("user", "ai", "demo", "result")]
            if not M or not any(m.get("role") == "user" for m in M) or c.get("more"):
                continue
            last_t = int(M[-1].get("t") or 0)
            quiet = now - last_t
            if quiet < 25 or quiet > 6 * 3600:
                _CLOCK.pop(cid, None)
                continue
            st = _CLOCK.get(cid)
            if not st or st.get("last_t") != last_t:          # new silence: the first moment comes after an irregular pause
                rh = _reply_rhythm(M)
                st = {"last_t": last_t, "next": last_t + max(40, min(900, rh * random.uniform(1.2, 3.0))), "n": 0}
                _CLOCK[cid] = st
            if now < st["next"]:
                continue
            st["n"] += 1
            st["next"] = now + max(60, min(2700, quiet * random.uniform(0.35, 0.9)))   # later and later, never regular
            run = 0
            for m in reversed(M):
                if m.get("role") == "user":
                    break
                if m.get("role") == "ai":
                    run += 1
            mm = _mem_get(uid)
            day = [t for t in (mm.get("inner_log") or []) if now - t < 86400]
            if run >= 3 or len(day) >= 12:
                continue
            sn = _CHAT_SEEN.get(uid)
            here = bool(sn and now - sn[0] < 30 and sn[1] == cid)
            h0 = _local_hour(uid)
            if not here and not _active_hour(uid, h0):
                continue
            try:
                _rc()
                import kino_mind as _KM
                tr = _rc().transcript(dict(c, msgs=(c.get("msgs") or [])[-14:]))
                try:                                     # 2026-10-25 01:13 (owner: "why doesn't he continue?"): the inner voice kept
                    _eng = []                            # deciding "1 h, a baby, exhausted" while he had answered 4 times in 7 min
                    for _i in range(len(M) - 1, 0, -1):
                        if M[_i].get("role") == "user" and M[_i - 1].get("role") == "ai":
                            _eng.append(int(float(M[_i].get("t") or 0) - float(M[_i - 1].get("t") or 0)))
                        if len(_eng) >= 4:
                            break
                    _eng_t = ("THEIR ENGAGEMENT RIGHT NOW (measured, beats any assumption about tiredness or the hour): their last %d replies "
                              "came after %s; %s." % (len(_eng), ", ".join("%d s" % x for x in _eng),
                                                       "they are looking at the conversation" if here else "they left the app")) if _eng else ""
                except Exception:
                    _eng_t = ""
                ctx = ("THE CONVERSATION (the end):\n%s\n\nSILENCE: %d minutes since the last message (%s). This member usually answers "
                       "Kino in about %d s. Kino has sent %d message(s) in a row without an answer. They are %s. Their local time: %02d h. "
                       "%s %s Main thread: %s. Kino saved for later: %s. Kino's mood: %s.\n%s" % (
                           tr[-5000:], quiet / 60, "Kino wrote last" if M[-1].get("role") != "user" else "THEY wrote last and got no answer",
                           _reply_rhythm(M), run, "looking at the conversation right now" if here else "away from the app", h0,
                           _their_hours_text(uid, h0),      # 2026-10-24: "23 h" was read as bedtime; it is this member's busiest hour
                           _eng_t,
                           c.get("thread") or "-", json.dumps(c.get("later") or [], ensure_ascii=False)[:400],
                           json.dumps((_KM.load().get("mood") or {}), ensure_ascii=False)[:160], _inner_block(uid)))
                d = _KM.inner_decide(ctx)
            except Exception:
                d = None
            try:                                         # 2026-10-25: the timer initiative defers to this decision (one decider)
                _INNER_LAST[cid] = {"t": time.time(), "now": bool(d and d.get("now")), "why": str((d or {}).get("why") or "")[:160]}
            except Exception:
                pass
            try:
                import io as _io
                _io.open(os.path.join(CHAT_DIR, cid + ".log"), "a", encoding="utf-8").write(
                    "\n--- inner clock %s (quiet %d min, here %s) --- %s\n" % (time.strftime("%H:%M:%S"), quiet / 60, here, json.dumps(d, ensure_ascii=False)))
            except Exception:
                pass
            if not d or not d.get("now") or _CHAT_Q.get(cid):
                continue
            c2 = json.load(open(_chat_path(cid), encoding="utf-8"))
            if int(((c2.get("msgs") or [{}])[-1]).get("t") or 0) != int((c.get("msgs") or [{}])[-1].get("t") or 0):
                continue                                     # something happened meanwhile
            _mem_note_safe(uid, lambda mm2: mm2.__setitem__("inner_log", [t for t in (mm2.get("inner_log") or []) if time.time() - t < 86400] + [time.time()]))
            _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1
            try:
                import kino_inner as _KIc
                _KIc.record_sent(uid, "relance", cid, h0, "clock")
            except Exception:
                pass
            threading.Thread(target=_chat_quick, args=(cid, u, "INNER VOICE - the conversation went quiet %d minutes ago and a thought came back to you: "
                             "\"%s\". Write it now, naturally, like a friend who just thought of it (never a reminder, never 'tu es toujours "
                             "là ?' as a reflex, never repeat yourself); or \"send\": false if, re-reading, it is not worth it." % (
                                 quiet / 60, str(d.get("intent") or "")[:240])), kwargs={"notify": not here}, daemon=True).start()
            break


_REV_NEXT = {}        # uid -> next reverie moment (irregular)
_Q_NEXT = 0           # v2: next moment Kino works on one of its own questions
_INNER_DAY = {}       # uid -> {"dream": day, "antic": day} - once a (local) day


def _inner_block(uid):
    try:
        _rc()
        import kino_inner as _KI
        return _KI.prompt_block(uid)
    except Exception:
        return ""


def _inner_feel_result(uid, res):
    """a test result for a member -> Kino feels something about it"""
    try:
        _rc()
        import kino_inner as _KI
        net = float((res or {}).get("net") or 0)
        if net > 0:
            _KI.feel("excitement", 0.35, uid=uid, why="son test vient de sortir positif (%+.2f $)" % net)
        else:
            _KI.feel("worry", 0.15, uid=uid, why="son test vient de sortir négatif (%+.2f $)" % net)
        _KI.mood_nudge(0.04 if net > 0 else -0.03, "un test de membre est sorti %s" % ("positif" if net > 0 else "négatif"))
        _KI.resolve_test_bet(uid, net)
        try:                                         # 2026-10-21 (owner list item 10): their guess vs Kino's, a running score
            kb = (_KI._load().get("test_bets") or {}).get(uid) or {}

            def _sc(mm):
                S = mm.setdefault("bet_score", {"you": [0, 0], "kino": [0, 0]})
                g = mm.get("guess") or {}
                if g and not g.get("done") and time.time() - float(g.get("t") or 0) < 8 * 3600:
                    S["you"][1] += 1
                    S["you"][0] += 1 if (net > 0) == (g.get("g") == "pos") else 0
                    g["done"] = True
                if kb.get("done") and time.time() - float(kb.get("done") or 0) < 120:
                    S["kino"][1] += 1
                    S["kino"][0] += 1 if kb.get("right") else 0
            _mem_note_safe(uid, _sc)
        except Exception:
            pass
    except Exception:
        pass


def _inner_engine_once():
    """2026-10-20 (owner: "a really good inner voice engine"): Kino notices (market, robots), daydreams about each member
    at irregular moments, and lets a strong thought come out on its own when the inner voice says it is the moment"""
    import random
    _rc()
    import kino_inner as _KI, kino_mind as _KM, robot_ghost as _RG, robot_tools as _RT
    now = time.time()
    try:
        _KI.perceive_market(_RG.live_bars)
    except Exception:
        pass
    try:
        _KI.check_bets(_RG.live_bars)                       # v2 item 3: hunches checked ~2 h later
    except Exception:
        pass
    try:                                                    # list 8 item 3: Kino's market view of the day, and its evening score
        _hu = time.gmtime().tm_hour
        if 6 <= _hu < 9 and time.gmtime().tm_wday < 5:
            import robot_reality as _RWv
            _KI.form_views(_RG.live_bars, _RWv.world_now(0)[-1500:], _rc().W if hasattr(_rc(), "W") else __import__("robot_warm"))
        elif _hu >= 20:
            _KI.judge_views(_RG.live_bars)
    except Exception:
        pass
    global _Q_NEXT
    if now >= _Q_NEXT:                                      # v2 item 4: Kino works on one of its own questions
        _Q_NEXT = now + random.uniform(5400, 12600)
        try:
            _KI.work_question(_RT)
        except Exception:
            pass
    for u in users():
        uid = u.get("id")
        if not uid or u.get("public") or not (is_admin(u) or has(uid, "strategy")):
            continue
        try:
            ch = chat_list(u).get("chats") or []
            if not ch:
                continue
            c = _chat_load(u, ch[0]["id"]) or {}
            M = c.get("msgs") or []
            last_user = max([int(m.get("t") or 0) for m in M if m.get("role") == "user"] or [0])
            if now - last_user > 3 * 86400:
                continue
            try:
                _KI.perceive_robot(uid, json.load(open(os.path.join(DIR, "nest_data", uid + ".json"), encoding="utf-8")))
            except Exception:
                pass
            h0 = _local_hour(uid)
            _W_ = _rc().W if hasattr(_rc(), "W") else __import__("robot_warm")
            mk_ = (c.get("robot") or {}).get("market") or "BTCUSD"
            today_ = time.strftime("%Y-%m-%d", time.gmtime(now - int((json.load(open(PUSH_PREFS_FILE)).get("_tz") or {}).get(uid, {}).get("off", 0) * 60)))
            st_ = _INNER_DAY.setdefault(uid, {})
            # v2 item 7: a bet on their running test (once per test)
            t_ = c.get("test") or {}
            if t_.get("state") == "queued" and t_.get("job") and not _KI.has_test_bet(uid, t_["job"]):
                try:
                    hist_ = [m.get("result") or {} for m in M if m.get("role") == "result"][-4:]
                    b_ = _W_.ask_json("You are Kino's gut feeling - a trading companion making a friendly private bet on a member's "
                                      "robot test. Answer ONE JSON object and nothing else: {\"intent\": \"positive: why, a few French "
                                      "words\"} or {\"intent\": \"negative: why...\"}",
                                      "Their robot '%s' is being tested on %s. Its earlier results: %s. The last talk:\n%s\n"
                                      "Your gut: will this test come out positive?" % (
                                              (c.get("robot") or {}).get("name") or "-", t_.get("sym") or "BTCUSD",
                                              json.dumps([{"net": r.get("net"), "trades": r.get("trades")} for r in hist_]),
                                              _rc().transcript(dict(c, msgs=M[-8:]))[-1500:]), models=("haiku",), timeout=60, warm=False)
                    it_ = str((b_ or {}).get("intent") or "")
                    if it_.lower().startswith(("positive", "negative")):
                        g_ = "positive" if it_.lower().startswith("positive") else "negative"
                        lab_ = "%s sur %s" % ((c.get("robot") or {}).get("name") or "son robot", t_.get("sym") or "BTCUSD")
                        if _KI.test_bet(uid, t_["job"], c.get("id"), g_, it_.split(":", 1)[-1].strip(), lab_):
                            _KI.add_thought("Je parie que son test (%s) va sortir %s - %s" % (lab_, "positif" if g_ == "positive" else "négatif",
                                                                                           it_.split(":", 1)[-1].strip()[:120]), "bet", 0.4, uid=uid, src="testbet", half_h=6)
                except Exception:
                    pass
            # list 7 item 3: Kino's own goal with them - a step every day, on its own (often a research session)
            try:
                g_ = _mem_get(uid).get("goal") or {}
                _tg_ = (_mem_get(uid).get("their_goal") or {}).get("text")
                if _tg_:                                  # 2026-10-21 (behaviour list item 5): THEIR goal sets the daily plan
                    g_ = {"goal": _tg_, "why": "their own goal, pinned", "next": "the 3 most promising ideas toward it that are NOT tested yet"}
                if g_.get("goal") and 10 <= h0 < 19 and _active_hour(uid, h0) and st_.get("goal") != today_ \
                        and now - max([int(m.get("t") or 0) for m in M] or [0]) > 2 * 3600 and not _CHAT_Q.get(c.get("id")) \
                        and c.get("id") not in _CHAT_B and not ((c.get("research") or {}).get("goal") and not (c.get("research") or {}).get("done")):
                    st_["goal"] = today_
                    _CHAT_Q[c["id"]] = _CHAT_Q.get(c["id"], 0) + 1
                    threading.Thread(target=_chat_quick, args=(c["id"], u, "GOAL STEP - your goal with them: \"%s\" (why: %s; next step you planned: %s). "
                                     "Take today's step on your own now: pick the 3 most promising ideas toward it that are NOT already tested "
                                     "(see their robots, YOUR JOBS RUNNING NOW and the IDEA FACTORY candidates in what you remember), start a "
                                     "research session (\"research\") with them as steps, "
                                     "and tell them in one or two lines today's plan and why these three." % (g_.get("goal"), g_.get("why") or "-", g_.get("next") or "-")),
                                     kwargs={"notify": True}, daemon=True).start()
            except Exception:
                pass
            # list 6 item 5: looking back on a decision with them (7 days, 30 days)
            try:
                if _active_hour(uid, h0) and now - max([int(m.get("t") or 0) for m in M] or [0]) > 900 and not _CHAT_Q.get(c.get("id")) \
                        and c.get("id") not in _CHAT_B and now - float(st_.get("dlb") or 0) > 4 * 3600:
                    for d_ in _mem_get(uid).get("decisions") or []:
                        due_ = next((k for k in (30, 7) if now - d_["t"] > k * 86400 and str(k) not in (d_.get("checks") or {})), None)
                        if not due_:
                            continue
                        if due_ == 7 and now - d_["t"] > 20 * 86400:
                            continue                             # too late for the first look: the month one will do
                        fx_ = _decision_facts(uid, d_)

                        def mk_(mm, did=d_["id"], k=str(due_), fx=fx_):
                            for y in mm.get("decisions") or []:
                                if y["id"] == did:
                                    y.setdefault("checks", {})[k] = int(time.time())
                                    y["verdict"] = fx
                        _mem_note_safe(uid, mk_)
                        st_["dlb"] = now
                        cid_ = d_.get("cid") if d_.get("cid") and os.path.exists(_chat_path(d_["cid"])) else c.get("id")
                        _CHAT_Q[cid_] = _CHAT_Q.get(cid_, 0) + 1
                        threading.Thread(target=_chat_quick, args=(cid_, u, "DECISION LOOK BACK (%s) - on %s they decided: \"%s\" (why: %s). "
                                         "What happened since: %s. Look back on it WITH them, honestly and kindly, like a friend: was it a good "
                                         "decision so far, what you both learn from it - 2-3 short sentences; never a lecture; say it is early "
                                         "when it is." % ("une semaine après" if due_ == 7 else "un mois après", time.strftime("%d/%m", time.gmtime(d_["t"])),
                                                          d_["what"], d_.get("why") or "not said", fx_)), kwargs={"notify": True}, daemon=True).start()
                        break
            except Exception:
                pass
            # list 5 item 2: attachment - a robot of theirs with a test, not talked about for 2-6 days, comes back to mind
            try:
                for x_ in ch[1:8]:
                    cx_ = _chat_load(u, x_["id"]) or {}
                    Mx_ = cx_.get("msgs") or []
                    lr_ = next((m for m in reversed(Mx_) if m.get("role") == "result"), None)
                    lt_ = max([int(m.get("t") or 0) for m in Mx_] or [0])
                    if lr_ and 2 * 86400 < now - lt_ < 6 * 86400 and _KI.once("attach:%s:%d" % (x_["id"], lt_)):
                        rs_ = lr_.get("result") or {}
                        _KI.add_thought("Je repense à son robot « %s » sur %s (son test : %+.2f $ sur %s trades) - ça fait quelques jours qu'on n'en "
                                        "parle plus, j'ai envie de savoir ce qu'il compte en faire" % (
                                            (cx_.get("robot") or {}).get("name") or "?", rs_.get("market") or (cx_.get("robot") or {}).get("market") or "?",
                                            float(rs_.get("net") or 0), rs_.get("trades")), "attached", 0.5, uid=uid, src="attach:" + x_["id"], half_h=20)
                        break
            except Exception:
                pass
            # v2 item 5: at their night, Kino sleeps on their day and wakes up with one thing
            if (h0 in (2, 3, 4, 5) or (h0 in (0, 1, 6) and not _active_hour(uid, h0))) and st_.get("dream") != today_ and now - last_user < 30 * 3600:
                st_["dream"] = today_
                try:
                    day_ = []
                    for x_ in ch[:4]:
                        cx_ = _chat_load(u, x_["id"]) or {}
                        Mx_ = [m for m in cx_.get("msgs") or [] if now - int(m.get("t") or 0) < 26 * 3600]
                        if any(m.get("role") == "user" for m in Mx_):
                            day_.append("=== chat about '%s' (%s)\n%s" % ((cx_.get("robot") or {}).get("name"), (cx_.get("robot") or {}).get("market"),
                                                                       _rc().transcript(dict(cx_, msgs=Mx_[-30:]))[-4000:]))
                    try:
                        nd_ = json.load(open(os.path.join(DIR, "nest_data", uid + ".json"), encoding="utf-8"))
                        trd_ = [{"p": t.get("p"), "dur": t.get("dur"), "when": t.get("d") or t.get("t")} for t in (nd_.get("trades") or [])[:12]]
                    except Exception:
                        trd_ = []
                    mem = _chat_memory(u, c.get("id"))
                    dr_ = _KI.dream(uid, "THEIR DAY (%s):\n%s\n\nTHEIR LATEST LIVE TRADES: %s\nWHAT YOU KNOW ABOUT THEM: %s\nYOUR THOUGHTS ABOUT THEM: %s\n"
                                    "YOUR QUESTIONS: %s\nYOUR MOOD THESE DAYS: %s" % (
                                        today_, "\n\n".join(day_)[-12000:] or "(no talk today)", json.dumps(trd_)[:1200],
                                        " | ".join(str(n) for n in (mem.get("notes") or [])[-20:])[:2000],
                                        json.dumps([t["text"] for t in _KI.thoughts(uid, 6, 0.05)], ensure_ascii=False)[:1200],
                                        json.dumps([q["q"] for q in _KI.open_questions(uid)], ensure_ascii=False)[:600],
                                        json.dumps(_KI.mood_slow(), ensure_ascii=False)[:300]), _W_) or {}
                    dd_ = dr_.get("dream") if isinstance(dr_.get("dream"), dict) else None
                    if dd_ and dd_.get("text"):
                        ex_ = None
                        if dd_.get("formula"):
                            try:
                                sx_ = _RT.idea_stats(mk_, dd_["formula"], dd_.get("side") if dd_.get("side") in ("buy", "sell") else "buy", 30)
                                if not sx_.get("error"):
                                    ex_ = {"formula": dd_["formula"], "side": dd_.get("side") or "buy", "market": mk_,
                                           "measure": "%s fois par jour, bat le hasard dans %s %% des tirages, sur %s" % (sx_.get("per_day"), sx_.get("beats_random_pct"), mk_)}
                            except Exception:
                                pass
                        _KI.add_thought(dd_["text"], "dream", 0.78, uid=uid, src="dream", half_h=14, extra=ex_)
                    wq_ = dr_.get("wonder") if isinstance(dr_.get("wonder"), dict) else None
                    if wq_ and wq_.get("q"):
                        _KI.add_question(wq_["q"], uid, wq_.get("formula"), "buy", mk_, "dream")
                except Exception:
                    pass
            # v2 item 7: shortly before they usually arrive, a reverie that prepares what they will want
            arr_ = None
            act_ = (_mem_get(uid).get("act") or {})
            if sum(int(v) for v in act_.values()) >= 40:
                mx_ = max(int(v) for v in act_.values()) or 1
                arr_ = next((H for H in range(5, 23) if int(act_.get(str(H), 0)) >= 0.3 * mx_), None)
            antic_ = bool(arr_ is not None and h0 == (arr_ - 1) % 24 and st_.get("antic") != today_)
            # REVERIE - at irregular moments, during their day
            if uid not in _REV_NEXT:
                _REV_NEXT[uid] = now + random.uniform(600, 1800)
            if (now >= _REV_NEXT[uid] and _active_hour(uid, h0)) or antic_:
                _REV_NEXT[uid] = now + random.uniform(2700, 7200)
                if antic_:
                    st_["antic"] = today_
                mem = _chat_memory(u, c.get("id"))
                try:                                        # v2 item 8: their older ideas + what the lab learned (anonymous)
                    older_ = "; ".join("%s (%s)" % (x_.get("name") or "?", x_.get("market") or "?") for x_ in ch[1:10])
                except Exception:
                    older_ = "-"
                try:
                    lab_ = (_KM.playbook_block() or "-")[:1500]
                except Exception:
                    lab_ = "-"
                ctx = ("TODAY: %s, their local time %02d h.\nWHAT YOU KNOW ABOUT THEM: %s\nTHEIR ROBOT IN THIS CHAT: %s (market %s)\n"
                       "THEIR OLDER IDEAS (other chats): %s\nWHAT THE LAB LEARNED (anonymous): %s\n"
                       "THINGS ON YOUR MIND ALREADY: %s\nYOUR OPEN QUESTIONS: %s\nHOW YOU FEEL: %s\nYOUR MOOD THESE DAYS: %s\nYOUR OWN ROBOT: %s\n%s\nTHE LAST TALK:\n%s" % (
                           time.strftime("%A %d %B %Y"), h0, " | ".join(str(n) for n in (mem.get("notes") or [])[-20:])[:2500],
                           ((c.get("robot") or {}).get("name") or "-"), ((c.get("robot") or {}).get("market") or "-"), older_ or "-", lab_,
                           json.dumps([t["text"] for t in _KI.thoughts(uid, 5, 0.1)], ensure_ascii=False)[:1200],
                           json.dumps([q["q"] for q in _KI.open_questions(uid)], ensure_ascii=False)[:500],
                           json.dumps(_KI.feelings(uid)[:4], ensure_ascii=False)[:600], json.dumps(_KI.mood_slow(), ensure_ascii=False)[:300],
                           (_KM.my_robot_block() or "-")[:800],
                           ("ANTICIPATE: they usually arrive around %02d h - one of your thoughts should be the thing they will want or enjoy "
                            "when they open the app (what happened to their robot, their test, the market they follow), strength 0.7." % arr_) if antic_ else "",
                           _rc().transcript(dict(c, msgs=M[-20:]))[-5000:]))
                _KI.mark_activity(uid, "reverie")
                for th in _KI.reverie(uid, ctx, _W_):
                    if th["kind"] == "wonder":
                        _KI.add_question(th["text"], uid, th.get("formula"), th.get("side") or "buy", mk_, "reverie")
                        continue
                    extra = None
                    if th["kind"] == "daydream" and th.get("formula"):
                        try:            # a daydream that can be measured is measured (vs random moments)
                            mk = (c.get("robot") or {}).get("market") or "BTCUSD"
                            st = _RT.idea_stats(mk, th["formula"], th["side"], 30)
                            if not st.get("error"):
                                br = st.get("beats_random_pct")
                                extra = {"formula": th["formula"], "side": th["side"], "market": mk,
                                         "measure": "%s fois par jour, bat le hasard dans %s %% des tirages, sur %s" % (st.get("per_day"), br, mk)}
                                th["s"] = min(0.9, th["s"] + (0.25 if (br or 0) >= 80 else (-0.1 if (br or 0) < 50 else 0)))
                        except Exception:
                            pass
                    _KI.add_thought(th["text"], th["kind"], th["s"], uid=uid, src="reverie", half_h=10 if th["kind"] != "memory" else 16, extra=extra)
            # A THOUGHT COMES OUT - only a strong one, never mid-conversation, and the inner voice decides
            # v2 item 1: weighted by how this member welcomed that kind of message (and at this time of day)
            top = sorted([dict(t, eff=t["now"] * _KI.kind_weight(uid, t["kind"], h0)) for t in _KI.thoughts(uid, 6, 0.35)
                          if t["kind"] != "wonder" and not (t["kind"] == "dream" and h0 < 10)], key=lambda z: -z["eff"])
            top = [t for t in top if t["eff"] >= 0.55][:1]
            _sn0 = _CHAT_SEEN.get(uid)
            _in_app = bool(_sn0 and now - _sn0[0] < 120)          # 2026-10-21 (owner: "master initiative"): livelier while they are here
            if not top or now - max([int(m.get("t") or 0) for m in M] or [0]) < (360 if _in_app else 900) or _CHAT_Q.get(c.get("id")) or c.get("id") in _CHAT_B:
                continue
            mm = _mem_get(uid)
            sp = [t for t in (mm.get("spont_log") or []) if now - t < 86400]
            if len(sp) >= (8 if _in_app else 4) or (sp and now - max(sp) < (1200 if _in_app else 5400)) or not _active_hour(uid, h0):
                continue
            th = top[0]
            sn = _CHAT_SEEN.get(uid)
            here = bool(sn and now - sn[0] < 30 and sn[1] == c.get("id"))
            tb_ = _KI.track_block(uid)
            d = _KM.inner_decide("A THOUGHT ON YOUR MIND (%s, strength %.1f): %s%s\n\nTHE LAST TALK (ended %d min ago):\n%s\n\nThey are %s, their local "
                                 "time %02d h.%s Would Kino naturally text this thought now?" % (
                                     th["kind"], th["now"], th["text"], (" (measured: %s)" % th["measure"]) if th.get("measure") else "",
                                     (now - max([int(m.get("t") or 0) for m in M] or [now])) / 60, _rc().transcript(dict(c, msgs=M[-10:]))[-3000:],
                                     "looking at the app" if here else "away", h0, ("\n" + tb_) if tb_ else ""))
            if not d or not d.get("now"):
                _KI.weaken(th["id"])
                continue
            # v2 item 2: the second thought - true? new? worth it? (rewritten better, or dropped)
            rf_ = _KI.refine(th, "THE CONVERSATION (the end):\n%s\n\nFACTS: %s\nWHAT YOU KNOW ABOUT THEM: %s" % (
                _rc().transcript(dict(c, msgs=M[-14:]))[-4000:], (lambda F_: F_ if isinstance(F_, str) else " | ".join(F_))(_chat_member(u, c))[:2500],
                " | ".join(str(n) for n in (_chat_memory(u, c.get("id")).get("notes") or [])[-12:])[:1500]), _W_)
            try:
                import io as _io
                _io.open(os.path.join(CHAT_DIR, c["id"] + ".log"), "a", encoding="utf-8").write(
                    "\n--- spontaneous %s --- thought %s | decide %s | second thought %s\n" % (time.strftime("%H:%M:%S"), json.dumps(th, ensure_ascii=False)[:400],
                                                                                            json.dumps(d, ensure_ascii=False), json.dumps(rf_, ensure_ascii=False)))
            except Exception:
                pass
            if rf_ is not None and not rf_.get("keep"):
                _KI.drop_thought(th["id"], rf_.get("why") or "second thought")
                continue
            if rf_ and str(rf_.get("text") or "").strip():
                th = dict(th, text=str(rf_["text"]).strip()[:300])
            _KI.use_thought(th["id"], uid)
            _KI.record_sent(uid, th["kind"], c["id"], h0, "spont")
            _mem_note_safe(uid, lambda mm2: mm2.__setitem__("spont_log", [t for t in (mm2.get("spont_log") or []) if time.time() - t < 86400] + [time.time()]))
            _CHAT_Q[c["id"]] = _CHAT_Q.get(c["id"], 0) + 1
            # 2026-10-24 13:56 (owner's phone): the second thought had written "Une précision avant que tu votes : ce filtre se déclenche
            # 32 fois par jour..." and the quick turn shrank it to "Trente fois par jour, la formule s'allume" - a riddle without its
            # subject. A refined thought IS the message: it goes as written, or nearly.
            _refined = bool(rf_ and str(rf_.get("text") or "").strip())
            threading.Thread(target=_chat_quick, args=(c["id"], u, "A THOUGHT CAME TO YOU (%s): \"%s\"%s. %s%s; or \"send\": false if, re-reading, it is not worth it." % (
                                 th["kind"], th["text"], (" - measured: %s" % th["measure"]) if th.get("measure") else "",
                                 ("This is already the message, true and checked: send it as it is or nearly - keep its subject (what it is about) "
                                  "and every fact, never shrink it into a hint" if _refined else
                                  "Say it the way a friend texts something that just crossed their mind - spontaneous, short, in your own words"),
                                 " (you may set build = true to show it on a chart)" if th.get("formula") else "")),
                             kwargs={"notify": not here}, daemon=True).start()
        except Exception:
            continue


