_MISS = {}            # cid -> [msg t, tries, first seen stuck]


def _chat_watch_once():
    """2026-10-20 (owner list 5): every 30 s over all conversations -
    (9) a member's message left without any answer (a crashed turn, a stuck counter): Kino is woken up again (twice), then
        a short honest line rather than silence; every case is logged (robots/kino_alarm.log)
    (3) a promise Kino made ("laisse-moi 10 min", field "work") is due: it is kept, even if the talk moved on
    (8) an experiment agreed together ended: Kino measures it with them"""
    now = time.time()
    U_ = {x.get("id"): x for x in users()}
    for f in os.listdir(CHAT_DIR):
        if not f.endswith(".json"):
            continue
        cid = f[:-5]
        try:
            c = json.load(open(os.path.join(CHAT_DIR, f), encoding="utf-8"))
        except Exception:
            continue
        u = U_.get(c.get("uid"))
        if not u or c.get("hidden") or cid.endswith("9999999999999"):
            continue                                  # 2026-10-21: test copies never get woken / promises kept (one did, mid-test)
        M = c.get("msgs") or []
        alarm = lambda what: open(os.path.join(DIR, "robots", "kino_alarm.log"), "a", encoding="utf-8").write(
            "%s %s %s\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), cid, what))
        # (9) missed reply
        lm = M[-1] if M else {}
        if lm.get("role") in ("user", "show", "image", "doc") and not lm.get("answered") and 75 < now - int(lm.get("t") or 0) < 3 * 3600 \
                and cid not in _CHAT_WAIT and cid not in _CHAT_B:
            st = _MISS.get(cid)
            if not st or st[0] != lm.get("t"):
                st = _MISS[cid] = [lm.get("t"), 0, now]
            if _CHAT_Q.get(cid):
                if now - st[2] > 240:                 # a turn counted as running for 4 min with nothing coming: stuck
                    _CHAT_Q[cid] = 0
                    alarm("stuck counter reset")
                else:
                    continue
            elif st[1] and now - st[2] < 75:
                continue                              # give the last wake-up time to answer
            st[2] = now
            if st[1] < 2:
                st[1] += 1
                alarm("no answer %d s after the member's message - waking Kino (try %d)" % (now - int(lm.get("t") or 0), st[1]))
                threading.Thread(target=_chat_listen, args=(cid, u), daemon=True).start()
            elif st[1] == 2:
                st[1] = 3
                alarm("still no answer after 2 tries - honest line posted")
                en_ = c.get("lang") == "en"
                _chat_mut(cid, lambda cc: _chat_msg(cc, "ai", text=("Sorry, I lost my thread for a moment - can you tell me again?" if en_ else
                                                                  "Pardon, j'ai perdu le fil une seconde - tu peux me redire ?"), quick=True))
            continue
        if _CHAT_Q.get(cid) or cid in _CHAT_B or cid in _CHAT_WAIT:
            continue
        try:                                             # 2026-10-23 (engine 3): 30 min without an answer = "silent" came true
            _rc()
            import kino_person as _KP
            _KP.silent_check(u.get("id"), cid, now)
        except Exception:
            pass
        # (3) a promise due
        W_ = [w for w in c.get("work") or [] if now >= float(w.get("due") or 0)]
        if W_:                                           # 2026-10-23 23:33 (watch): member first, and one reminder per 10 min per chat
            _lu = max([float(m.get("t") or 0) for m in (c.get("msgs") or []) if m.get("role") == "user"] or [0])
            # 2026-10-24 20:41 UTC (watch): the reminder fired 28 s after his own inner-voice message - two bubbles of his in a
            # minute. His own last bubble holds it exactly like the member's: a friend finishes one thought before the next.
            _la = max([float(m.get("t") or 0) for m in (c.get("msgs") or []) if m.get("role") == "ai"] or [0])
            if now - _lu < 240 or now - _la < 240 or now - _LAST_PROMISE_FIRE.get(cid, 0) < 600:
                try:                                     # 2026-10-24: two reminders 2 min apart slipped through - log every hold
                    io.open(os.path.join(DIR, "robots", "pace.log"), "a", encoding="utf-8").write("%s %s %s HELD promise | member %ds ago, own %ds ago, last fire %ds ago\n" % (
                        time.strftime("%m-%d %H:%M:%S"), u.get("id"), cid, now - _lu, now - _la, now - _LAST_PROMISE_FIRE.get(cid, 0)))
                except Exception:
                    pass
                W_ = []
        if W_ and _waiting_promise(W_[0].get("what")) and _jobs_running(u.get("id"), cid):
            w = W_[0]

            def _ws(cc, w=w, old=now - float(w.get("t") or now) > 8 * 3600):
                if old:
                    cc["work"] = [x for x in cc.get("work") or [] if x.get("t") != w.get("t")]
                    try:                                 # 2026-10-23: dropped unkept = broken in the ledger
                        _rc()
                        import kino_commit as _KC
                        _KC.resolve_work(cid, w.get("what"), False, "waited 8 h on a job that never ended")
                    except Exception:
                        pass
                else:
                    for x in cc.get("work") or []:
                        if x.get("t") == w.get("t"):
                            x["due"] = now + 1800
            _chat_mut(cid, _ws)
            continue
        if W_:
            w = W_[0]
            def _wk(cc, w=w):
                cc["work"] = [x for x in cc.get("work") or [] if x.get("t") != w.get("t")]
                cc["kept"] = ((cc.get("kept") or []) + [{"what": w.get("what"), "t": int(now)}])[-5:]   # 2026-10-21: the promise tray ticks green
            _chat_mut(cid, _wk)
            if now - float(w["due"]) < 6 * 3600:
                sn = _CHAT_SEEN.get(u.get("id"))
                here = bool(sn and now - sn[0] < 60 and sn[1] == cid)
                _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1
                _LAST_PROMISE_FIRE[cid] = now
                try:                                      # 2026-10-23: how many times this promise was made already
                    _pnd = json.load(open(_chat_path(cid), encoding="utf-8")).get("promise_n") or {}
                    _pn = int(_pnd.get(_promise_key(_pnd, w.get("what")), 1))
                except Exception:
                    _pn = 1
                _patt = ("" if _pn <= 1 else
                         " SECOND TIME you are reminded of this promise: the numbers come NOW with a tool (breakdown / idea_stats / compare / "
                         "robot_replay), or you say in ONE plain line that you cannot compute it here and you drop it - no 'je m'y mets' again."
                         if _pn == 2 else
                         " THIRD TIME: you promised this three times and delivered nothing. Say so in one plain line, no excuse, no new promise, "
                         "build = false, and let it go.")
                threading.Thread(target=_chat_quick, args=(cid, u, "YOUR PROMISE - %d minutes ago you told them you would look into: \"%s\". "
                                 "Keep it now: say it like a friend coming back (\"bon, j'ai regardé...\") and set build = true so the real "
                                 "numbers / chart come with it. They are %s.%s" % ((now - float(w["t"])) / 60, w["what"],
                                                                                   "looking at the conversation" if here else "away from the app", _patt)),
                                 kwargs={"notify": not here}, daemon=True).start()
            else:
                try:                                     # 2026-10-23: a promise found 6 h late is a broken one
                    _rc()
                    import kino_commit as _KC
                    _KC.resolve_work(cid, w.get("what"), False, "promise found %d h late" % ((now - float(w["due"])) / 3600))
                except Exception:
                    pass
            continue
        # (1, 2) a research session moves on by itself: one step every few minutes while the talk is quiet
        R_ = c.get("research") or {}
        if R_.get("goal") and not R_.get("done"):
            last_any = max([int(m.get("t") or 0) for m in M] or [0])
            sn = _CHAT_SEEN.get(u.get("id"))
            here = bool(sn and now - sn[0] < 60 and sn[1] == cid)
            if now > float(R_.get("until") or 0) or int(R_.get("n") or 0) >= 14:
                _chat_mut(cid, lambda cc: (cc.get("research") or {}).__setitem__("done", now))
                _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1
                threading.Thread(target=_chat_quick, args=(cid, u, "RESEARCH SESSION - time is up: wrap it up now in 2-4 short sentences - what you "
                                 "found, what you keep, what you would do next - and \"research_done\": true."), kwargs={"notify": not here}, daemon=True).start()
                continue
            if now - last_any >= 100 and now - float(R_.get("last_step") or 0) >= 150:
                def _st(cc):
                    r_ = cc.get("research") or {}
                    r_["n"] = int(r_.get("n") or 0) + 1
                    r_["last_step"] = now
                _chat_mut(cid, _st)
                todo = [i for i, x in enumerate(R_.get("steps") or []) if x.get("state") in ("todo", "doing")]
                _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1
                threading.Thread(target=_chat_quick, args=(cid, u, "RESEARCH SESSION - goal: %s. %s Do it now (build = true for the numbers), "
                                 "say it in ONE short line, update the plan. Finish early with a wrap-up if the goal is reached." % (
                                     R_["goal"], ("Next step: %d. %s." % (todo[0], R_["steps"][todo[0]]["text"])) if todo else
                                     "All steps are done or dropped: add a better next step if one is worth it, or wrap up now.")),
                                 kwargs={"notify": False}, daemon=True).start()
                continue
        # (8) an experiment ended (during their day)
        X_ = [x for x in c.get("exps") or [] if not x.get("done") and now >= float(x.get("due") or 0)]
        if X_ and _active_hour(u.get("id")):
            x = X_[0]

            def putx(cc):
                for y in cc.get("exps") or []:
                    if y.get("t") == x.get("t"):
                        y["done"] = now
            _chat_mut(cid, putx)
            _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1
            threading.Thread(target=_chat_quick, args=(cid, u, "SHARED EXPERIMENT - the experiment you agreed on together has ended: \"%s\" "
                             "(started %s, %d days; how to measure: %s; YOUR BET: %s). Measure it now with your tools (build = true) and "
                             "show it together - honestly, and say plainly whether your bet was right." % (
                                 x["title"], time.strftime("%d/%m", time.gmtime(x["t"])), x.get("days") or 0, x.get("how") or "-", x.get("bet") or "-")),
                             kwargs={"notify": True}, daemon=True).start()


