def kino_mem(user, body):
    """2026-10-20 (owner list 8 item 6): the member fixes or deletes anything Kino remembers about them - notes, their
    standing instructions, shared moments, running jokes, decisions. A fix is kept so Kino can say "ah, noté, je m'étais trompé"."""
    uid = user.get("id")
    kind, act = str(body.get("kind") or ""), str(body.get("act") or "del")
    txt = str(body.get("text") or "").strip()[:400]
    try:
        i = int(body.get("i"))
    except Exception:
        return {"ok": False}
    if kind in ("note", "standing", "decision"):
        key = {"note": "notes", "standing": "standing", "decision": "decisions"}[kind]

        def put(mm):
            L = mm.get(key) or []
            if not (0 <= i < len(L)):
                return
            old = L[i] if isinstance(L[i], str) else (L[i].get("text") or L[i].get("what") or "")
            if act == "fix" and txt:
                if isinstance(L[i], str):
                    L[i] = txt
                elif kind == "decision":
                    L[i]["what"] = txt
                else:
                    L[i]["text"] = txt
                mm["mem_fixes"] = ((mm.get("mem_fixes") or []) + [{"t": int(time.time()), "old": str(old)[:200], "new": txt}])[-10:]
            else:
                L.pop(i)
            mm[key] = L
        _mem_note_safe(uid, put)
        return {"ok": True}
    if kind in ("moment", "joke"):
        _rc()
        import kino_inner as _KIx

        def f(d):
            L = (d.get("moments") or {}).get(uid) or []
            idx = [k for k, x in enumerate(L) if x.get("kind") == kind]
            if 0 <= i < len(idx):
                L.pop(idx[i])
        _KIx._mut(f)
        return {"ok": True}
    return {"ok": False}


def kino_forget(user, body):
    """the member makes Kino forget one note about them"""
    try:
        i = int(body.get("i"))
    except Exception:
        return {"ok": False}

    def put(mm):
        n = mm.get("notes") or []
        if 0 <= i < len(n):
            n.pop(i)
            mm["notes"] = n
    _mem_note_safe(user.get("id"), put)
    return {"ok": True}


# ---- 2026-10-19 (owner: "Kino on Telegram, same memory and personality: you talk to it there, it reaches you there") ----
# owl_telegram.py forwards a linked member's message to POST /kino_tg (localhost only + live/kino_bridge.secret); it goes
# into their latest conversation like any message; the quick reply comes back in the HTTP answer, later messages
# (Kino's follow-up, proactive ones) are sent to their Telegram by tg_send while the Telegram thread is "live".
def _tg_token():
    try:
        return json.load(open(os.path.join(DIR, "owl_telegram.json"), encoding="utf-8")).get("token")
    except Exception:
        return None


def tg_send(uid, text):
    u = next((x for x in users() if x.get("id") == uid), None)
    cid, tok = (u or {}).get("telegram_chat"), _tg_token()
    if not cid or not tok or not text:
        return False
    try:
        import urllib.request, urllib.parse
        data = urllib.parse.urlencode({"chat_id": cid, "text": str(text)[:3500]}).encode()
        url = "https://api.telegram.org/bot%s/sendMessage" % tok
        try:
            urllib.request.urlopen(url, data=data, timeout=15).read()
        except Exception as e:
            if "CERTIFICATE_VERIFY_FAILED" not in str(e):
                raise
            import ssl as _ssl            # this box's Python distrusts the chain (owl_telegram.py does the same)
            urllib.request.urlopen(url, data=data, timeout=15, context=_ssl._create_unverified_context()).read()
        return True
    except Exception:
        return False


def tg_photo(uid, png, caption=""):
    """a chart picture to the member's Telegram (multipart sendPhoto)"""
    u = next((x for x in users() if x.get("id") == uid), None)
    cid, tok = (u or {}).get("telegram_chat"), _tg_token()
    if not cid or not tok or not png:
        return False
    import urllib.request, uuid, ssl as _ssl
    bd = uuid.uuid4().hex
    body = (("--%s\r\nContent-Disposition: form-data; name=\"chat_id\"\r\n\r\n%s\r\n" % (bd, cid)) +
            ("--%s\r\nContent-Disposition: form-data; name=\"caption\"\r\n\r\n%s\r\n" % (bd, str(caption)[:900]))).encode("utf-8") + \
        ("--%s\r\nContent-Disposition: form-data; name=\"photo\"; filename=\"chart.png\"\r\nContent-Type: image/png\r\n\r\n" % bd).encode() + \
        png + ("\r\n--%s--\r\n" % bd).encode()
    req = urllib.request.Request("https://api.telegram.org/bot%s/sendPhoto" % tok, data=body,
                                 headers={"Content-Type": "multipart/form-data; boundary=%s" % bd})
    try:
        try:
            urllib.request.urlopen(req, timeout=20).read()
        except Exception as e:
            if "CERTIFICATE_VERIFY_FAILED" not in str(e):
                raise
            urllib.request.urlopen(req, timeout=20, context=_ssl._create_unverified_context()).read()
        return True
    except Exception:
        return False


def _tg_demo(uid, dm):
    """2026-10-19 (owner item 6): a chart Kino shows goes to Telegram as a picture while the member talks there"""
    if not dm or dm.get("nodata") or not _tg_live(uid):
        return
    try:
        _rc()
        import chart_png as _CP
        png = _CP.render(dm)
        if png:
            threading.Thread(target=tg_photo, args=(uid, png, ""), daemon=True).start()
    except Exception:
        pass


def _tg_live(uid):
    return time.time() - float(_mem_get(uid).get("tg_live") or 0) < 1800


def kino_tg(body):
    uid, text = str(body.get("uid") or ""), str(body.get("text") or "").strip()[:1500]
    u = next((x for x in users() if x.get("id") == uid), None)
    if not u or not text:
        return {"ok": False}
    if not (is_admin(u) or has(uid, "strategy")):
        return {"ok": True, "say": "Kino, le compagnon de trading de l'app, est inclus dans la formule Stratégie. Tu peux la voir dans l'app : Compte › Abonnement."}
    ch = chat_list(u).get("chats") or []
    cid = ch[0]["id"] if ch else chat_start(u, {"lang": "fr"}).get("id")
    if not cid:
        return {"ok": False}
    if _CHAT_Q.get(cid):
        return {"ok": True, "say": None}
    _mem_note_safe(uid, lambda mm: mm.__setitem__("tg_live", time.time()))
    _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1
    _chat_mut(cid, lambda c: _chat_msg(c, "user", text=text, via="telegram"))
    n0 = len((_chat_load(u, cid) or {}).get("msgs") or [])
    _chat_quick(cid, u)                                     # synchronous here: the bridge waits for the reply
    c = _chat_load(u, cid) or {}
    new = [m for m in (c.get("msgs") or [])[n0:] if m.get("role") == "ai"]
    last_user = next((m for m in reversed(c.get("msgs") or []) if m.get("role") == "user"), {})
    return {"ok": True, "say": "\n\n".join(m.get("text") or "" for m in new) or None, "react": last_user.get("react"),
            "chips": (new[-1].get("chips") if new else None) or []}


def ai_nudge(user):
    """the takeover card of the app: the AI's latest unseen message (last 3 days); and for the floating Kino bubble on
    every page (owl_kino_fab.js): can (has Kino), unread (Kino's messages since the member last looked), the last one"""
    if user.get("public"):
        return {"public": True}
    if not (is_admin(user) or has(user.get("id"), "strategy")):
        return {"can": False}
    out = {"can": True, "unread": 0}
    try:
        ch = chat_list(user).get("chats") or []
        if ch:
            c = _chat_load(user, ch[0]["id"]) or {}
            sn = _CHAT_SEEN.get(user.get("id"))
            seen_t = sn[0] if sn else max([int(m.get("t") or 0) for m in c.get("msgs") or [] if m.get("role") == "user"] or [0])
            new = [m for m in c.get("msgs") or [] if m.get("role") == "ai" and int(m.get("t") or 0) > seen_t]
            out["unread"] = len(new)
            if new:
                out["last"] = {"t": new[-1].get("t"), "text": str(new[-1].get("text") or "")[:200], "cid": c["id"]}
    except Exception:
        pass
    m = _mem_get(user.get("id"))
    for n in reversed(m.get("nudges") or []):
        if not n.get("seen") and time.time() - n["t"] < 3 * 86400:
            out["nudge"] = {"t": n["t"], "text": n["text"], "cid": n["cid"], "important": n.get("important")}
            break
    return out


def ai_nudge_seen(user, body):
    t = int(body.get("t") or 0)
    cid = body.get("cid")

    def put(m):
        for n in m.get("nudges") or []:
            if n["t"] == t or (cid and n["cid"] == cid):
                n["seen"] = True
    _mem_note_safe(user.get("id"), put)
    return {"ok": True}


