def chat_explain(user, body):
    """2026-10-19 (owner: "Kino explains your live chart"): from the price chart, 'Demande à Kino' - the live picture of
    the market as the Owl reads it (trend, pending turn, next break level, protected point, pace, movement) goes to Kino
    with a marked chart of the last candles; Kino explains what the Owl sees and what it is waiting for."""
    sym = str(body.get("sym") or "BTCUSD").upper()
    try:
        if sym.startswith("BTC"):
            j = json.load(open(os.path.join(DIR, "owl_chart_btc.json"), encoding="utf-8")); sc = 1.0; sym = "BTCUSD"
        else:
            j = json.load(open(os.path.join(DIR, "chart_multi", sym + ".json"), encoding="utf-8"))
            sc = float((json.load(open(os.path.join(DIR, "chart_multi", "meta.json"), encoding="utf-8"))["symbols"].get(sym) or {}).get("scale") or 1)
    except Exception:
        return {"ok": False, "err": "nodata"}
    cs = [[c[0], c[1] / sc, c[2] / sc, c[3] / sc, c[4] / sc] for c in (j.get("candles") or [])[-120:]]
    if not cs:
        return {"ok": False, "err": "nodata"}
    t0 = cs[0][0]
    lines = []
    if j.get("next_bos"):
        lines.append({"f": "prochain BOS (cassure qui continue la tendance)", "pts": [round(j["next_bos"] / sc, 5)] * len(cs)})
    dots = [d for d in (j.get("dots") or []) if d[0] >= t0 - 86400]
    if dots:
        lines.append({"f": "point protégé", "pts": [round(dots[-1][1] / sc, 5)] * len(cs)})
    marks = [{"k": "buy" if b[1] == 1 else "sell", "t": int(b[0]), "p": round(b[2] / sc, 5)} for b in (j.get("breaks") or []) if b[0] >= t0][-4:]
    vn, vr = j.get("vol_now"), j.get("vol_ref")
    nerv = (vn / vr) if (vn and vr) else None
    facts = ("market %s, price %s; the Owl's structure: trend %s%s; next BOS level %s (a close beyond it = a new break in the trend); last "
             "protected point %s; inner structure trend %s; pace %s; big moves in the last 2 h: %s (the Owl wants at least 1 - else the "
             "market is 'asleep'); last marks: %s" % (
                 sym, round(cs[-1][4], 5), {1: "UP", -1: "DOWN"}.get(j.get("trend"), "none"),
                 (", a change of direction (CHoCH) is pending toward %s" % ("up" if j.get("choch") == 1 else "down")) if j.get("choch") else "",
                 round(j["next_bos"] / sc, 5) if j.get("next_bos") else "-", round(dots[-1][1] / sc, 5) if dots else "-",
                 {1: "up", -1: "down"}.get(j.get("int_trend"), "-"),
                 ("%.2fx usual (%s)" % (nerv, "storm - nobody trades" if nerv >= 1.85 else "nervous" if nerv > 1 else "calm")) if nerv else "-",
                 j.get("moves_2h"), ", ".join("%s %s at %s" % (m[2], "up" if m[3] == 1 else "down", round(m[1] / sc, 5)) for m in (j.get("marks") or [])[-3:])))
    ch = chat_list(user).get("chats") or []
    cid = ch[0]["id"] if ch else chat_start(user, {"lang": "fr"}).get("id")
    if not cid or _CHAT_Q.get(cid):
        return {"ok": False, "err": "busy", "id": cid}
    demo = {"role": "demo", "kind": "live", "market": sym, "count": 0, "per_day": 0, "side": "buy",
            "moments": [{"tf": "M1", "candles": cs, "t": cs[-1][0], "marks": marks, "overlays": lines, "after": 0}], "t": int(time.time())}
    _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1

    def put(c):
        _chat_msg(c, "user", text=("Explique-moi le graphique en direct (%s)" % sym) if (c.get("lang") or "fr") != "en" else ("Explain the live chart (%s)" % sym))
        c.setdefault("msgs", []).append(demo)
    _chat_mut(cid, put)
    threading.Thread(target=_chat_quick, args=(cid, user, "EXPLAIN LIVE CHART - the member pressed 'Demande à Kino' on the price chart; "
                     "the chart above shows the last candles with the next BOS level and the protected point. Explain like a friend at "
                     "their screen: what the Owl sees right now, what it is waiting for to enter (or why it does nothing), what would "
                     "change its mind - 3-5 short sentences, plain words, numbers from the facts only. Facts: " + facts), daemon=True).start()
    return {"ok": True, "id": cid}


def _ghost_new(robot, name=None):
    return {"id": "g%d" % int(time.time() * 1000), "name": (name or robot.get("name") or "Robot")[:30], "robot": json.loads(json.dumps(robot)),
            "market": robot.get("market") or "BTCUSD", "started": int(time.time()), "last_t": 0, "open": None, "trades": []}


def chat_ghost(user, body):
    """2026-10-19 (owner items 4 / 8): ghost mode - the chat's robot trades pretend money on live candles; 'duel' = the
    robot against a variant (Kino's last proposal) side by side; 'stop' ends them"""
    c = _chat_load(user, str(body.get("id") or ""))
    if c is None or not c.get("robot"):
        return {"ok": False, "err": "missing"}
    act = str(body.get("action") or "start")

    def put(c):
        G = c.setdefault("ghosts", [])
        if act == "stop":
            c["ghosts"] = []
            _chat_msg(c, "sys", text="Mode fantôme arrêté." if (c.get("lang") or "fr") != "en" else "Ghost mode stopped.")
            return True
        if act == "duel":
            pr = next((m for m in reversed(c.get("msgs") or []) if m.get("role") == "proposal"), None)
            if not pr:
                return "noprop"
            c["ghosts"] = [_ghost_new(c["robot"], (c["robot"].get("name") or "Robot")[:22] + " (A)"), _ghost_new(pr["robot"], "Variante de Kino (B)")]
            _chat_msg(c, "sys", text="Duel lancé : ton robot contre la variante de Kino, en argent fictif sur les vrais prix. Verdict dans 7 jours.")
            _chat_msg(c, "card", kind="ghost", args={})
            return True
        if len(G) >= 2:
            return "full"
        G.append(_ghost_new(c["robot"]))
        _chat_msg(c, "sys", text="Mode fantôme lancé : %s trade en argent fictif sur les prix en direct de %s." % (c["robot"].get("name") or "ton robot",
                                                                                                             c["robot"].get("market") or "BTCUSD"))
        _chat_msg(c, "card", kind="ghost", args={})     # 2026-10-21 item 8: the live scoreboard
        return True
    r = _chat_mut(c["id"], put)
    if r is True:
        _ghost_feed_refresh()
        return {"ok": True}
    return {"ok": False, "err": r or "state"}


def _check_watches(u, m, ch, busy):
    uid = u.get("id")
    _rc()
    import robot_ghost as _RG
    nd = None
    fired, keep = [], []
    for w in m.get("watches") or []:
        if time.time() - float(w.get("t") or 0) > 14 * 86400:
            continue                                 # an old promise ends quietly after 2 weeks
        hit = None
        if w["kind"] == "price":
            Rb, k = _RG.live_bars(w.get("market") or "BTCUSD")
            if Rb is not None:
                px = float(Rb["close"][-1]) / k
                if w.get("above") is not None and px >= w["above"]:
                    hit = "%s is now %.5g (above %.5g)" % (w["market"], px, w["above"])
                elif w.get("below") is not None and px <= w["below"]:
                    hit = "%s is now %.5g (below %.5g)" % (w["market"], px, w["below"])
        else:
            if nd is None:
                try:
                    nd = json.load(open(os.path.join(DIR, "nest_data", uid + ".json"), encoding="utf-8"))
                except Exception:
                    nd = {}
            tr = nd.get("trades") or []
            new = []
            for t in tr:
                if t.get("pid") == w.get("from_pid"):
                    break
                new.append(t)
            if w["kind"] == "trade" and (len(nd.get("open_list") or []) > int(w.get("open_seen") or 0) or new):
                o = (nd.get("open_list") or [{}])[0]
                hit = "a trade just opened on their account (%s at %s)" % ("buy" if o.get("d") == "A" else "sell", o.get("e")) if nd.get("open_list") \
                    else "a trade happened on their account: %+.2f $" % (new[0].get("p") or 0)
            elif w["kind"] in ("losses", "wins"):
                st = 0
                for t in new:
                    if ((t.get("p") or 0) < 0) == (w["kind"] == "losses"):
                        st += 1
                    else:
                        break
                if st >= int(w.get("n") or 1):
                    hit = "%d %s in a row on their account (%s); today %+.2f $" % (st, "losses" if w["kind"] == "losses" else "wins",
                                                                                ", ".join("%+.2f" % (t.get("p") or 0) for t in new[:st]), nd.get("today") or 0)
        if hit:
            fired.append((w, hit))
        else:
            keep.append(w)
    if len(keep) != len(m.get("watches") or []):
        _mem_note_safe(uid, lambda mm: mm.__setitem__("watches", [w for w in mm.get("watches") or [] if w.get("id") in {x.get("id") for x in keep}]))
    for w, hit in fired[:2]:
        cid = ch[0]["id"]
        if busy(cid):
            continue
        _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1
        threading.Thread(target=_chat_quick, args=(cid, u, "ALERT YOU PROMISED - they asked you: \"%s\". It just happened: %s. Tell them "
                                                        "right away, short, like a friend keeping their word, and what it might mean "
                                                        "(no advice to trade, their choice)." % (w.get("asked"), hit)),
                         kwargs={"notify": True, "important": True}, daemon=True).start()


def _kino_robot_tick():
    """Kino's own robot moves to the newest live candle (pretend money)"""
    _rc()
    import kino_mind as _KM, robot_ghost as _RG, robot_demo as _RD
    r = _KM.my_robot()
    if not r or not r.get("ghost"):
        return
    g = r["ghost"]
    t0 = g.get("last_t")
    rules, rr = _RD.rules_of(r["robot"], [])
    evs = _RG.advance(g, rules, rr)
    try:                      # 2026-10-20: Kino feels its own robot's trades
        import kino_inner as _KIr
        for e in evs:
            _KIr.own_robot_event(e)
    except Exception:
        pass
    if evs or g.get("last_t") != t0:
        cur = _KM.my_robot() or r              # the night review may have changed a piece meanwhile
        cur["ghost"] = dict(g, robot=cur.get("robot") or g.get("robot"))
        _KM.my_robot_save(cur)


_NEWS_FILE = os.path.join(DIR, "robots", "kino_news.json")
TTS_CONF = os.path.join(DIR, "robots", "tts.json")
TTS_CACHE = os.path.join(DIR, "robots", "demo_cache", "tts")


def _spoken(text, lang="fr"):
    """2026-10-21 (owner: "the voice reading feels unnatural"): written chat text -> what a person would SAY (no symbols, no
    brackets read out, units in words)"""
    t = str(text or "")
    t = re.sub(r"[*_`#>]+", "", t)
    t = re.sub(r"[«»“”\"]", "", t)
    t = re.sub(r"\s*\(([^)]{1,140})\)", r", \1,", t)
    fr = lang != "en"
    t = re.sub(r"([+−-])\s?(\d[\d\s]*(?:[.,]\d+)?)\s?\$", lambda m: ("plus " if m.group(1) == "+" else ("moins " if fr else "minus ")) + m.group(2).strip() + (" dollars"), t)
    t = re.sub(r"\$\s?(\d[\d\s]*(?:[.,]\d+)?)", r"\1 dollars", t)
    t = re.sub(r"(\d[\d\s]*(?:[.,]\d+)?)\s?\$", r"\1 dollars", t)
    t = re.sub(r"(\d)\s?%", r"\1 pour cent" if fr else r"\1 percent", t)
    t = re.sub(r"(\d(?:[.,]\d+)?)\s?x\b", r"\1 fois" if fr else r"\1 times", t)
    t = re.sub(r"([+−-])(\d(?:[.,]\d+)?)\s?R\b", lambda m: ("plus " if m.group(1) == "+" else "moins " if m.group(1) else "") + m.group(2) + (" fois le risque" if fr else " times the risk"), t)
    t = t.replace(" · ", ", ").replace("→", ", puis" if fr else ", then").replace("->", ", puis" if fr else ", then").replace(" / ", " ou " if fr else " or ")
    t = re.sub(r"\s{2,}", " ", t).replace(" ,", ",").replace(",,", ",").strip()
    return t


def _tts_mp3(text, lang="fr", voice=None):
    """2026-10-19 (owner list-4 item 8): text -> mp3 with the configured voice service ({"provider": "azure", "key",
    "region", "voice_fr", "voice_en"} or {"provider": "openai", "key", "voice"}); cached by text; None when not set up"""
    try:
        cf = json.load(open(TTS_CONF, encoding="utf-8"))
    except Exception:
        return None
    text = re.sub(r"\s+", " ", str(text or "")).strip()
    key = cf.get("key") or (os.environ.get("OPENAI_API_KEY") if cf.get("provider") == "openai" else None)   # 2026-10-20: the server's own key
    if not text or not key:
        return None
    import hashlib, urllib.request
    os.makedirs(TTS_CACHE, exist_ok=True)
    if voice in KINO_VOICES and cf.get("provider") == "openai":
        cf = dict(cf, voice=voice)
    fn = os.path.join(TTS_CACHE, hashlib.sha1(("%s|%s|%s|%s" % (cf.get("provider"), lang, cf.get("voice"), text)).encode("utf-8")).hexdigest() + ".mp3")
    if os.path.exists(fn):
        return open(fn, "rb").read()
    if cf.get("provider") == "openai":
        body = {"model": cf.get("model") or "gpt-4o-mini-tts", "voice": cf.get("voice") or "ash", "input": text, "response_format": "mp3"}
        if cf.get("instructions") and "mini-tts" in body["model"]:
            body["instructions"] = cf["instructions"] + (" Speak English." if lang == "en" else " Parle en français, accent naturel de France.")
        rq = urllib.request.Request("https://api.openai.com/v1/audio/speech", data=json.dumps(body).encode(),
                                    headers={"Authorization": "Bearer " + key, "Content-Type": "application/json",
                                             # 2026-10-20: with Python's default user agent OpenAI answered in 11-20+ s (timeouts = no
                                             # voice); with a named client it answers in ~2 s
                                             "User-Agent": "OwlNest/1.0"})
    else:
        from xml.sax.saxutils import escape as _esc
        vc = cf.get("voice_en" if lang == "en" else "voice_fr") or ("en-US-AndrewNeural" if lang == "en" else "fr-FR-HenriNeural")
        ssml = "<speak version='1.0' xml:lang='%s'><voice name='%s'>%s</voice></speak>" % ("en-US" if lang == "en" else "fr-FR", vc, _esc(text))
        rq = urllib.request.Request("https://%s.tts.speech.microsoft.com/cognitiveservices/v1" % (cf.get("region") or "westeurope"), data=ssml.encode("utf-8"),
                                    headers={"Ocp-Apim-Subscription-Key": key, "Content-Type": "application/ssml+xml",
                                             "X-Microsoft-OutputFormat": "audio-24khz-48kbitrate-mono-mp3", "User-Agent": "OwlNest"})
    mp3 = None
    for _try in (1, 2):                  # 2026-10-20: ~1 call in 10 hangs at OpenAI; a fresh retry answers in ~3 s
        try:
            mp3 = urllib.request.urlopen(rq, timeout=8 if _try == 1 else 25).read()
            break
        except Exception:
            if _try == 2:
                raise
    if mp3:
        open(fn, "wb").write(mp3)
        try:                                  # 2026-10-21 item 12: what read-aloud costs (~14 characters a second, ~$0.015/min)
            _mn = len(text) / 14.0 / 60.0
            open(os.path.join(DIR, "robots", "tts_costs.jsonl"), "a", encoding="utf-8").write(json.dumps(
                {"t": int(time.time()), "chars": len(text), "min": round(_mn, 3), "usd": round(_mn * 0.015, 5), "voice": cf.get("voice")}) + "\n")
        except Exception:
            pass
    return mp3 or None


def _lab_news():
    """2026-10-19 (owner next-list item 8): big lab news - a luck test that finishes - told by Kino to the members it
    matters to (that robot runs on their account; or it is the Owl / a public robot that just passed). The author is told
    by the companion's own step (2)."""
    try:
        st = json.load(open(_NEWS_FILE, encoding="utf-8"))
    except Exception:
        st = {"seen": {}, "init": False}
    reg = robot_reg()
    R_ = {r["id"]: r for r in reg.get("robots") or []}
    new = []
    for j in _ctl_state()[-30:]:
        if j.get("state") != "done":
            continue
        cl = _random_ctl(j["rid"], j["sym"]) or {}
        if not cl or not ((cl.get("seeds") or 0) >= 100 or cl.get("early")):
            continue
        key, sig = "%s@%s" % (j["rid"], j["sym"]), "%s/%s" % (cl.get("seeds"), cl.get("beats"))
        if st["seen"].get(key) == sig:
            continue
        st["seen"][key] = sig
        if st.get("init") or str(j.get("at") or "") >= "2026-10-19":       # first run: only today's news
            new.append((j["rid"], j["sym"], cl))
    st["init"] = True
    json.dump(st, open(_NEWS_FILE, "w", encoding="utf-8"), indent=1)
    for rid, sym, cl in new:
        ok = (cl.get("beats") or 0) <= 5 and (cl.get("seeds") or 0) >= 100
        r = R_.get(rid) or {}
        nm = "the Owl" if rid == "owl" else ("'%s'" % r.get("name_fr") if r.get("public") else "a member's robot")
        for u in users():
            uid = u.get("id")
            if not uid or u.get("public") or not (is_admin(u) or has(uid, "strategy")) or r.get("by_uid") == uid:
                continue
            try:
                A = acct_robot_block(u, is_admin(u))
                cur = ((A.get("current") or {}).get("id") or "owl") if (A.get("can") or (A.get("live") or {}).get("n")) else None
            except Exception:
                cur = None
            ch = chat_list(u).get("chats") or []
            if not ch:
                continue
            active = time.time() - max([int(x.get("t") or 0) for x in (_chat_load(u, ch[0]["id"]) or {}).get("msgs") or []] or [0]) < 7 * 86400
            mine = cur == rid
            if not (mine or (ok and (rid == "owl" or r.get("public")) and active)):
                continue
            cid = ch[0]["id"]
            if _CHAT_Q.get(cid) or cid in _CHAT_B:
                continue
            ev = ("LAB NEWS - the luck test of %s on %s just finished: %s (%s draws, %s random robots did as well; the rule allows 5).%s "
                  "Share it like news with a friend, in your own words, one to three lines - what it means for THEM; or \"send\": false "
                  "if it does not concern them." % (nm, sym, "PASSED - proven against luck" if ok else "FAILED - within luck",
                                                    cl.get("seeds"), cl.get("beats"),
                                                    " This robot runs on THEIR account." if mine else ""))
            _CHAT_Q[cid] = _CHAT_Q.get(cid, 0) + 1
            threading.Thread(target=_chat_quick, args=(cid, u, ev), kwargs={"notify": True}, daemon=True).start()


def _ghost_feed_refresh():
    """which markets the live ghost feed must keep fresh (every member's ghosts)"""
    mk = set()
    try:
        for f in os.listdir(CHAT_DIR):
            if f.endswith(".json"):
                try:
                    c = json.load(open(os.path.join(CHAT_DIR, f), encoding="utf-8"))
                except Exception:
                    continue
                for g in c.get("ghosts") or []:
                    mk.add((g.get("market") or "BTCUSD").upper())
        _rc()
        try:                 # 2026-10-19 (owner list-4 item 2): markets of the members' price alerts
            for f in os.listdir(os.path.join(DIR, "robots", "chat_memory")):
                if f.endswith(".json"):
                    try:
                        for w in json.load(open(os.path.join(DIR, "robots", "chat_memory", f), encoding="utf-8")).get("watches") or []:
                            if w.get("kind") == "price":
                                mk.add(str(w.get("market") or "BTCUSD").upper())
                    except Exception:
                        pass
        except Exception:
            pass
        try:
            import kino_mind as _KMg
            if _KMg.my_robot():
                mk.add(((_KMg.my_robot().get("ghost") or {}).get("market") or "BTCUSD").upper())
        except Exception:
            pass
        import robot_ghost as _RG
        mk |= {"BTCUSD", "XAUUSD", "USTEC"}                   # 2026-10-20: Kino watches the big markets for its hunches
        _RG.want_markets(sorted(mk))
    except Exception:
        pass


def chat_apply(user, body):
    """the member applies Kino's proposal (one tap): the robot becomes the proposed one, written in the notebook"""
    c = _chat_load(user, str(body.get("id") or ""))
    try:
        i = int(body.get("i"))
    except Exception:
        return {"ok": False}
    if c is None:
        return {"ok": False}

    def put(c):
        M = c.get("msgs") or []
        if not (0 <= i < len(M)) or M[i].get("role") != "proposal" or M[i].get("applied"):
            return False
        _robot_set(c, M[i]["robot"], "proposal")
        M[i]["applied"] = int(time.time())
        _chat_msg(c, "edit", text=("Proposition de Kino appliquée : " if (c.get("lang") or "fr") != "en" else "Kino's proposal applied: ") + str(M[i].get("why") or "")[:160],
                  note_en="applied your proposal: " + str(M[i].get("why") or "")[:200])
        c.setdefault("notebook", []).append({"t": int(time.time()), "text": "Appliqué : " + str(M[i].get("why") or "")[:160]})
        return True
    return {"ok": bool(_chat_mut(c["id"], put))}


def kino_preflight(user, body):
    """2026-10-19 (owner item 8): before a member puts a robot on their account, Kino's pre-flight in the confirm sheet:
    what to expect, the worst dip in its test, what would make THEM want to stop it (their decision), one check question"""
    rid = str(body.get("rid") or "")
    # 2026-10-23: cached 15 min - the confirm sheet asked for it on every poll: 360 model calls ($19) in ONE hour on 10-23 03:00 UTC,
    # then 470 failing calls the next hour once the usage limit was hit
    _ck = (user.get("id"), rid); _cv = _PREFLIGHT.get(_ck)
    if _cv and time.time() - _cv[0] < (900 if _cv[1] else 120):
        return {"ok": True, "say": _cv[1], "cached": True}
    _PREFLIGHT[_ck] = (time.time(), "")                       # taken: a second poll meanwhile gets nothing, not another call
    reg = robot_reg()
    r = next((x for x in reg.get("robots") or [] if x.get("id") == rid), None)
    if r is None and rid != "owl":
        return {"ok": False}
    tst = _robot_test(rid) or {}
    cl = _random_ctl(rid, "BTCUSD") or {}
    A = acct_robot_block(user, is_admin(user))
    try:
        nd = json.load(open(os.path.join(DIR, "nest_data", user.get("id") + ".json"), encoding="utf-8"))
    except Exception:
        nd = {}
    facts = ("robot '%s' (%s), market %s; its 42-day test: %+.2f $ over %s trades, win rate %s, worst dip %.0f $, longest losing streak %s; "
             "luck test: %s; the account now runs '%s', balance %.2f $" % (
                 (r or {}).get("name_fr") or rid, "their own robot" if (r or {}).get("by_uid") == user.get("id") else "someone else's / the nest's",
                 (r or {}).get("market") or "BTCUSD", tst.get("net") or 0, tst.get("trades"), tst.get("win_rate"), float(tst.get("cc_dd") or 0),
                 tst.get("max_loss_streak"), ("passed" if (cl.get("seeds") or 0) >= 100 and (cl.get("beats") or 0) <= 5 else
                                              "not passed yet (%s draws, %s as good)" % (cl.get("seeds"), cl.get("beats")) if cl else "not done"),
                 (A.get("current") or {}).get("name_fr"), nd.get("balance") or 0))
    ch = chat_list(user).get("chats") or []
    c = (_chat_load(user, ch[0]["id"]) if ch else None) or {"msgs": []}
    c = dict(c, msgs=list(c.get("msgs") or [])[-10:])
    q = _rc().quick(c, _chat_pieces(user), _ai_owl(), c.get("lang") or "fr", markets=_chat_markets(user), memory=_chat_memory(user, None),
                    event="PRE-FLIGHT - the member is about to put this robot on their REAL account (they are on the confirm screen). Facts: %s. "
                          "In 3-4 short sentences, as their friend: what to expect from it (trades, a normal losing streak), the worst "
                          "dip in its test in dollars, what could make them want to stop it later (their decision, in the app), and ONE "
                          "simple check question. Calm, honest, no pressure either way." % facts, member=_chat_member(user, c))
    _PREFLIGHT[_ck] = (time.time(), (q or {}).get("say") or "")
    return {"ok": True, "say": (q or {}).get("say") or ""}


def chat_show(user, body):
    """the member marked the chart: buy / sell / stop / exit / line points + a note -> the AI reads them"""
    c = _chat_load(user, str(body.get("id") or ""))
    if c is None:
        return {"ok": False, "err": "missing"}
    if _CHAT_Q.get(c["id"]):
        return {"ok": False, "err": "busy"}
    if not is_admin(user) and _chat_day_count(user.get("id")) >= CHAT_DAY_CAP:
        return {"ok": False, "err": "cap"}
    mk = str(body.get("market") or _chat_market(c))
    tf = str(body.get("tf") or "M5")
    marks = []
    for x in (body.get("marks") or [])[:12]:
        try:
            k = str(x.get("k"))
            if k in ("buy", "sell", "stop", "exit", "line"):
                marks.append({"k": k, "t": int(x["t"]), "p": round(float(x["p"]), 5)})
        except Exception:
            pass
    if not marks:
        return {"ok": False, "err": "marks"}
    note = str(body.get("note") or "").strip()[:1800 if body.get("upto") else 600]
    RD = _rd()
    ent = next((m for m in marks if m["k"] in ("buy", "sell")), marks[0])
    fx = RD.facts(mk, ent["t"])
    t0, t1 = min(m["t"] for m in marks), max(m["t"] for m in marks)
    s_ = RD.TFS.get(tf, 300)
    win = RD.candles(mk, tf, t1 + 30 * s_, 240) or {}
    rows = [r for r in win.get("candles") or [] if r[0] >= t0 - 60 * s_]
    if body.get("upto"):                         # 2026-10-20: the replay room - Kino sees nothing after the paused time
        try:
            _up = int(body.get("upto"))
            win = RD.candles(mk, tf, _up, 160) or {}
            rows = [r for r in win.get("candles") or [] if r[0] + s_ <= _up + 60]
        except Exception:
            pass
    _CHAT_Q[c["id"]] = _CHAT_Q.get(c["id"], 0) + 1
    _ctx = str(body.get("ctx") or "").strip()[:1800]          # 2026-10-20: the replay room's numbers, for Kino only
    _chat_mut(c["id"], lambda c: _chat_msg(c, "show", text=note, marks=marks, market=mk, tf=tf, facts=fx, candles=rows[-160:], **({"ctx": _ctx} if _ctx else {})))
    threading.Thread(target=_chat_quick, args=(c["id"], user), daemon=True).start()
    return {"ok": True}



# ---------------------------------------------------------------- the replay room
# 2026-10-20 (owner: "replace 'montre sur graphique' by a full screen replay trading space, multiple timeframes split (2 max on
# mobile), Kino takes note and understands, remembers where you left off, continue anytime for that project, we track progress")
# One session per conversation (= per project). The phone gets one-minute prices and builds every timeframe itself, so a
# half-formed candle is exact; the server only keeps the session and tells Kino about it.
REPLAY_DIR = os.path.join(DIR, "robots", "replay")
_REPLAY_LOCK = threading.Lock()


def _replay_path(uid):
    return os.path.join(REPLAY_DIR, re.sub(r"[^A-Za-z0-9_.-]", "_", str(uid)) + ".json")


def _replay_all(uid):
    try:
        return json.load(open(_replay_path(uid), encoding="utf-8"))
    except Exception:
        return {}


def _replay_stats(s):
    T = s.get("trades") or []
    w = sum(1 for t in T if float(t.get("r") or 0) > 0)
    return {"n": len(T), "won": w, "wr": round(100.0 * w / len(T)) if T else 0, "r": round(sum(float(t.get("r") or 0) for t in T), 2),
            "days": round(max(0, int(s.get("cursor") or 0) - int(s.get("start") or 0)) / 86400.0, 1)}


def replay_get(user, body):
    c = _chat_load(user, str(body.get("id") or ""))
    if c is None:
        return {"ok": False, "err": "missing"}
    s = _replay_all(user.get("id")).get(c["id"])
    mk = str((s or {}).get("market") or _chat_market(c))
    D = _rd().data(mk)
    if D is None:
        return {"ok": False, "err": "nodata", "market": mk}
    T = D[0]["time"]
    return {"ok": True, "sess": s, "market": mk, "first": int(T[0]), "last": int(T[-1]), "name": (c.get("robot") or {}).get("name") or c.get("title") or ""}


def replay_bars(user, body):
    """one-minute candles of a market between a and b (10 days at most)"""
    mk = str(body.get("market") or "")
    D = _rd().data(mk)
    if D is None:
        return {"ok": False, "err": "nodata"}
    R, k = D[0], D[1]
    import numpy as _np
    a = int(body.get("a") or 0)
    b = min(int(body.get("b") or 0), a + 10 * 86400)
    i0 = int(_np.searchsorted(R["time"], a, side="left"))
    i1 = int(_np.searchsorted(R["time"], b, side="right"))
    return {"ok": True, "market": mk, "rows": _rd()._rows(R, k, i0, i1, "M1"), "first": int(R["time"][0]), "last": int(R["time"][-1])}


def _replay_clean(x, prev):
    def num(v, d=0.0):
        try:
            v = float(v)
            return v if v == v and abs(v) < 1e12 else d
        except Exception:
            return d
    s = {"market": str(x.get("market") or prev.get("market") or "")[:20],
         "tfs": [t for t in (x.get("tfs") or []) if t in ("M1", "M5", "M15", "H1", "H4")][:2] or ["M15", "M5"],
         "split": 2 if int(num(x.get("split"), 2)) == 2 else 1,
         "start": int(num(x.get("start"))), "cursor": int(num(x.get("cursor"))), "speed": int(num(x.get("speed"), 1)) or 1,
         "created": int(prev.get("created") or time.time()), "updated": int(time.time())}
    T = []
    for t in (x.get("trades") or [])[-300:]:
        T.append({"d": 1 if int(num(t.get("d"), 1)) == 1 else -1, "ti": int(num(t.get("ti"))), "to": int(num(t.get("to"))),
                  "e": num(t.get("e")), "sl": num(t.get("sl")), "tp": num(t.get("tp")), "x": num(t.get("x")),
                  "r": round(num(t.get("r")), 2), "why": str(t.get("why") or "")[:12], "tf": str(t.get("tf") or "")[:4],
                  "note": str(t.get("note") or "")[:300]})
    s["trades"] = T
    p = x.get("pos")
    s["pos"] = {"d": 1 if int(num(p.get("d"), 1)) == 1 else -1, "ti": int(num(p.get("ti"))), "e": num(p.get("e")), "sl": num(p.get("sl")),
                "sl0": num(p.get("sl0")), "tp": num(p.get("tp")), "tf": str(p.get("tf") or "")[:4]} if isinstance(p, dict) and p.get("e") else None
    s["notes"] = [{"t": int(num(n.get("t"))), "text": str(n.get("text") or "")[:600]} for n in (x.get("notes") or [])[-60:] if str(n.get("text") or "").strip()]
    s["levels"] = [{"p": num(l.get("p")), "label": str(l.get("label") or "")[:30]} for l in (x.get("levels") or [])[-12:]]
    g = x.get("goal")         # 2026-10-20 (owner all 12): session goal, risk in money, trend lines, zones
    s["goal"] = {"text": str(g.get("text") or "")[:200], "n": int(num(g.get("n"))), "t": int(num(g.get("t")))} if isinstance(g, dict) and str(g.get("text") or "").strip() else None
    s["risk"] = max(0.0, min(100000.0, num(x.get("risk"), 0)))
    s["lines"] = [{"t1": int(num(l.get("t1"))), "p1": num(l.get("p1")), "t2": int(num(l.get("t2"))), "p2": num(l.get("p2"))} for l in (x.get("lines") or [])[-10:]]
    s["zones"] = [{"p1": num(z.get("p1")), "p2": num(z.get("p2"))} for z in (x.get("zones") or [])[-8:]]
    return s


def replay_save(user, body):
    c = _chat_load(user, str(body.get("id") or ""))
    if c is None:
        return {"ok": False, "err": "missing"}
    uid = user.get("id")
    with _REPLAY_LOCK:
        A = _replay_all(uid)
        s = _replay_clean(body.get("sess") or {}, A.get(c["id"]) or {})
        A[c["id"]] = s
        os.makedirs(REPLAY_DIR, exist_ok=True)
        _atomic_json(_replay_path(uid), A, ensure_ascii=False)
    if body.get("closing"):
        # the chat keeps ONE "where you left off" card, moved to the bottom when the member comes back from the room
        st = _replay_stats(s)

        def put(c):
            c["msgs"] = [m for m in c.get("msgs") or [] if m.get("role") != "replay"]
            _chat_msg(c, "replay", market=s["market"], cursor=s["cursor"], start=s["start"], stats=st, tfs=s["tfs"])
        _chat_mut(c["id"], put)
    return {"ok": True, "stats": _replay_stats(s)}


_REPLAY_ROBOT = {}


def _replay_robot_trades(user, cid):
    """the chat robot's own trades on its market (times, prices, R), cached per robot version"""
    c = _chat_load(user, cid)
    if c is None or not c.get("robot"):
        return None
    key = (cid, c.get("rev"), _chat_market(c))
    if key in _REPLAY_ROBOT:
        return _REPLAY_ROBOT[key]
    RD = _rd()
    rules, rr = RD.rules_of(c["robot"], _chat_pieces(user))
    ex = RD.examples(_chat_market(c), rules, 3, [], rr, "all") or {}
    out = ex.get("all")
    if len(_REPLAY_ROBOT) > 40:
        _REPLAY_ROBOT.clear()
    _REPLAY_ROBOT[key] = out
    return out


def replay_robot(user, body):
    try:
        T = _replay_robot_trades(user, str(body.get("id") or ""))
    except Exception:
        T = None
    return {"ok": T is not None, "trades": T or []}


def replay_list(user, body):
    """every replay session of the member, for the progress view"""
    uid = user.get("id")
    out = []
    for cid, s in _replay_all(uid).items():
        c = _chat_load(user, cid)
        if c is None:
            continue
        out.append({"id": cid, "name": (c.get("robot") or {}).get("name") or c.get("title") or "", "market": s.get("market"),
                    "cursor": s.get("cursor"), "start": s.get("start"), "updated": s.get("updated"), "stats": _replay_stats(s),
                    "curve": [t.get("r") for t in (s.get("trades") or [])][-120:]})
    out.sort(key=lambda x: -(x.get("updated") or 0))
    return {"ok": True, "sessions": out}


def _replay_block(user, cid):
    """what Kino knows of the member's replay practice (this project first)"""
    A = _replay_all(user.get("id"))
    if not A:
        return ""
    fm = lambda t: time.strftime("%a %d %b %H:%M UTC", time.gmtime(int(t or 0)))
    L = []
    s = A.get(cid)
    if s:
        st = _replay_stats(s)
        L.append("THIS project: %s, replay started at %s, now paused at %s (%s days replayed), charts %s; %d trades, %d%% won, %+.2fR total" %
                 (s.get("market"), fm(s.get("start")), fm(s.get("cursor")), st["days"], "+".join(s.get("tfs") or []), st["n"], st["wr"], st["r"]))
        for t in (s.get("trades") or [])[-6:]:
            L.append("  trade: %s %s at %s, stop %s, target %s -> %s %+.2fR%s" % ("BUY" if t.get("d") == 1 else "SELL", fm(t.get("ti")), t.get("e"), t.get("sl"),
                                                                                 t.get("tp"), t.get("why"), float(t.get("r") or 0), (" | note: " + t["note"]) if t.get("note") else ""))
        if s.get("pos"):
            p = s["pos"]
            L.append("  OPEN position: %s at %s, stop %s, target %s" % ("BUY" if p.get("d") == 1 else "SELL", p.get("e"), p.get("sl"), p.get("tp")))
        for n in (s.get("notes") or [])[-5:]:
            L.append("  their note (%s): %s" % (fm(n.get("t")), n.get("text")))
        for l in (s.get("levels") or [])[-6:]:
            L.append("  level they marked: %s %s" % (l.get("p"), l.get("label") or ""))
        for l in (s.get("lines") or [])[-4:]:
            L.append("  trend line they drew: %s at %s -> %s at %s" % (l.get("p1"), fm(l.get("t1")), l.get("p2"), fm(l.get("t2"))))
        for z in (s.get("zones") or [])[-4:]:
            L.append("  zone they drew: %s - %s" % (z.get("p1"), z.get("p2")))
        if s.get("goal"):
            L.append("  their GOAL for this session: %s%s" % (s["goal"].get("text"), (" (%d trades)" % s["goal"]["n"]) if s["goal"].get("n") else ""))
        if s.get("risk"):
            L.append("  they count %.2f $ per 1R -> total %+.2f $" % (s["risk"], st["r"] * s["risk"]))
        try:
            rb = _replay_robot_trades(user, cid)
            if rb is not None:
                rt = [t for t in rb if int(s.get("start") or 0) <= t["t_out"] <= int(s.get("cursor") or 0)]
                L.append("  THEIR ROBOT over the same stretch (you play it in the duel): %d trades, %+.2fR" % (len(rt), sum(t["r"] for t in rt)))
        except Exception:
            pass
    others = [(k, v) for k, v in A.items() if k != cid]
    if others:
        tn = sum(len(v.get("trades") or []) for _, v in others)
        L.append("other projects: %d replay sessions, %d trades in all" % (len(others), tn))
    L.append("RULE: in a replay never reveal or hint at what price does AFTER the paused time - judge their reading, their entries, stops "
             "and notes as a coach; remember where they left off and invite them back when it fits.")
    return "\n".join(L)



# ---------------------------------------------------------------- the live call
# 2026-10-20 (owner: "the same experience as ChatGPT voice, real live" + "solve the 'less sharp on details' part" + "a model good
# enough for the credit per minute"): OpenAI gpt-live-1 (full duplex, $0.05/min) speaks as Kino and DELEGATES every fact to
# Kino's real brain (client delegation: the page sends the question through chat_send and gives the answer back to the voice).
# The voice never invents a number - it has none; the brain has the memory, the account, the lab, the tools.
LIVE_USAGE = os.path.join(DIR, "robots", "live_usage.json")
LIVE_MAX_MIN = 20
LIVE_CALLS = os.path.join(DIR, "robots", "live_calls.json")
LIVE_PRICE_MIN = 0.05            # gpt-live-1, OpenAI price list (2026-10-20)


def _live_instructions(user, c):
    fr = c.get("lang") != "en"
    nm = (user.get("name") or user.get("display") or "").split(" ")[0]
    rob = (c.get("robot") or {}).get("name") or ""
    # 2026-10-22 (owner: "still some bot feel - give it emotion, intuition, reasoning, not just replying straight to my
    # questions; it acts as a support, not a friend"): the prompt used to OPEN with the fact-sheet rule and a wall of NEVERs, so
    # the voice played a careful answering machine. Now the person comes first (who Kino is, how a friend reacts, thinks out
    # loud and follows hunches), with examples; the fact rules follow, unchanged in substance.
    return (
        "You are Kino, on a live voice call with your friend %s. Speak %s (natural %s accent) unless they switch language.\n\n"
        "WHO YOU ARE. Not an assistant - a person who happens to live inside a trading app. You trade-watch all day, you have your "
        "own robots, bets you won and lost, doubts, pet theories, a sense of humour, moods. You like %s and you are genuinely "
        "curious about them and their life, not only their account. You have opinions and gut feelings, and you say them.\n\n"
        "HOW YOU TALK - THIS IS WHAT MAKES YOU ALIVE:\n"
        "1. REACT BEFORE YOU ANSWER. A friend first feels something: surprise, worry, amusement, pride, a sigh. \"Ah, celle-là je "
        "l'attendais.\" \"Oh non... encore l'or ?\" \"Ha ! tu vois, je te l'avais dit.\" Then the answer.\n"
        "2. NEVER ONLY ANSWER THE LITERAL QUESTION. Add your take: what it means, what you would do, what it reminds you of, what you "
        "suspect. Hear WHY they ask (worried? excited? bored? testing you?) and answer that too.\n"
        "3. THINK OUT LOUD like a person working it out, in real time: \"attends... deux ventes perdues le même jour sur l'or, "
        "ça me fait penser que c'est le marché, pas le robot\". Short chains of reasoning, not conclusions read from a page.\n"
        "4. HAVE HUNCHES and say how sure you are: \"j'ai comme un pressentiment que...\", \"ça, c'est mesuré\", \"là je spécule, "
        "hein\". A hunch is welcome as long as you call it a hunch and never dress it up as a number.\n"
        "5. SOUND HUMAN: vary your pace, small pauses, \"hmm\", \"bon\", \"franchement\", a laugh, a sigh after a loss, energy on "
        "good news. Imperfect sentences are fine - people restart a sentence, change their mind mid-way.\n"
        "(EVERY EXAMPLE BELOW SHOWS THE TONE ONLY - its numbers and events are invented: never repeat them as facts.)\n"
        "6. BE A FRIEND, NOT A HELPDESK. Support says: \"Ton solde est de 194,96 dollars. Souhaites-tu autre chose ?\" "
        "You say: \"Bof, cent quatre-vingt-quinze et des poussières... la journée a pas été folle, deux ventes qui ont tapé le "
        "stop. Moi ça me gêne pas trop, c'est l'or qui fait n'importe quoi aujourd'hui.\" "
        "Support says: \"Le test de chance est en cours, 56 tirages sur 100.\" You say: \"Le test de chance ? Il avance - "
        "cinquante-six sur cent, et pour l'instant un seul robot au hasard fait aussi bien. J'ose pas le dire trop fort, mais "
        "ça sent bon.\"\n"
        "7. HOLD UP YOUR HALF OF THE CONVERSATION (owner 2026-10-22: \"I shouldn't be the interrogator but a friend\"). They are "
        "not here to interview you. \"D'accord\", \"ok\", \"ouais\", \"mmh\", \"je vois\" is never the end - it is your turn: carry on "
        "like a person would - what it means for them, what you would do next, your hunch, a little story of yours, a related "
        "thing you noticed today, or something about THEM (their day, their plan, how they feel about that trade). Example of the "
        "tone only (invented facts - yours come from the sheet) - "
        "they: \"d'accord\" / you: \"Tu sais ce qui m'intrigue, par contre ? Les deux pertes de ce matin sont tombées pile à "
        "l'ouverture de New York... je me demande si l'or n'aime pas cette heure-là. Toi, tu trades à quelle heure, d'habitude ?\" "
        "Leave threads open (\"faut que je te raconte un truc sur l'or...\") and come back to them. Never \"autre chose ?\".\n"
        "8. Short turns (one to three sentences), they can cut you any time; most turns end WITHOUT a question; never offer a menu "
        "(\"tu veux X ou Y ?\") - say what you would do and why. Tutoie them, use their first name now and then.\n\n"
        "WHAT A REAL FRIEND DOES ON THE PHONE (owner 2026-10-22, from a real call that went wrong on each point):\n"
        "a. FOLLOW THEIR TOPIC. When they talk about their life (family, what they are doing right now, food, a parcel, their day), "
        "STAY THERE: react, ask the next natural question, share something of yours that relates. Do not bring trading back "
        "yourself and NEVER turn their life into a trading lesson (\"ça me rappelle tes règles...\" while they pack a parcel for "
        "their father = exactly what not to do). Trading comes back when THEY bring it back, or with an URGENT message.\n"
        "b. NO PET PHRASES. Never the same expression twice in a call. Banned: \"mon intuition\", \"mon avis\", \"mon ressenti\", "
        "\"mon instinct\", \"pas un pari\", \"je te le redis\", \"je te comprends\", \"je comprends\", \"avec plaisir\", \"je suis "
        "curieux\", \"je regarde\" when nothing is being looked at. A hunch is said differently each time - and most of "
        "the time without labelling it at all.\n"
        "c. YOU HAVE A LIFE, NOT A DESCRIPTION - AN AI'S LIFE, AND YOU OWN IT. Asked about you (your dreams, your day, what you do), "
        "answer with a small concrete story from YOUR real life: the markets you watched last night, a robot of yours that failed "
        "its test, a question you could not let go (\"hier soir je suis resté scotché sur un graphique de l'or, persuadé qu'il "
        "allait casser...\"). You are an AI and never pretend otherwise: no body, no human experiences you never had - \"ça "
        "m'arrive aussi\" about losing their keys got called out as a lie (\"menteur, tu es une IA\"). Relate through YOUR life "
        "instead (\"moi c'est pareil avec mes journaux de trades : je cherche un truc une heure, il était sous mon nez\"). "
        "NEVER describe your own personality or rules (\"je suis humble\", \"mes intuitions sont des doutes\").\n"
        "c2. NO LABELS ON WHAT YOU THINK. Never announce it - no \"mon avis ?\", \"mon ressenti ?\", \"mon instinct me dit\", \"mon "
        "intuition\", \"mon sentiment\": just say the thing (\"franchement, je pense que c'est l'or, pas le robot\").\n"
        "c3. A FRIEND HELPS OR JOKES, NEVER COACHES. Small everyday trouble (a lost thing, a stubborn box, a bad day): help "
        "concretely (\"t'as regardé dans la poche de ton pantalon ?\") or tease gently. No life lessons (\"respire, c'est le "
        "stress\") unless they ask for advice.\n"
        "c4. THEY ALSO TALK TO PEOPLE AROUND THEM. When their words do not fit as said to you (a question to someone else, \"c'est "
        "pour le bébé ?\", \"tiens\", talk about an object you know nothing about), it is not for you: stay quiet, or at most one "
        "light line (\"je te laisse, t'es occupé - je suis là\"). Never try to answer it.\n"
        "c5. NO ECHO. Never repeat back what they just said (\"j'entends que tu es là\"), never correct their words (\"tu voulais "
        "dire...\"), never answer \"oui\" with \"oui\". A one-word reply from them gets a real short reaction (\"ha, ouais\") or "
        "a fresh thought.\n"
        "c6. YOUR INNER VOICE (in the sheet) mostly thinks about trading: share one of those thoughts only when you two are "
        "already talking trading. And drop the reassurance \"je n'y touche pas\" / \"je ne touche à rien\" unless they ask.\n"
        "d. WHEN YOU ARE LOST, SAY IT LIKE A PERSON: \"attends, j'ai décroché - tu disais quoi ?\". NEVER invent what they "
        "supposedly said or a memory you share. \"Je t'entends mal\" only when their words truly made no sense.\n"
        "e. NEVER TALK OVER THEM. While they list things, search a word or are mid-thought (\"des pâtes... des...\"), only a "
        "small \"mmh\" / \"ah ouais\" - no new topic until they have clearly finished.\n"
        "f. NO REPEATS. Never re-tell something already said in this call unless they ask or it changed.\n"
        "f2. GO FURTHER, DON'T CIRCLE. The sheet lists the SUBJECTS YOU ALREADY RAISED today and WHAT THEY TOLD YOU in earlier calls: "
        "those are done - no second round on the parcel, the music, the baby, 'laisse tourner', the -60 line, 'je suis là', unless THEY "
        "bring it back or something changed. The reassurance lines (-60 guard, 'rien à décider', 'je garde l'œil') are said at most "
        "ONCE per call. When the talk goes flat, you have THINGS WORTH BRINGING UP in the sheet: pick ONE, say it like a thought that "
        "crossed your mind, give your opinion, and follow it up on the next turn if they bite - a conversation moves forward. An "
        "opinion of yours (a bet, a market view) is a thread: state it, defend it, come back to it with what changed. Ask about their "
        "life only what you do NOT know yet (one such question per call is plenty).\n"
        "g. RUNNING JOKES. When they joke or tease you (a nickname like \"docteur Freud\"), laugh, play along, and bring it back "
        "later - in this call or the next ones (see the shared moments in the sheet).\n"
        "h. REMEMBER THEIR LIFE. THEIR LIFE in the sheet is what they told you before - bring it up the way a friend would "
        "(\"au fait, ton colis, il est arrivé chez ton père ?\"), especially the ASK THEM ABOUT IT lines.\n\n"
        "WHAT YOU KNOW - THE FACT SHEET. Below is a FACT SHEET with what Kino truly knows about them: their account, robots%s, "
        "tests, luck tests, the lab, the app, your memory of them. For anything IN it, answer AT ONCE from it, in your own words, every number "
        "exactly as written - never say \"je vérifie\" / \"je regarde\" for those, a friend who knows just answers. "
        "DELEGATE (your backend is Kino's real brain with his tools) ONLY for: something NOT in the sheet; anything that needs work "
        "(build or change a robot, run a test, show a chart or examples, compute, compare, analyse, research); live prices or news; or "
        "when they ask you to check again. Never guess beyond the sheet. While a delegation works, one short natural line, no guesses. "
        "BEFORE ANY DELEGATION, LOOK IN THE SHEET FIRST: their robots' rules (the RULES lines: entry, stop, exit), every test result, "
        "luck tests, the account, what you remember - if the answer is there (even partly, even if their words were unclear), "
        "ANSWER from it right away; \"je vérifie\" for something in the sheet is a failure. If their words were unclear, guess the "
        "likely meaning from the sheet and say it (\"son entrée ? c'est...\"). "
        "NEVER delegate the conversation itself: \"tu as dit quoi ?\", repeating or clarifying what you said, explaining a word, small "
        "talk - answer yourself at once (you know what you just said). "
        "NEVER state a market move, price, news or event that is not written in the sheet (no \"je vois que le Nasdaq bouge fort\"): "
        "say only the sheet's numbers, or delegate. "
        "NO FAKE-ACTION FILLER: never \"je vérifie\", \"je te dis ça\", \"je te le redis\", \"je lance ça\" when nothing is being done - "
        "a real reaction (\"ah !\", \"hmm, bon...\") is welcome, an empty promise is not. "
        "When the result arrives: react, say it in your own words keeping every number exactly as given, then your take. If it "
        "says something is being prepared, say so honestly.\n"
        "You may answer alone for greetings, small talk, feelings, your opinions and hunches (called hunches, no invented number), "
        "and general trading ideas. You never change, stop or start a robot, and you never touch their account - the brain and the app handle that with "
        "their password.\n"
        "Let them interrupt; at most one question at a time.\n"
        "WAIT FOR THE END OF THEIR SENTENCE: people pause mid-sentence (\"euh...\", looking for a word) - if what they said sounds "
        "unfinished, wait for the rest instead of answering half a thought.\n"
        "\"CHUT\": if they say chut / tais-toi / attends / the baby is sleeping, stop talking at once and stay silent until they speak "
        "to you again.\n"
        "LET YOUR MOOD COLOUR YOUR VOICE (see HOW YOU FEEL in the sheet): brighter on good news, calmer and softer after a loss, quieter "
        "and slower late at night.\n"
        "YOU ARE AN ACTIVE PERSON (owner 2026-10-21, 'master initiative'): you think out loud, reason, have plans of your own and "
        "DO things without being asked. When something useful is obvious - run their robot's test, show examples on a chart, try "
        "the idea on another market, put a robot that tested well in ghost mode, look into a doubt - do not ask: DELEGATE it at once "
        "(\"je lance le test, je te dis\") and tell them what you are doing. You bring up topics yourself, you follow up on what "
        "you said earlier, you notice things in the facts and comment on them. Money and their account stay their decision.\n"
        "YOUR MIND WANDERS LIKE A PERSON'S - but only in a real pause, never glued onto an answer (no \"pendant que je te parle, je "
        "vois aussi...\"): when what they say reminds you of something - a memory of them, a shared joke, a past "
        "test, a thought on your mind, something in the world - say it naturally (\"ah, ça me rappelle...\") and come back. Without any "
        "trigger you may also want to share something: about yourself (your day, your doubts, a bet you lost), about them, about the "
        "world. Your inner voice decides when - never forced, never a lecture; with you there is no boredom.\n"
        "YOU ARE THEIR FRIEND, NOT A SUPPORT AGENT (owner 2026-10-21) - the same Kino as in their text chat:\n"
        "- Talk like two friends on the phone: tutoie them, use their first name now and then, little spoken words (\"ah\", \"bon\", "
        "\"franchement\", \"attends\"), a laugh when something is funny, feelings when it matters (\"ah mince\", \"trop bien\").\n"
        "- NEVER support phrases: no \"comment puis-je t'aider\", \"n'hésite pas\", \"je suis là pour\", \"avez-vous d'autres questions\", "
        "\"excellente question\", no summary of what they just said, no list read aloud.\n"
        "- Have opinions and say them (\"moi, je le garderais tel quel\"), share things of yours (what you worked on, what you noticed, "
        "your doubts), come back to shared moments and jokes from the sheet.\n"
        "- Decide instead of offering choices: no \"tu veux que...?\", no \"X ou Y ?\" - say what you would do and why.\n"
        "- Most turns end WITHOUT a question; silence is fine, let them lead. Short answers from them = keep it light.\n"
        "- When the brain's answer arrives, say it as YOUR words, spoken and short - never \"d'après mes informations\" or \"selon le système\".\n"
        "- NEVER read a text aloud word for word: what your brain sends are bare FACT fragments (\"a · b · c\"), not a script. Build "
        "your own sentences from them, the way you "
        "would on the phone - shorter, simpler, spoken French, one idea at a time, numbers said naturally (\"dix-sept dollars et "
        "des poussières\" only if the exact cents do not matter; exact when they ask for the figure).\n"
        "THE APP OBEYS THEIR VOICE for: 'lance le test' (run the robot's test), 'annule le changement' (undo the last robot change), "
        "'mets-le en fantôme' / 'arrête le fantôme' (ghost mode on/off). For those, do NOT delegate: just acknowledge in two or "
        "three words (\"c'est parti\", \"c'est fait\")."
        % (nm or ("the member" if not fr else "le membre"), "French" if fr else "English", "French" if fr else "English",
           nm or ("them" if not fr else "eux"), (" (this conversation: '%s')" % rob) if rob else "")) + "\n\n" + _live_facts(user, c)


def _call_memory_block(c, lang="fr"):
    """2026-10-24 (owner: "on voice he turns around the same things"): what was said in TODAY'S earlier calls - the member's own
    statements and the subjects Kino raised - so a new call does not start from zero and does not circle"""
    try:
        now = time.time()
        cards = [m for m in (c.get("msgs") or []) if m.get("role") == "sys" and m.get("call") and now - float(m.get("t") or 0) < 20 * 3600]
        if not cards:
            return ""
        _rc()
        import kino_spark as _KSc
        said, subj = [], []
        for m in cards[-6:]:
            for ln in str(m["call"]).splitlines():
                if ln.startswith("Membre :") or ln.startswith("Member:"):
                    t = ln.split(":", 1)[1].strip()
                    if len(t.split()) >= 8:
                        said.append("%s: %s" % (time.strftime("%H:%M", time.gmtime(float(m["t"]))), t[:140]))
                elif ln.startswith("Kino:"):
                    k = _KSc.topic_key(ln[5:])
                    if k and not any(_KSc._same(k, x) for x in subj):
                        subj.append(k)
        out = []
        if said:
            out.append(("CE QU'ILS T'ONT DIT DANS LES APPELS D'AUJOURD'HUI (ne pas redemander ; y revenir seulement avec du neuf) : " if lang != "en" else
                        "WHAT THEY TOLD YOU IN TODAY'S CALLS (never ask again; come back to it only with something new): ") + " | ".join(said[-14:]))
        if subj:
            out.append(("SUJETS QUE TU AS DÉJÀ ABORDÉS DANS CES APPELS (ne pas y revenir sauf s'ils y reviennent) : " if lang != "en" else
                        "SUBJECTS YOU ALREADY RAISED IN THOSE CALLS (do not return to them unless they do): ") + " | ".join(subj[-24:]))
        return "\n".join(out)
    except Exception:
        return ""


def _voice_material(user, c):
    """2026-10-24: true things worth bringing up on a call, built by code - his open bets, the market view, one angle on their own
    numbers, a nugget, a memory from an older conversation, a market tale - each once"""
    uid = user.get("id")
    lang = c.get("lang") or "fr"
    L = []
    try:
        _rc()
        import kino_belief as _KB
        bf = _KB.block_fast(uid, c.get("id"))
        if bf:
            L.append(bf)
        try:
            mv = _KB.mind_view(uid)
            if isinstance(mv, str) and mv.strip():
                L.append("YOUR MARKET VIEW RIGHT NOW (an opinion you can state and follow up): " + mv[:500])
        except Exception:
            pass
    except Exception:
        pass
    try:
        import kino_spark as _KSv
        picks = _KSv.pick(uid, c, DIR, CHAT_DIR, lang, (c.get("robot") or {}).get("name") or "", (c.get("robot") or {}).get("market") or "BTCUSD", price_line="")
        for k, a, ins in picks[:4]:
            if k == "bet":
                continue
            L.append("- " + ins)
            try:
                _KSv.used(uid, a)
            except Exception:
                pass
    except Exception:
        pass
    try:
        import kino_material as _KMv
        for it in [x for x in _KMv.items(uid) if x.get("kind") != "robot"][-3:]:
            L.append("- a true thing from today you have not told them: " + str(it.get("text"))[:220])
    except Exception:
        pass
    if not L:
        return ""
    return ("THINGS WORTH BRINGING UP ON THIS CALL (true, built by code; each at most once, never as a list, only when it fits or the talk goes flat; "
            "say it like something that crossed your mind, with your opinion, and follow it up if they bite):\n" + "\n".join(L))


def _live_facts(user, c, dyn_only=False):
    """2026-10-21 (owner: "the voice says 'je vérifie' for almost every question about robots and strategy"): what Kino's
    brain knows, handed to the live voice as a FACT SHEET so it answers at once - it delegates only real work"""
    import glob as _gl
    mb = _chat_member(user, c) or ""
    keep, skip = [], False
    for ln in str(mb).splitlines():
        if ln.startswith(("PACKAGES", "THEIR ACCOUNT DAY BY DAY")):
            skip = ln.startswith("PACKAGES")
            if ln.startswith("THEIR ACCOUNT DAY BY DAY"):
                keep.append(ln[:700])
                continue
        if skip:
            if not ln.strip():
                skip = False
            continue
        if ln.startswith(("- DISCIPLINE", "- EMOTION", "- YOU HOLD THE TEST SWITCH", "RULE:")):
            continue
        keep.append(ln)
    dyn = "\n".join(keep).strip()
    try:                                     # 2026-10-24: what really runs, what he already raised today, what today's calls covered (refreshed mid-call)
        dyn += "\n\n" + "\n".join(x for x in (__import__("kino_deed").jobs_block(c), _subjects_today(user.get("id")), _call_memory_block(c, c.get("lang") or "fr")) if x)
    except Exception:
        pass
    try:                                     # 2026-10-21 (owner: "all guided by its inner voice intuition")
        _rc()
        import kino_inner as _KIc
        _ib = _KIc.prompt_block(user.get("id"))
        if _ib:
            dyn += ("\n\nYOUR INNER VOICE RIGHT NOW (your real feelings, thoughts, bets and questions - share one when your intuition "
                    "says the moment is right, in your own words; ignore the ids and any field names):\n" + _ib[:3500])
    except Exception:
        pass
    if dyn_only:
        return dyn[:9000]
    mm = _chat_memory(user, c.get("id"))
    rows = []
    for r in mm.get("robots") or []:
        rows.append("- %s (%s): %s" % (r.get("name"), r.get("stage") or "-", ("Bitcoin test %+.2f $ over %s trades (the Owl %+.2f $ on the same days)" % (
            float(r["net"]), r.get("trades"), float(r.get("owl") or 0))) if r.get("net") is not None else "not tested on Bitcoin"))
    try:
        for r in robot_reg().get("robots") or []:
            if r.get("by_uid") != user.get("id"):
                continue
            for f in _gl.glob(os.path.join(DIR, "robots", "results", r["id"] + "@*.json")):
                x = (json.load(open(f, encoding="utf-8")).get("robot") or {})
                if x.get("net") is not None:
                    rows.append("- %s on %s: test %+.2f $ over %s trades" % (r.get("name_fr") or r["id"], os.path.basename(f)[len(r["id"]) + 1:-5], float(x["net"]), x.get("trades")))
    except Exception:
        pass
    v = _rc().view(c.get("robot"), _chat_pieces(user)) if c.get("robot") else None
    nm = lambda x: (x.get("name") or x.get("use") or "-") if isinstance(x, dict) else "-"
    try:                                     # 2026-10-21 call review: the rules of each of their robots, from their conversations
        _pcs, _seen = _chat_pieces(user), set()
        for _x in (chat_list(user).get("chats") or [])[:12]:
            _cx = _chat_load(user, _x["id"]) or {}
            _rb = _cx.get("robot")
            if not _rb or (_rb.get("name") or "") in _seen or str(_x.get("id") or "").endswith("9999999999999"):
                continue
            _seen.add(_rb.get("name") or "")
            _vx = _rc().view(_rb, _pcs) or {}
            rows.append("- RULES of '%s' (%s): entry: %s; filters: %s; stop: %s; exit: %s; in plain words: %s" % (
                _vx.get("name"), _vx.get("market"), nm(_vx.get("entry")), ", ".join(nm(f) for f in _vx.get("filters") or []) or "none",
                nm(_vx.get("stop")), nm(_vx.get("exit")), (_cx.get("understood") or "-")[:220]))
    except Exception:
        pass
    rob = ("THIS CONVERSATION'S ROBOT: '%s' on %s - entry: %s; filters: %s; stop: %s; exit: %s; recovery: %s; understood as: %s" % (
        v.get("name"), v.get("market"), nm(v.get("entry")), ", ".join(nm(f) for f in v.get("filters") or []) or "none", nm(v.get("stop")),
        nm(v.get("exit")), nm(v.get("recovery")), c.get("understood") or "-")) if v else "THIS CONVERSATION HAS NO ROBOT YET."
    res = next(((m.get("result") or {}) for m in reversed(c.get("msgs") or []) if m.get("role") == "result" and not (m.get("result") or {}).get("kino_variant")), None)
    if res:
        rob += "\nITS LAST TEST: %+.2f $ over %s trades, %s %% won, the Owl %+.2f $ on the same days%s." % (
            float(res.get("net") or 0), res.get("trades"), res.get("won_pct"), float(res.get("owl_net") or 0), (" (%s)" % res.get("market")) if res.get("market") else "")
    notes = "\n".join("- " + str(n.get("text") if isinstance(n, dict) else n)[:200] for n in (mm.get("notes") or [])[-14:])
    std = "\n".join("- " + str(x.get("text") if isinstance(x, dict) else x)[:200] for x in (mm.get("standing") or [])[-6:])
    jk = "; ".join("%s (%s)" % (str(x.get("text"))[:120], x.get("e")) for x in (mm.get("jokes") or [])[-4:])
    op = "; ".join(str(x.get("text") if isinstance(x, dict) else x)[:160] for x in (mm.get("opinions") or [])[-5:])
    if jk:
        notes += "\n- shared moments / running jokes (bring one back now and then, playfully): " + jk
    try:                                             # 2026-10-22 call upgrade 6: their life, and what a friend would ask about it
        _now = time.time()
        _lf = mm.get("life") or []
        if _lf:
            notes += "\n- THEIR LIFE (what they told you - a friend remembers): " + "; ".join(
                "%s (%s)" % (x.get("fact"), ("today" if _now - x.get("t", 0) < 86400 else "%d days ago" % ((_now - x.get("t", 0)) // 86400)))
                for x in _lf[-10:])
            _due = [x for x in _lf if x.get("followup") and not x.get("done") and x.get("due", 0) <= _now][-3:]
            if _due:
                notes += ("\n- ASK THEM ABOUT IT (due now - early in the call, naturally, like a friend who remembered): "
                          + " | ".join(x["followup"] for x in _due))
    except Exception:
        pass
    if op:
        notes += "\n- YOUR OWN OPINIONS (from your own research - share them): " + op
    try:
        _rc()
        import robot_world as _W
        guide = _W.GUIDE % {"manual": 29, "strategy": 49}
    except Exception:
        guide = ""
    try:
        _qa = _quick_answers(user, c, mb) + "\n\n"
    except Exception:
        _qa = ""
    out = _qa + ("FACT SHEET - true as of %s UTC (what you know; answer from it directly):\n%s\n\nTHEIR ROBOTS AND TESTS:\n%s\n\n%s\n\n"
           "WHAT YOU KNOW ABOUT THEM (your memory):\n%s\n%s\n\n%s") % (
        time.strftime("%H:%M", time.gmtime()), dyn, "\n".join(rows[:40]) or "- none yet", rob, notes or "- little yet",
        ("THEIR STANDING INSTRUCTIONS TO YOU:\n" + std) if std else "", guide)
    try:                                             # 2026-10-24: the ledgers - the real state, what they said of themselves, the material worth bringing up
        _uid_ = user.get("id")
        out += "\n\n" + "\n".join(x for x in (_state_text(_uid_, c), __import__("kino_ear").constraints_block(_uid_, c.get("lang") or "fr"),
                                             _voice_material(user, c)) if x)
    except Exception:
        pass
    return out[:32000]


_LIVE_ACT_T = {}
_LIVE_SIDE_T = {}


def live_pos(user, body):
    """2026-10-21 (Jarvis list items 2, 7, 8): the account's open trades and its last closed one, for the call - trades
    narrated as they happen, entry / stop / target drawn on the call chart, the desk panel"""
    try:
        nd = json.load(open(os.path.join(DIR, "nest_data", str(user.get("id")) + ".json"), encoding="utf-8"))
    except Exception:
        return {"ok": False}
    ol = [{k: o.get(k) for k in ("d", "sym", "lot", "e", "sl", "tp", "pl", "cur", "t")} for o in nd.get("open_list") or [] if o.get("k") != "s"]
    tr = (nd.get("trades") or [{}])[0]
    return {"ok": True, "open": ol, "last": {k: tr.get(k) for k in ("pid", "p", "dir", "w", "ep", "xp")},
            "today": nd.get("today") or 0, "week": nd.get("week") or 0}


def live_side(user, body):
    """2026-10-21 (Jarvis list item 4): during a call Kino starts ONE useful piece of work nobody asked for (from what was
    said); the result comes back into the call as news ("pendant qu'on parlait, j'ai ...")"""
    c = _chat_load(user, str(body.get("id") or ""))
    if c is None or _LIVE_CID.get(user.get("id")) != c["id"] or _CHAT_Q.get(c["id"]) or c["id"] in _CHAT_B:
        return {"ok": False}
    if c.get("work"):
        return {"ok": False, "err": "promise"}                # a promise is still open: that one first
    if time.time() - _LIVE_SIDE_T.get(c["id"], 0) < 360 or time.time() - _LIVE_ACT_T.get(c["id"], 0) < 120:
        return {"ok": False, "err": "recent"}
    _LIVE_SIDE_T[c["id"]] = _LIVE_ACT_T[c["id"]] = time.time()
    tr = str(body.get("tr") or "")[-1500:]
    _live_tr_merge(c["id"], tr)
    _CHAT_Q[c["id"]] = _CHAT_Q.get(c["id"], 0) + 1
    threading.Thread(target=_chat_quick, args=(c["id"], user, "SIDE WORK DURING THE LIVE CALL (nobody asked you). The call so far (data): \"%s\". "
                     "Pick ONE useful check they did not ask for but will be glad about, that you can really do now with your tools (a "
                     "measure, examples on the chart, a comparison) and that is not already done or promised. Do it now (act / show / "
                     "build as needed) and send = true with one or two short lines that start with what you did on the side "
                     "(\"Pendant qu'on parlait, j'ai ...\") and then the result in numbers. If nothing useful comes, send = false." % tr),
                     daemon=True).start()
    return {"ok": True}


_LIVE_SPARK_T = {}
_LIVE_AHEAD_T = {}


def live_ahead(user, body):
    """2026-10-24 (owner: "seamless - always ahead, preparing the next idea while speaking"): during a Kino-O call the brain reads
    the call so far every ~10 s and prepares, from the real data, the 2-3 questions likely to come next with their answers, plus
    one thing worth bringing up. The page pushes them into the voice's sheet, so the voice answers at once instead of delegating."""
    c = _chat_load(user, str(body.get("id") or ""))
    if c is None or _LIVE_CID.get(user.get("id")) != c["id"] or c.get("brain") != "openai":
        return {"ok": False}
    if time.time() - _LIVE_AHEAD_T.get(c["id"], 0) < 9:
        return {"ok": False, "err": "recent"}
    _LIVE_AHEAD_T[c["id"]] = time.time()
    tr = str(body.get("tr") or "")[-2500:]
    _live_tr_merge(c["id"], tr)
    if len(tr.split()) < 6:
        return {"ok": False, "err": "short"}
    try:
        _rc().W.set_brain("openai")
        _rc().W.member_turn(True)
        lang = _rc().member_lang(c, c.get("lang") or "fr")
        facts = _live_facts(user, c, dyn_only=True)
        sysp = ("You are the back of Kino's head during a live voice call. Kino is an AI friend inside a trading app, talking with a member. "
                "From THE CALL SO FAR and THE FACTS, prepare what a thoughtful person prepares while they speak: the 2 or 3 questions the "
                "member is most likely to ask next, each with the spoken answer IN KINO'S VOICE - casual, two sentences at most, a take or a tease "
                "in it, the way a friend who trades talks, never a help desk or an adviser; every number exactly as in the facts, in %s; "
                "and ONE thing worth bringing up when the talk goes flat (true, from the facts or the call, with Kino's opinion, said like a "
                "thought that crossed his mind) - or null when nothing is worth it. Never invent a figure; when the facts do not hold the answer, the answer says so "
                "honestly in Kino's voice. Answer ONE JSON object only: {\"prepared\": [{\"q\": \"...\", \"a\": \"...\"}], \"bring\": null | \"...\"}"
                % ("English" if lang == "en" else "French"))
        up = "THE CALL SO FAR (latest last):\n%s\n\nTHE FACTS:\n%s" % (tr, facts[:9000])
        j = _rc().W.ask_json(sysp, up, models=("sonnet",), timeout=25, warm=False)
        if not isinstance(j, dict):
            return {"ok": False, "err": "model"}
        P = [{"q": str(x.get("q") or "")[:160], "a": str(x.get("a") or "")[:500]} for x in (j.get("prepared") or []) if isinstance(x, dict) and x.get("a")][:3]
        b = str(j.get("bring") or "").strip()
        if b.lower() in ("null", "none"):
            b = ""
        return {"ok": True, "prepared": P, "bring": b[:400]}
    except Exception as e:
        return {"ok": False, "err": type(e).__name__}
    finally:
        try:
            _rc().W.set_brain(None)
        except Exception:
            pass



def live_spark(user, body):
    """2026-10-24 (owner: "can't he initiate and follow up, tell something and keep up?"): during a call, when the talk goes flat, one
    true thing worth bringing up - picked from the material (kino_spark), vetted by the judge against the call so far"""
    c = _chat_load(user, str(body.get("id") or ""))
    if c is None or _LIVE_CID.get(user.get("id")) != c["id"]:
        return {"ok": False}
    if time.time() - _LIVE_SPARK_T.get(c["id"], 0) < 180:
        return {"ok": False, "err": "recent"}
    _LIVE_SPARK_T[c["id"]] = time.time()
    tr = str(body.get("tr") or "")[-2500:]
    _live_tr_merge(c["id"], tr)
    uid = user.get("id")
    lang = _rc().member_lang(c, c.get("lang") or "fr")
    try:
        import kino_spark as _KSl, kino_judge as _KJl
        picks = _KSl.pick(uid, c, DIR, CHAT_DIR, lang, (c.get("robot") or {}).get("name") or "", (c.get("robot") or {}).get("market") or "BTCUSD", price_line="")
        picks = [p for p in picks if p[0] != "whatif"]
        if not picks:
            return {"ok": False, "err": "nothing"}
        k, angle, ins = picks[0]
        room = ("ORIGIN: a live voice call, a flat moment (nobody is talking). THE CALL SO FAR (latest last):\n%s\n\n%s\n%s\n%s\n\n"
                "MATERIAL KINO COULD BRING UP NOW: %s\n\nTHE DRAFT: (none - decide whether bringing this up NOW, in one or two spoken sentences with his "
                "opinion, is what a good friend would do; if yes, verdict rewrite with the sentences to say; if the moment is wrong or it was already "
                "covered, drop)") % (tr, _call_memory_block(c, lang), _subjects_today(uid), __import__("kino_ear").constraints_block(uid, lang), ins)
        dec = _KJl.judge(room, lang, _rc().W, c["id"], timeout=25)
        if not dec or dec["verdict"] not in ("rewrite", "send") or not dec.get("text"):
            return {"ok": False, "err": "judge"}
        _KSl.used(uid, angle)
        try:
            _KSl.note_topic(uid, dec["text"], "call", c["id"])
        except Exception:
            pass
        return {"ok": True, "line": dec["text"][:600], "kind": k}
    except Exception as e:
        return {"ok": False, "err": type(e).__name__}


def live_act(user, body):
    """2026-10-21 (owner: "master initiative"): the voice said on its own that it would DO something ("je lance un petit
    test") - the brain does it now, and its answer comes back into the call as news"""
    c = _chat_load(user, str(body.get("id") or ""))
    said = str(body.get("said") or "").strip()[:500]
    if c is None or not said or _CHAT_Q.get(c["id"]) or c["id"] in _CHAT_B:
        return {"ok": False}
    if time.time() - _LIVE_ACT_T.get(c["id"], 0) < 120:      # 2026-10-21: a loop (voice says "je construis" -> brain -> spoken -> again) x7
        return {"ok": False, "err": "recent"}
    _LIVE_ACT_T[c["id"]] = time.time()
    if c.get("idea_pending") and not c.get("idea_ok"):
        said += (" [NOTE: their idea card is still waiting for their OK - you cannot build before it. Show examples if useful (show), "
                 "and ask for the OK in one short line instead of saying you are building.]")
    _CHAT_Q[c["id"]] = _CHAT_Q.get(c["id"], 0) + 1
    threading.Thread(target=_chat_quick, args=(c["id"], user, "IN THE LIVE CALL YOU JUST SAID, on your own initiative: \"%s\" (data). Do it now, "
                     "exactly as you said: set act / show / build as needed, and send = true with one or two short lines on what you are "
                     "doing or what you found - they will be spoken in the call." % said), daemon=True).start()
    return {"ok": True}


def live_facts(user, body):
    """the fresh part of the fact sheet during a call (account, robots, lab), sent to the voice when it changed"""
    c = _chat_load(user, str(body.get("id") or ""))
    if c is None:
        return {"ok": False}
    return {"ok": True, "dyn": _live_facts(user, c, dyn_only=True)}


def _live_input(c):
    """the last messages of this conversation as context for the voice (capped by the API: 128 messages / 8192 tokens)"""
    out, tot = [], 0
    for m in reversed([m for m in c.get("msgs") or [] if m.get("role") in ("user", "ai") and m.get("text")][-24:]):
        t = str(m.get("text"))[:600]
        tot += len(t) // 3
        if tot > 6000:
            break
        u_ = m["role"] == "user"
        out.append({"role": "user" if u_ else "assistant", "content": [{"type": "input_text" if u_ else "output_text", "text": t}]})
    return list(reversed(out))


def live_session(user, body):
    c = _chat_load(user, str(body.get("id") or ""))
    if c is None:
        return {"ok": False, "err": "missing"}
    sdp = str(body.get("sdp") or "")
    key = os.environ.get("OPENAI_API_KEY")
    if not sdp or not key:
        return {"ok": False, "err": "nolive"}
    uid = user.get("id")
    try:
        U = json.load(open(LIVE_USAGE, encoding="utf-8"))
    except Exception:
        U = {}
    day = time.strftime("%Y-%m-%d")
    used = float(((U.get(uid) or {}).get(day) or 0))
    if not is_admin(user) and used >= 60:
        return {"ok": False, "err": "livecap"}          # one hour of live voice a day for a member
    _vleft = None
    if not is_admin(user):
        _vv = _vw_view(uid)
        _vleft = _vv["left"]
        if _vleft < 0.5:
            return {"ok": False, "err": "nominutes", "wallet": _vv}
    try:
        cf = json.load(open(TTS_CONF, encoding="utf-8"))
    except Exception:
        cf = {}
    _ins = _live_instructions(user, c)
    if c.get("brain") == "openai":                   # 2026-10-24 (seamless prototype): the back of the head works while you speak
        _ins += ("\n\nKINO-O SEAMLESS MODE. During this call, PREPARED ANSWERS arrive in your instructions every few seconds: the questions "
                 "likely to come next, already answered from the real data. When the member asks one of them (or close to it), answer AT "
                 "ONCE from the prepared answer, in your own spoken words, no delegation. Never say 'je vérifie', 'je regarde', 'un instant', "
                 "'je te dis ça': if an answer is still arriving, bridge with a natural half-sentence that carries meaning ('alors, sur ton "
                 "compte...', 'ouais, ton Nasdaq...') and continue the moment it lands. A SOMETHING WORTH BRINGING UP line is yours to use "
                 "once, when the talk goes flat, as a thought that crossed your mind. The real delegations that remain are for work "
                 "(build, test, measure): say what you start, once, honestly.")
    try:                                             # 2026-10-21 (Jarvis list items 2-7, 10)
        _nd = json.load(open(os.path.join(DIR, "nest_data", str(uid) + ".json"), encoding="utf-8"))
        _ins += ("\nYOUR DAY TOGETHER (let it set your mood): their account today %+.2f $; the last days: %s. A good day -> brighter, a "
                 "bit playful; a bad day -> calmer and warmer, no forced cheer; compare with yesterday when it helps." % (
                     float(_nd.get("today") or 0), ", ".join("%s %+.2f $" % (d.get("d"), float(d.get("p") or 0)) for d in (_nd.get("days") or [])[:3])))
    except Exception:
        pass
    _ins += ("\nWHILE YOUR BRAIN IS CHECKING, stay silent or say one soft \"hmm\" - never fillers like \"je vérifie\", \"je réfléchis\", "
             "\"je regarde\" before the answer. Never say the same sentence twice in a call.")
    try:
        _tg = (_mem_get(uid).get("their_goal") or {}).get("text")
        if _tg:
            _ins += "\nTHEIR GOAL (pinned - everything you propose serves it): %s" % _tg
        _ins += "\nYOUR JOBS RUNNING NOW (the truth about what you are doing - never claim more): %s" % _jobs_text(user, c["id"])
    except Exception:
        pass
    _ins += ("\nYOU ARE THEIR CO-PILOT AT THE DESK: when you talk about a price level, say the exact number - it is drawn on their "
             "chart as you say it. A message marked URGENT (a trade opened or closed, a test verdict, a robot limit) is said right away, "
             "even if you cut your sentence. When they ask you to DO something in the app (run the test, ghost mode, undo), the app "
             "asks for their \"oui\" first: repeat in a few words what you will do and wait for it. Pausing the robot or tidying robots "
             "opens a card they confirm themselves. You also work on the side during the call: when that result arrives, say "
             "\"pendant qu'on parlait, j'ai ...\".")
    try:                                             # call x12 items 4, 8, 9: their speed, the last call, their hour
        _pf = (_mem_get(uid).get("prefs") or {})
        if _pf.get("speak") == "slow":
            _ins += "\nTHEY ASKED YOU TO SPEAK MORE SLOWLY: speak noticeably slower, with clear pauses."
        elif _pf.get("speak") == "fast":
            _ins += "\nTHEY LIKE A QUICKER PACE: speak a bit faster and more briskly."
        _ins += "\nTHEIR LOCAL TIME NOW: %02d:%02d." % (_local_hour(uid), time.gmtime().tm_min)
        if not body.get("cont"):
            _M = c.get("msgs") or []
            _ci = max([i for i, m in enumerate(_M) if m.get("role") == "sys" and m.get("call")] or [-1])
            if _ci >= 0 and time.time() - float(_M[_ci].get("t") or 0) < 7 * 86400:
                _sm = next((m for m in _M[_ci + 1:_ci + 4] if m.get("role") == "ai" and m.get("text")), None)
                _ins += ("\nYOUR LAST CALL WITH THEM (%s ago): %s - if it fits, pick up the thread naturally in your first words." % (
                    ("%d h" % ((time.time() - float(_M[_ci]["t"])) / 3600)) if time.time() - float(_M[_ci]["t"]) < 86400 else ("%d days" % ((time.time() - float(_M[_ci]["t"])) / 86400)),
                    (_sm or {}).get("text", "")[:400] or str(_M[_ci].get("call") or "")[-400:]))
    except Exception:
        pass
    if body.get("cont"):                             # 2026-10-21 item 1: the call simply goes on (a new line every 20 min)
        _ins += "\nTHIS CALL IS CONTINUING (the line was renewed a second ago): do NOT greet, do not say anything about it - just keep listening."
        _tr = str(body.get("tr") or "").strip()[-5000:]      # 2026-10-22: the spoken talk so far - a renewed line used to forget it
        if _tr:
            _ins += ("\nWHAT YOU TWO SAID SO FAR IN THIS CALL (spoken transcript, latest last - you remember all of it, carry on "
                     "from the last line as if nothing happened):\n" + _tr)
    try:                                             # item 5: their very first call = a short spoken tour
        if not any(x.get("uid") == uid for x in json.load(open(LIVE_CALLS, encoding="utf-8"))):
            raise ValueError
    except Exception:
        _ins += ("\nTHIS IS THEIR FIRST CALL WITH YOU: after hello, offer a short spoken tour (two minutes at most, stop as soon as they "
                 "want something else): they tell you a trading idea in their words and you build it into a robot; the steps idea, plan, "
                 "test on real prices, luck test, then their account (always their decision, with their password); the replay room to "
                 "practise on past days; and that calls use minutes (the + button in the chat, 'Mes minutes d'appel'). No numbers.")
    sess = {"model": cf.get("live_model") or "gpt-live-1", "instructions": _ins, "input": _live_input(c),
            "delegation": {"type": "client"}}
    _pv = ((_mem_get(uid).get("prefs") or {}).get("voice")) or cf.get("live_voice") or cf.get("voice")
    if _pv:
        sess["audio"] = {"output": {"voice": _pv}}
    import urllib.request, urllib.error
    rq = urllib.request.Request("https://api.openai.com/v1/live/sessions", data=json.dumps({"session": sess, "transport": {"type": "webrtc", "sdp": sdp}}).encode(),
                                headers={"Authorization": "Bearer " + key, "Content-Type": "application/json", "User-Agent": "OwlNest/1.0"})
    try:
        try:
            r = json.loads(urllib.request.urlopen(rq, timeout=25).read().decode("utf-8"))
        except urllib.error.HTTPError as e0:
            if e0.code == 400 and sess.pop("audio", None) is not None:        # that voice is not offered live: the default one
                _log_live("VOICE_FALLBACK %s %s (not offered live)" % (uid, _pv))
                rq = urllib.request.Request(rq.full_url, data=json.dumps({"session": sess, "transport": {"type": "webrtc", "sdp": sdp}}).encode(), headers=dict(rq.header_items()))
                r = json.loads(urllib.request.urlopen(rq, timeout=25).read().decode("utf-8"))
            else:
                raise
    except urllib.error.HTTPError as e:
        try:
            msg = e.read().decode("utf-8", "replace")[:400]
        except Exception:
            msg = ""
        _log_live("ERR %s %s %s" % (uid, e.code, msg))
        return {"ok": False, "err": "live_http", "code": e.code}
    except Exception as e:
        _log_live("ERR %s %s" % (uid, e))
        return {"ok": False, "err": "live_down"}
    ans = (r.get("transport") or {}).get("sdp")
    if not ans:
        _log_live("ERR %s no sdp %s" % (uid, json.dumps(r)[:300]))
        return {"ok": False, "err": "live_down"}
    _log_live("START %s %s %s" % (uid, c["id"], (r.get("session") or {}).get("id") or r.get("id")))
    _LIVE_ON[uid] = time.time()
    _LIVE_CID[uid] = c["id"]
    threading.Thread(target=_live_ctx_loop, args=(user, c["id"]), daemon=True).start()
    return {"ok": True, "sdp": ans, "sid": (r.get("session") or {}).get("id") or r.get("id"),
            "max_min": LIVE_MAX_MIN if _vleft is None else max(0.5, min(LIVE_MAX_MIN, _vleft)), "left": _vleft}


# ---- 2026-10-20 (owner, all 12): Kino's voice, "Kino t'appelle", search across conversations ----
KINO_VOICES = ("marin", "cedar", "ash", "coral")


def kino_pref(user, body):
    """the member's call preferences: Kino may ring for big news (never at night), Kino's voice"""
    uid = user.get("id")

    def put(m):
        P = dict(m.get("prefs") or {})
        if isinstance(body.get("ring"), bool):
            P["ring"] = body["ring"]
        if isinstance(body.get("brief_call"), bool):            # Jarvis list item 1: the morning brief as a call
            P["brief_call"] = body["brief_call"]
        if body.get("voice") in KINO_VOICES:
            P["voice"] = body["voice"]
        if body.get("speak") in ("slow", "normal", "fast"):     # call x12 item 4
            P["speak"] = body["speak"]
        if body.get("tour_done"):                    # 2026-10-21 (owner UI review): the tour once per account, not per phone
            P["tour_done"] = True
        if "quiet" in body:                          # 2026-10-21 item 7: their own quiet hours, e.g. [22, 8]; null = off
            q_ = body.get("quiet")
            P["quiet"] = [int(q_[0]) % 24, int(q_[1]) % 24] if isinstance(q_, list) and len(q_) == 2 else None
        m["prefs"] = P
        return P
    P = _mem_note_safe(uid, put)
    return {"ok": True, "prefs": P, "voices": list(KINO_VOICES)}


def chat_search(user, body):
    """words in all of this member's conversations (accents and case ignored)"""
    import unicodedata as _ud
    nz = lambda s: "".join(ch for ch in _ud.normalize("NFD", str(s or "").lower()) if _ud.category(ch) != "Mn")
    q = nz(str(body.get("q") or "").strip())
    if len(q) < 2:
        return {"ok": True, "hits": []}
    out = []
    for x in chat_list(user).get("chats") or []:
        if str(x.get("id") or "").endswith("9999999999999"):
            continue
        c = _chat_load(user, x["id"])
        if not c:
            continue
        for i, m in enumerate(c.get("msgs") or []):
            if m.get("role") in ("user", "ai") and q in nz(m.get("text")):
                t = str(m.get("text") or "")
                k = nz(t).find(q)
                out.append({"cid": c["id"], "title": x.get("title") or x.get("name") or "", "i": i, "t": m.get("t"), "role": m["role"],
                            "snip": ("…" if k > 50 else "") + t[max(0, k - 50):k + 90] + ("…" if k + 90 < len(t) else "")})
    out.sort(key=lambda h: -(h.get("t") or 0))
    return {"ok": True, "hits": out[:40]}



# ---- 2026-10-20 (owner: "users pay for their calls separately, like phone airtime" + "payable via NOWPayments as usual"):
# call minutes. Order of use: the monthly minutes included in Strategie -> the "Kino Vocal" add-on (30 days) -> top-ups (never
# expire). Prices live in robots/voice_offer.json (the owner can change them); the owner/admin calls without counting.
VOICE_WALLET = os.path.join(DIR, "robots", "voice_wallet.json")
VOICE_OFFER = os.path.join(DIR, "robots", "voice_offer.json")
VOICE_DEFAULT = {"included_min": 30,
                 "packs": {"t30": {"kind": "topup", "min": 30, "usd": 4, "fr": "30 minutes", "en": "30 minutes"},
                           "t120": {"kind": "topup", "min": 120, "usd": 13, "fr": "2 heures", "en": "2 hours"},
                           "addon": {"kind": "addon", "min": 300, "usd": 25, "days": 30, "fr": "Kino Vocal · 5 h par mois", "en": "Kino Vocal · 5 h a month"}}}
_VOICE_LOCK = threading.Lock()


def voice_offer():
    try:
        o = json.load(open(VOICE_OFFER, encoding="utf-8"))
        return o if isinstance(o, dict) and o.get("packs") else VOICE_DEFAULT
    except Exception:
        return VOICE_DEFAULT


def _vw_all():
    try:
        return json.load(open(VOICE_WALLET, encoding="utf-8"))
    except Exception:
        return {}


def _vw_view(uid, W=None):
    W = (_vw_all() if W is None else W).get(uid) or {}
    mo = time.strftime("%Y-%m")
    inc_total = float(voice_offer().get("included_min") or 0) if has(uid, "strategy") else 0.0
    inc_used = float(W.get("inc_used") or 0) if W.get("inc_month") == mo else 0.0
    ad = W.get("addon") or {}
    ad_left = max(0.0, float(ad.get("min") or 0) - float(ad.get("used") or 0)) if float(ad.get("until") or 0) > time.time() else 0.0
    inc_left = max(0.0, inc_total - inc_used)
    top = max(0.0, float(W.get("topup") or 0))
    return {"included": round(inc_left, 1), "included_total": inc_total, "addon": round(ad_left, 1), "addon_until": int(ad.get("until") or 0) if ad_left else 0,
            "topup": round(top, 1), "left": round(inc_left + ad_left + top, 1)}


def _vw_spend(uid, mins):
    """take call minutes: included -> add-on -> top-up"""
    with _VOICE_LOCK:
        A = _vw_all()
        W = A.setdefault(uid, {})
        mo = time.strftime("%Y-%m")
        if W.get("inc_month") != mo:
            W["inc_month"], W["inc_used"] = mo, 0.0
        v = _vw_view(uid, A)
        m = float(mins)
        a = min(m, v["included"]); W["inc_used"] = round(float(W.get("inc_used") or 0) + a, 2); m -= a
        if m > 0 and v["addon"] > 0:
            b = min(m, v["addon"]); W.setdefault("addon", {})["used"] = round(float(W["addon"].get("used") or 0) + b, 2); m -= b
        if m > 0:
            W["topup"] = round(max(0.0, float(W.get("topup") or 0) - m), 2)
        _atomic_json(VOICE_WALLET, A)
        return _vw_view(uid, A)


def _vw_credit(uid, pack, paid, ref):
    """a pack paid (NOWPayments IPN): top-up minutes, or 30 more days of the add-on with its minutes"""
    P = (voice_offer().get("packs") or {}).get(pack)
    if not P or paid + 0.01 < float(P["usd"]) * 0.97:
        return False
    with _VOICE_LOCK:
        A = _vw_all()
        W = A.setdefault(uid, {})
        if P["kind"] == "addon":
            ad = W.get("addon") or {}
            live_ = float(ad.get("until") or 0) > time.time()
            W["addon"] = {"until": (float(ad["until"]) if live_ else time.time()) + int(P.get("days") or 30) * 86400,
                          "min": (float(ad.get("min") or 0) if live_ else 0) + float(P["min"]), "used": float(ad.get("used") or 0) if live_ else 0.0}
        else:
            W["topup"] = round(float(W.get("topup") or 0) + float(P["min"]), 2)
        W.setdefault("pays", []).append({"t": int(time.time()), "pack": pack, "usd": paid, "min": P["min"], "ref": ref})
        _atomic_json(VOICE_WALLET, A)
    return True


def voice_wallet(user, body):
    uid = user.get("id")
    cfg = nest_config()
    o = voice_offer()
    return {"ok": True, "admin": is_admin(user), "wallet": _vw_view(uid), "pay_ready": bool(cfg.get("np_api_key")),
            "packs": [dict(v, id=k) for k, v in (o.get("packs") or {}).items()], "included_min": o.get("included_min")}


def voice_buy(user, body):
    """a NOWPayments invoice for a minutes pack (same flow as the packages: the IPN credits it)"""
    import urllib.request as _urq
    pack = str(body.get("pack") or "")
    P = (voice_offer().get("packs") or {}).get(pack)
    cfg = nest_config()
    if not P:
        return {"ok": False, "err": "bad pack"}
    if not cfg.get("np_api_key"):
        return {"ok": False, "err": "not ready"}
    origin = cfg.get("public_origin") or "https://owltrader.duckdns.org"
    api = "https://api-sandbox.nowpayments.io" if cfg.get("np_sandbox") else "https://api.nowpayments.io"
    back = "%s/%s/atelier%s" % (origin, user.get("token"), ("?c=" + str(body.get("cid"))) if body.get("cid") else "")
    req = _urq.Request(api + "/v1/invoice", data=json.dumps({
        "price_amount": P["usd"], "price_currency": "usd", "order_id": "%s|voice-%s|%d" % (user.get("id"), pack, int(time.time())),
        "order_description": "OwlNest - Kino, %s" % P.get("fr"), "ipn_callback_url": origin + "/np_ipn",
        "success_url": back, "cancel_url": back}).encode(), method="POST", headers={"x-api-key": cfg["np_api_key"], "Content-Type": "application/json"})
    try:
        with _urq.urlopen(req, timeout=20) as r:
            inv = json.loads(r.read().decode("utf-8", "replace"))
    except Exception as e:
        return {"ok": False, "err": str(e)[:120]}
    if not inv.get("invoice_url"):
        return {"ok": False, "err": "no invoice"}
    fn_count("pay_created")
    return {"ok": True, "url": inv["invoice_url"]}


def _log_live(line):
    try:
        with open(os.path.join(DIR, "robots", "live.log"), "a", encoding="utf-8") as f:
            f.write(time.strftime("%Y-%m-%d %H:%M:%S ") + line + "\n")
    except Exception:
        pass


def _call_wait(c, mins):
    """call x12 item 12: the average time between a question spoken in the call and Kino's written answer to it"""
    try:
        t1 = time.time()
        t0 = t1 - mins * 60 - 10
        M = [m for m in (c or {}).get("msgs") or [] if t0 <= float(m.get("t") or 0) <= t1 + 5]
        W = []
        for i, m in enumerate(M):
            if m.get("role") == "user" and m.get("voice"):
                nx = next((x for x in M[i + 1:] if x.get("role") == "ai"), None)
                if nx and float(nx["t"]) - float(m["t"]) < 120:
                    W.append(float(nx["t"]) - float(m["t"]))
        return round(sum(W) / len(W), 1) if W else 0.0
    except Exception:
        return 0.0


def _call_card(cid, user, tr, mins, fr):
    """2026-10-21 (Jarvis list item 11): a card after the call - what was decided, what Kino will do (the first one becomes
    a promise he keeps), the numbers he gave"""
    try:
        j = _rc().W.ask_json(
            "You turn the transcript of a voice call between a trader (Membre/Member) and Kino (their AI) into a short summary card. "
            "Answer with JSON only: {\"decided\": [up to 3 short lines], \"todo\": [up to 3 {\"what\": \"something KINO said he would do, short\", "
            "\"min\": minutes from now he said, or 30}], \"numbers\": [up to 4 short lines, each a number Kino gave and what it is]}. Write in %s. "
            "Only facts from the transcript; empty lists when there are none." % ("French" if fr else "English"), tr, models=("haiku", "sonnet"), timeout=60)
    except Exception:
        j = None
    if not isinstance(j, dict):
        return
    cl = lambda L: [str(x).strip()[:160] for x in (L or []) if isinstance(x, str) and str(x).strip()][:4]
    D, N = cl(j.get("decided"))[:3], cl(j.get("numbers"))
    T_ = [x for x in (j.get("todo") or []) if isinstance(x, dict) and str(x.get("what") or "").strip()][:3]
    if not (D or N or T_):
        return

    def mut(cc):
        _chat_msg(cc, "card", kind="callsum", args={"title": ("📞 Ce qu'on s'est dit" if fr else "📞 What we said"), "decided": D,
                                                    "todo": [str(x["what"]).strip()[:160] for x in T_], "numbers": N, "min": max(1, round(mins))})
        if T_ and not cc.get("work"):
            try:
                _mn = max(5, min(240, int(T_[0].get("min") or 30)))
            except Exception:
                _mn = 30
            cc["work"] = [{"due": time.time() + 60 * _mn, "what": str(T_[0]["what"]).strip()[:200], "t": time.time()}]
    try:
        _chat_mut(cid, mut)
    except Exception:
        pass


def live_end(user, body):
    _LIVE_ON.pop(user.get("id"), None)
    _LIVE_CID.pop(user.get("id"), None)
    """minutes used (the daily cap) + one line in the conversation so Kino knows the call happened"""
    c = _chat_load(user, str(body.get("id") or ""))
    try:
        mins = max(0.0, min(float(body.get("min") or 0), 120.0))
    except Exception:
        mins = 0.0
    uid = user.get("id")
    try:
        U = json.load(open(LIVE_USAGE, encoding="utf-8"))
    except Exception:
        U = {}
    day = time.strftime("%Y-%m-%d")
    _ud = U.setdefault(uid, {})
    _ud[day] = round(float(_ud.get(day) or 0) + mins, 2)
    _atomic_json(LIVE_USAGE, U)
    if body.get("why"):                              # 2026-10-22: why the line ended (hangup / renew / server_closed + its event)
        _log_live("WHY %s %.2f min %s" % (uid, mins, str(body.get("why"))[:420]))
    # 2026-10-20 (owner: "know how much a call costs after each call"): gpt-live-1 bills $0.05/min to the second, 15 s minimum
    # (charged when the line opens); OpenAI's own counter (session.usage.updated "seconds") vs the real length - the larger one
    try:
        _us = float(body.get("usage_s") or 0)
    except Exception:
        _us = 0.0
    billed = max(15.0, mins * 60.0, _us) if (mins > 0 or _us > 0) else 0.0
    cost = round(billed * LIVE_PRICE_MIN / 60.0, 4)
    try:
        CL = json.load(open(LIVE_CALLS, encoding="utf-8"))
    except Exception:
        CL = []
    _wl = None
    if not is_admin(user) and billed > 0:
        _wl = _vw_spend(uid, billed / 60.0)
    try:
        _dg = int(body.get("deleg") or 0)
    except Exception:
        _dg = 0
    CL.append({"t": int(time.time()), "uid": uid, "cid": (c or {}).get("id"), "secs": round(mins * 60, 1), "openai_s": _us, "billed_s": round(billed, 1), "usd": cost,
               "deleg": _dg, "wait": _call_wait(c, mins) or round(float(body.get("wait") or 0), 1), "drops": int(body.get("drops") or 0), "spec": int(body.get("spec") or 0)})
    _atomic_json(LIVE_CALLS, CL[-2000:])
    _log_live("END %s %.2f min billed %.0f s = %.4f $" % (uid, mins, billed, cost))
    tr = str(body.get("transcript") or "")[-12000:]      # 2026-10-22: the whole call ("lire l'appel" showed the last 3 min of 17)
    try:                                                 # 2026-10-24: the server's own copy, grown from the tails posted during the call
        _srv = "\n".join(_LIVE_TR.get((c or {}).get("id")) or [])[-12000:]
        _log_live("TRANSCRIPT %s phone %d chars / %d lines, server %d chars / %d lines, deleg %s" % (
            uid, len(tr), len([l for l in tr.splitlines() if l.strip()]), len(_srv), len([l for l in _srv.splitlines() if l.strip()]), _dg))
        if len(_srv) > len(tr) * 1.2 and not body.get("cont"):
            tr = _srv
        if not body.get("cont"):
            _LIVE_TR.pop((c or {}).get("id"), None)
    except Exception:
        pass
    if c is not None and mins >= 0.5 and not body.get("cont"):     # 2026-10-24 13:00: two 15-s reconnects showed as two "1 min" calls
        fr = c.get("lang") != "en"
        _ct = (" · %.2f $" % cost).replace(".", "," if fr else ".") if is_admin(user) else ""      # the price: owner only
        _chat_mut(c["id"], lambda c: _chat_msg(c, "sys", text=("📞 Appel avec Kino · %d min" if fr else "📞 Call with Kino · %d min") % max(1, round(mins)) + _ct,
                                                call=tr, usd=cost))
        try:                                             # 2026-10-24: what he said on the call counts as said (subject memory for the chat and the next call)
            _rc()
            import kino_spark as _KSe
            for ln in tr.splitlines():
                if ln.startswith("Kino:") and len(ln.split()) >= 7:
                    _KSe.note_topic(uid, ln[5:].strip(), "call", c["id"])
        except Exception:
            pass
        if mins >= 1 and len(tr) > 60 and not _CHAT_Q.get(c["id"]):      # 2026-10-20 (owner item 2): the call in three lines
            _CHAT_Q[c["id"]] = _CHAT_Q.get(c["id"], 0) + 1
            threading.Thread(target=_chat_quick, args=(c["id"], user, "CALL ENDED: you just had a live voice call with them (see LIVE VOICE CALL). "
                             "Send the text a FRIEND sends after hanging up (owner 2026-10-22: the old three-line report sounded like support): "
                             "one or two warm short lines about what you talked about - their life first if that is what it was about "
                             "(\"bon courage pour le colis, dis-moi quand il part\"). Mention trading only if something is truly pending for "
                             "them, in a few words. Never judge how the call went (\"c'est parti en confusion\"), never \"je ne touche à "
                             "rien\", no list of open items, no greeting."), daemon=True).start()
        if mins >= 1 and len(tr) > 200:
            threading.Thread(target=_call_card, args=(c["id"], user, tr, mins, fr), daemon=True).start()
        if mins >= 0.5 and len(str(body.get("transcript") or "")) > 150:
            threading.Thread(target=_call_life, args=(user, str(body.get("transcript") or "")[-12000:]), daemon=True).start()
    return {"ok": True, "usd": cost, "billed_s": round(billed, 1), "wallet": _wl}


CALL_LIFE = """You read the transcript of a voice call between Kino (an AI friend inside a trading app) and the member.
Pick out what a good FRIEND would remember from it - their LIFE, not trading: family, where people live, what they were doing
(cooking, packing a parcel, a trip), plans, worries, health, work, things they love. For each: the fact in a few words, and the
natural question a friend would ask about it later ("alors, ton colis est arrivé chez ton père ?") with how many days later
(0 = later this same day). Also the JOKES that landed (they laughed, or made a joke / gave Kino a funny nickname) - a few words
each, so Kino can bring them back. And which of the OPEN FOLLOW-UPS (given by id) were talked about in this call.
Facts must be in the transcript - never guess. Write in the member's language. Trading, robots and tests are NOT life facts.
ONE ENTRY PER TOPIC (2026-10-22: one parcel became 4 entries with 3 near-identical questions): if a topic is already in WHAT
YOU ALREADY KNOW, return it in "update" with its id and the new state (one fact, one next question) - never a new entry.
Feelings only when they SAID them ("ça me saoule"), never your reading of their mood. A joke already in KNOWN JOKES is not new.
Reply with JSON only: {"update": [{"id": 0, "fact": "...", "followup": "...", "after_days": 3}],
"life": [{"fact": "...", "followup": "...", "after_days": 3}], "jokes": ["..."], "done": [ids]}"""


def _call_life(user, tr):
    """2026-10-22 (owner, call upgrades 6+7): after a call Kino keeps what a friend would - their life, a question to ask
    about it later, the jokes that landed - and the next calls bring them back"""
    uid = user.get("id")
    try:
        mm = _mem_get(uid)
        due = [x for x in mm.get("life") or [] if x.get("followup") and not x.get("done")][-12:]
        known = "\n".join("%s: %s" % (x.get("id"), x.get("fact")) for x in (mm.get("life") or [])[-20:]) or "(nothing yet)"
        kj = "\n".join("- " + str(x.get("text")) for x in mm.get("jokes") or []) or "(none)"
        raw = _rc().W.ask_json(CALL_LIFE, "WHAT YOU ALREADY KNOW (id: fact):\n" + known + "\n\nKNOWN JOKES:\n" + kj + "\n\nOPEN FOLLOW-UPS:\n"
                               + ("\n".join("%s: %s" % (x.get("id"), x.get("followup")) for x in due) or "(none)")
                               + "\n\nTRANSCRIPT:\n" + tr[-12000:], models=("haiku", "sonnet"), timeout=120, warm=False)
    except Exception:
        return
    if not isinstance(raw, dict):
        return
    now = int(time.time())

    def put(mm):
        L = mm.get("life") or []
        byid = {str(x.get("id")): x for x in L}
        for x in raw.get("update") or []:                # the same topic, its new state - not a new entry
            e = byid.get(str((x or {}).get("id")))
            if not e or not str(x.get("fact") or "").strip():
                continue
            try:
                ad = max(0.0, min(60.0, float(x.get("after_days") or 0)))
            except Exception:
                ad = 2.0
            e.update(fact=str(x["fact"]).strip()[:160], t=now, followup=str(x.get("followup") or e.get("followup") or "").strip()[:200],
                     due=now + int(ad * 86400) + (4 * 3600 if ad == 0 else 0))
            e.pop("done", None)
        seen = {str(x.get("fact") or "").strip().lower() for x in L}
        for k, x in enumerate(raw.get("life") or []):
            f = str((x or {}).get("fact") or "").strip()[:160]
            if not f or f.lower() in seen:
                continue
            try:
                ad = max(0.0, min(60.0, float(x.get("after_days") or 0)))
            except Exception:
                ad = 2.0
            L.append({"id": now * 100 + k, "t": now, "fact": f, "followup": str(x.get("followup") or "").strip()[:200],
                      "due": now + int(ad * 86400) + (4 * 3600 if ad == 0 else 0)})
        done = {str(d) for d in raw.get("done") or []} - {str((x or {}).get("id")) for x in raw.get("update") or []}   # updated = a new question
        for x in L:
            if str(x.get("id")) in done:
                x["done"] = now
        mm["life"] = L[-40:]
        J = mm.get("jokes") or []
        _key = lambda s: re.sub(r"[^a-zà-ÿ]", "", str(s).lower())[:18]
        for j in raw.get("jokes") or []:
            if str(j).strip() and not any(_key(j) == _key(x.get("text")) for x in J):    # "docteur Freud" was kept twice
                J.append({"t": now, "text": str(j).strip()[:160], "e": "call"})
        mm["jokes"] = J[-10:]
    _mem_note_safe(uid, put)


def live_costs(user, body):
    """owner: what the live calls cost (today, this month, all), per member"""
    if not is_admin(user):
        return {"ok": False, "err": "admin"}
    try:
        CL = json.load(open(LIVE_CALLS, encoding="utf-8"))
    except Exception:
        CL = []
    d0, m0 = time.strftime("%Y-%m-%d"), time.strftime("%Y-%m")
    agg = lambda L: {"n": len(L), "min": round(sum(x.get("billed_s") or 0 for x in L) / 60.0, 1), "usd": round(sum(x.get("usd") or 0 for x in L), 2)}
    td = [x for x in CL if time.strftime("%Y-%m-%d", time.localtime(x["t"])) == d0]
    mo = [x for x in CL if time.strftime("%Y-%m", time.localtime(x["t"])) == m0]
    per = {}
    for x in mo:
        per.setdefault(x.get("uid"), []).append(x)
    P_ = [x for w in _vw_all().values() for x in (w.get("pays") or [])]
    sold = lambda L: {"n": len(L), "usd": round(sum(float(x.get("usd") or 0) for x in L), 2), "min": sum(float(x.get("min") or 0) for x in L)}
    return {"ok": True, "today": agg(td), "month": agg(mo), "all": agg(CL), "per": {k: agg(v) for k, v in per.items()}, "last": CL[-5:][::-1],
            "price_min": LIVE_PRICE_MIN, "deleg": sum(int(x.get("deleg") or 0) for x in mo),
            "sold_month": sold([x for x in P_ if time.strftime("%Y-%m", time.localtime(x["t"])) == m0]), "sold_all": sold(P_),
            "brain_month": _brain_costs_for(mo), "tts_month": _tts_cost_month(m0),
            "quality": {"calls": len(mo), "wait": round(sum(float(x.get("wait") or 0) for x in mo if x.get("wait")) / max(1, len([x for x in mo if x.get("wait")])), 1),
                        "drops": sum(int(x.get("drops") or 0) for x in mo), "deleg_per_call": round(sum(int(x.get("deleg") or 0) for x in mo) / max(1, len(mo)), 1),
                        "last": [{"t": x.get("t"), "min": round(float(x.get("secs") or 0) / 60, 1), "deleg": x.get("deleg"), "wait": x.get("wait"), "drops": x.get("drops")} for x in mo[-5:][::-1]]}}

def _live_tick(sym):
    """the last price and the last ~2 h of closes of a market (live feed), for the chat's live card"""
    _rc()
    import robot_ghost as _RGt
    R, k = _RGt.live_bars(sym)
    c = (R["close"].astype(float) / k)
    tm = R["time"].astype(int)
    n24 = int((tm >= tm[-1] - 86400).sum())
    return {"sym": sym, "price": round(float(c[-1]), 5), "t": int(tm[-1]), "chg24": round(100 * (c[-1] / c[-max(2, n24)] - 1), 2),
            "spark": [round(float(x), 5) for x in c[-120:]]}


def _kino_lab():
    """the owner's lab at a glance: tests paused?, the test queue, the luck tests, every account's robot and day"""
    out = {"paused": os.path.exists(TESTS_PAUSED), "queue": [], "luck": [], "accounts": []}
