def _inf_autocheck(uid, name):
    """2026-10-17 (owner: "approve without asking"): fetch the publication, look for the code or the link; found ->
    approved on the spot and both sides told; otherwise the owner's queue shows the reason and the link's traffic"""
    import owl_influencers as _INF
    import owl_wallet as _OW
    try:
        code = _OW.code_of(uid)
        r = _INF.verify(uid, code, f"owltrader.duckdns.org/offres?p={code}")
        ck = (r or {}).get("auto_check") or {}
        if (r or {}).get("status") == "approved" and str((r or {}).get("review_note", "")).startswith("auto"):
            queue_push(uid, "\U0001f3ac Programme créateurs : approuvé", f"Votre publication est validée ({ck.get('reason')}). Dès maintenant, {int(_OW.INF_PCT * 100)} % de chaque mois payé par vos abonnés est pour vous, pendant leurs {_OW.INF_MONTHS} premiers mois.")
            queue_push("kino", "\U0001f3ac Créateur approuvé automatiquement", f"{name} : {ck.get('reason')}. Compte › Créateurs pour voir ou retirer.")
        elif (r or {}).get("status") == "pending":
            queue_push("kino", "\U0001f3ac Demande créateur à regarder", f"{name} : {ck.get('reason') or 'vérification impossible'}. Compte › Créateurs pour décider.")
    except Exception:
        pass


def _inf_block(user, st):
    import owl_influencers as _INF
    import owl_wallet as _OW
    uid = user.get("id")
    r = _INF.status(uid) or {}
    out = {"status": r.get("status") or "none", "platform": r.get("platform") or "", "channel": r.get("channel") or "", "video": r.get("video") or "", "note": r.get("note") or "", "applied_t": r.get("applied_t"),
           "reviewed_t": r.get("reviewed_t"), "review_note": r.get("review_note") or "", "pct": int(_OW.INF_PCT * 100), "months": _OW.INF_MONTHS,
           "active_users": st.get("active"), "this_month": st.get("this_month"), "series": st.get("series"), "recurring": st.get("recurring"),
           "expected": st.get("expected")}
    out["auto_check"] = r.get("auto_check")
    out["pubs"] = _INF.publications(uid) if r else []
    out["clicks"] = st.get("clicks"); out["conversion"] = st.get("conversion")
    if is_admin(user):
        _nm = {u.get("id"): (u.get("name") or u.get("id")) for u in users()}
        _rows = []
        for p in _INF.pending():
            _s = _OW.referral_stats(p["uid"])
            _rows.append(dict(p, name=_nm.get(p["uid"], p["uid"]), clicks=_s["clicks"], signed=_s["signed"], paid=_s["paid"]))
        out["pending"] = _rows
        out["approved"] = [{"uid": k, "name": _nm.get(k, k)} for k in sorted(_INF.approved_uids())]
    return out


def place_action(user, action, body, admin=False, origin="https://owltrader.duckdns.org"):
    import owl_market as _OMKT
    import owl_wallet as _OW
    uid = user.get("id"); body = body or {}
    if action == "place_publish":
        if not (admin or has(uid, "strategy")):
            return {"ok": False, "err": "Strat\u00e9gie n\u00e9cessaire pour publier"}
        # 2026-10-19 (owner): the public marketplace needs the 100-draw luck test - for everyone, the owner included
        # 2026-10-22: proven on ANY market (a gold robot passed its luck test on gold, it has no Bitcoin test)
        if not _OMKT.best_result(str(body.get("id") or "")):
            _q = robot_control(user, {"id": str(body.get("id") or ""), "sym": "BTCUSD"})
            return {"ok": False, "err": "Il faut d\u2019abord r\u00e9ussir le test de chance (100 tirages)." +
                    (" Il est lanc\u00e9." if _q.get("ok") else " Il est d\u00e9j\u00e0 en cours ou en attente." if _q.get("err") in ("busy", "done") else
                     " Il faut un test Bitcoin positif avec 20 trades ou plus." if _q.get("err") == "not_winning" else "")}
        return _OMKT.publish(str(body.get("id") or ""), uid, body.get("alias"), body.get("blurb"), body.get("price"), body.get("open_recipe"), admin)
    if action == "place_unpublish":
        return _OMKT.unpublish(str(body.get("id") or ""), uid, admin)
    if action == "wallet_addr":
        # the creator's USDT address for payouts (owner pays by hand from PAYOUT_MIN, the app keeps the ledger)
        return {"ok": True, "addr": _OW.set_payout_addr(uid, body.get("addr"))}
    if action == "inf_apply":
        # 2026-10-17 (owner): a creator / YouTuber applies with their channel and the video; the owner is told
        import owl_influencers as _INF
        if user.get("public"):
            return {"ok": False, "err": "public"}
        r = _INF.apply(uid, body.get("channel"), body.get("video"), body.get("note"), platform=body.get("platform"))
        if r.get("ok") and r.get("added"):
            # an approved creator added a publication: check that one, no status change
            _url = _INF._clean_url(body.get("video"))
            threading.Thread(target=lambda: _INF.verify(uid, _OW.code_of(uid), f"owltrader.duckdns.org/offres?p={_OW.code_of(uid)}", url=_url), daemon=True).start()
        elif r.get("ok"):
            threading.Thread(target=_inf_autocheck, args=(uid, user.get("name") or uid), daemon=True).start()
        return r
    if action == "inf_recheck":
        if not admin:
            return {"ok": False, "err": "owner"}
        _tu = str(body.get("uid") or "")
        _nm = next((u.get("name") for u in users() if u.get("id") == _tu), _tu)
        _inf_autocheck(_tu, _nm)
        return {"ok": True, "check": ((_INF_STATUS(_tu) or {}).get("auto_check"))}
    if action == "inf_review":
        if not admin:
            return {"ok": False, "err": "owner"}
        import owl_influencers as _INF
        _tu = str(body.get("uid") or "")
        r = _INF.review(_tu, bool(body.get("approve")), body.get("note"))
        if r.get("ok"):
            if r["status"] == "approved":
                queue_push(_tu, "\U0001f3ac Programme créateurs : approuvé", f"Votre vidéo est validée. Dès maintenant, {int(_OW.INF_PCT * 100)} % de chaque mois payé par vos abonnés est pour vous, tant qu’ils restent.")
            else:
                queue_push(_tu, "Programme créateurs", "Nous n’avons pas pu valider la vidéo cette fois. " + (str(body.get("note") or "")[:120]))
        return r
    if action == "payout_mark":
        if not admin:
            return {"ok": False, "err": "owner"}
        ok = _OW.mark_paid(str(body.get("uid") or ""), float(body.get("usd") or 0), body.get("ref"))
        if ok:
            queue_push(str(body.get("uid")), "\U0001f4b8 Paiement envoyé", f"Vos gains de créateur : ${float(body.get('usd') or 0):.2f} envoyés à votre adresse. Merci pour votre robot.")
        return {"ok": bool(ok)}
    if action == "wallet_use":
        pkg = _member_pkg(uid); fam = float(nest_config().get("family_usd") or 60)
        avail = _OW.days_available(uid, pkg, PACKAGES, fam)
        days = max(0, min(int(body.get("days") or 0), avail))
        if days <= 0:
            return {"ok": False, "err": "Pas assez dans la cagnotte pour un jour de " + {"family": "Automatique", "manual": "Signal", "strategy": "Strat\u00e9gie"}.get(pkg, pkg) + "."}
        usd = _OW.spend_days(uid, pkg, days, PACKAGES, fam)
        if not usd:
            return {"ok": False, "err": "Cagnotte insuffisante."}
        r = ent_grant(uid, pkg, days, "wallet")
        return {"ok": True, "days": days, "usd": usd, "until": time.strftime("%d/%m", time.gmtime(float(r.get(pkg + "_until") or time.time())))}
    if action == "place_unfollow":
        if not (pwd_ok(user, str(body.get("pwd") or "")) or master_pwd_ok(str(body.get("pwd") or ""))):
            return {"ok": False, "err": "pwd"}
        _OMKT.stop_sub(uid)
        try:
            return account_robot_set(user, {"id": "owl", "pwd": body.get("pwd")}, admin)
        except Exception as e:
            return {"ok": True, "note": str(e)[:60]}
    if action == "place_follow":
        rid = str(body.get("id") or ""); L = _OMKT.listing(rid)
        if not L or L.get("hidden"):
            return {"ok": False, "err": "not_allowed"}
        if L.get("paused"):
            return {"ok": False, "err": "paused"}
        if not (user.get("trade") and user.get("mt5_login")):
            return {"ok": False, "err": "no_auto"}
        if L.get("by_uid") == uid:
            return account_robot_set(user, {"id": rid, "pwd": body.get("pwd")}, admin)     # the creator runs their own robot for free
        price = 0.0            # pay once (owner 2026-10-17): every robot on the place is included in the plan
        cur = _OMKT.sub_of(uid)
        if price > 0:
            if True:
                # owner 2026-10-17: robot months are real money - paid in crypto through our payment system, never
                # from the referral cagnotte (time only); the IPN starts the month, the member then taps "Suivre"
                # crypto: a NOWPayments invoice; the IPN starts the month, the member then taps "Suivre" again
                cfg = nest_config()
                if not cfg.get("np_api_key"):
                    return {"ok": False, "err": "paiement indisponible"}
                import urllib.request as _urq
                api = "https://api-sandbox.nowpayments.io" if cfg.get("np_sandbox") else "https://api.nowpayments.io"
                rbname = (_OMKT.robots().get(rid) or {}).get("name_fr") or rid
                bodyj = json.dumps({"price_amount": price, "price_currency": "usd", "order_id": f"{uid}|robot:{rid}|{int(time.time())}",
                                    "order_description": f"OwlNest - robot {rbname} - 30 jours", "ipn_callback_url": f"{origin}/np_ipn",
                                    "success_url": f"{origin}/{user['token']}/place", "cancel_url": f"{origin}/{user['token']}/place"}).encode()
                req = _urq.Request(api + "/v1/invoice", data=bodyj, method="POST", headers={"x-api-key": cfg["np_api_key"], "Content-Type": "application/json"})
                with _urq.urlopen(req, timeout=20) as r:
                    inv = json.loads(r.read().decode("utf-8", "replace"))
                if not inv.get("invoice_url"):
                    return {"ok": False, "err": "no invoice"}
                return {"ok": True, "url": inv["invoice_url"]}
        _sw = account_robot_set(user, {"id": rid, "pwd": body.get("pwd")}, admin)
        if _sw.get("ok") and not (cur and cur.get("rid") == rid):
            _OMKT.start_sub(uid, rid, 0.0, "included")   # recorded only once the switch is accepted; open-ended
            try:
                _cr = L.get("by_uid")
                if _cr and _cr != uid and not is_admin(next((u for u in users() if u.get("id") == _cr), {}) or {}):
                    queue_push(_cr, "\U0001f916 Un membre tourne avec votre robot", "Vos gains de créateur montent chaque jour tant qu’il le garde.")
            except Exception:
                pass
        return _sw
    return {"ok": False, "err": "?"}


_MARKET_TICK = {"t": 0.0}


ROBOT_NOTIFIED = os.path.join(DIR, "robots", "notified.json")


def _robot_finish_push():
    """2026-10-18 (owner upgrade list): tell the member when a test they started is finished. First run = seed only."""
    try:
        seen = set(json.load(open(ROBOT_NOTIFIED, encoding="utf-8")))
        first = False
    except Exception:
        seen, first = set(), True
    reg = robot_reg()
    byid = {r["id"]: r for r in reg.get("robots") or []}
    nm = lambda rid: (byid.get(rid) or {}).get("name_fr") or rid
    ev = []
    for r in reg.get("robots") or []:
        if r.get("tested_at") and r.get("by_uid"):
            ev.append(("t:%s:%s" % (r["id"], r["tested_at"]), r["by_uid"], "Robot testé",
                       "« %s » a fini son test sur le Bitcoin. Le résultat est sur la page Mes robots." % nm(r["id"])))
    for x in _mq_load():
        if x.get("state") in ("done", "error") and x.get("uid"):
            ev.append(("m:%s" % x["id"], x["uid"], "Test de marché fini",
                       "« %s » sur %s : %s" % (nm(x["rid"]), x["sym"], "résultat prêt sur la page Mes robots." if x["state"] == "done" else "le test n’a pas pu aller au bout.")))
    for j in _ctl_load():
        st = next((c["state"] for c in _ctl_state() if c["rid"] == j["rid"] and c["sym"] == j["sym"] and c["at"] == j["at"]), None)
        if st in ("done", "error") and j.get("uid"):
            c = _random_ctl(j["rid"], j["sym"]) or {}
            ev.append(("c:%s:%s:%s" % (j["rid"], j["sym"], j["at"]), j["uid"], "Contrôle contre le hasard fini",
                       "« %s » sur %s : %s" % (nm(j["rid"]), j["sym"], (("%d tirages au hasard sur %d font aussi bien : %s" % (c.get("beats") or 0, c.get("seeds") or 0, "il bat le hasard." if (c.get("seeds") or 0) >= 100 and c["pct"] >= 95 else "dans la chance.")) if j.get("luck") else ("mieux que %d tirages au hasard sur 100." % round(c["pct"]))) if st == "done" and c.get("pct") is not None else "le contrôle n’a pas pu aller au bout.")))
    new = [e for e in ev if e[0] not in seen]
    if not first:
        for k, uid, title, body in new[:10]:
            try:
                queue_push(uid, title, body)
            except Exception:
                pass
    seen |= {e[0] for e in ev}
    json.dump(sorted(seen)[-2000:], open(ROBOT_NOTIFIED + ".tmp", "w", encoding="utf-8"))
    os.replace(ROBOT_NOTIFIED + ".tmp", ROBOT_NOTIFIED)


def _market_tick():
    """every 10 min from the robot-pending watch: listings paused when their test turns negative; subscriptions
    that ended -> back to the Owl, the member told; a reminder 2 days before the end"""
    if time.time() - _MARKET_TICK["t"] < 600:
        return
    _MARKET_TICK["t"] = time.time()
    try:
        _robot_finish_push()
    except Exception:
        pass
    try:
        import owl_market as _OMKT
        _OMKT.refresh_pauses()
        d = _OMKT.data(); R = _OMKT.robots()
        try:
            if _creator_accrue(d, time.time()):
                _OMKT._save(_OMKT.MARKET, d)
        except Exception:
            pass
        for uid, sub in list((d.get("subs") or {}).items()):
            if sub.get("open"):
                continue                      # pay once: included robots have no end date
            until = float(sub.get("until") or 0); rid = sub.get("rid")
            nm = (R.get(rid) or {}).get("name_fr") or rid
            if until <= time.time() and not sub.get("ended"):
                _OMKT.mark_ended(uid)
                try:
                    acct_robot_apply(uid, "owl", by="market")
                except Exception:
                    pass
                queue_push(uid, "\U0001f989 Retour \u00e0 l\u2019Owl", f"Votre mois avec \u00ab {nm} \u00bb est termin\u00e9 : votre compte reprend le robot du nid. Renouvelez sur la place quand vous voulez.")
            elif 0 < until - time.time() <= 2 * 86400 and not sub.get("warned"):
                sub["warned"] = int(time.time()); _OMKT._save(_OMKT.MARKET, d)
                queue_push(uid, "\u23f3 Robot suivi : 2 jours", f"Votre mois avec \u00ab {nm} \u00bb se termine dans 2 jours. Renouvelez sur la place pour le garder.")
    except Exception:
        pass


