def _join_result(title, body_html):
    return _flow_page(title, body_html)


def _broker_line(server):
    """{"known", "zone", "line"}: one plain sentence from the broker book for this server name"""
    import broker_book as _BB
    if not server:
        return {"known": False, "zone": "", "line": ""}
    if "exness" in server.lower():
        return {"known": True, "zone": "green", "line": "Exness : le courtier du robot. Tout est pr\u00eat."}
    _BB.sync_nest_data()
    pg = _BB.lookup(server)
    if not pg:
        return {"known": False, "zone": "", "line": "Courtier pas encore dans notre carnet : nous lirons votre compte en moins d\u2019une minute apr\u00e8s \u00ab V\u00e9rifier \u00bb."}
    v = pg.get("verdict") or {}
    fr = lambda x: ("%.2f" % float(x)).replace(".", ",")
    # 2026-10-17 (owner): grandma words - the gap per Bitcoin here vs Exness, then what it means for the robots
    cost = ("\u00c9cart %s $ par Bitcoin ici, %s $ \u00e0 Exness : " % (fr(v.get("spread")), fr(v.get("exness_spread") or _BB.EXNESS_SPREAD))) if v.get("spread") is not None else ""
    z = v.get("zone") or "unknown"
    tail = {"green": "les robots gagnent autant ici.", "orange": "les robots gagnent, mais moins qu\u2019\u00e0 Exness.",
            "red": "aucun robot ne gagne chez ce courtier.", "unknown": "v\u00e9rification compl\u00e8te apr\u00e8s \u00ab V\u00e9rifier \u00bb."}[z]
    return {"known": True, "zone": z, "line": cost + tail}


def _welcome_page(name, pkg_label, days, link, what, ident=None, extra=""):
    """2026-10-16 (acquisition review): step 3 of the flow, done - one button, the link kept, short copy"""
    import html as _h
    body = ("<div class=\"pill g\"><i></i>Compte ouvert</div>"
            f"<p class=\"sub\">{_h.escape(pkg_label)} &middot; {int(days)} jour{'s' if int(days) > 1 else ''}</p>"
            + what
            + (f"<p>Votre identifiant : <b>{_h.escape(ident)}</b>, avec le mot de passe que vous avez choisi, depuis n&#8217;importe quel t&eacute;l&eacute;phone.</p>" if ident else "")
            + f"<a class=\"go\" href=\"{link}?in=1\">Ouvrir mon OwlNest</a>"
            f"<div class=\"h\" style=\"text-align:center\">Votre lien : <a href=\"{link}?in=1\">{_h.escape(link.replace('https://', ''))}</a><br>Ajoutez-le &agrave; votre &eacute;cran d&#8217;accueil, ou installez l&#8217;application Android depuis l&#8217;accueil.</div>"
            + extra)
    return _flow_page("Bienvenue dans le nid, " + _h.escape(name), body, step=4, doc_title="OwlNest &middot; Bienvenue")


def _probe_wait_page(jid):
    """2026-10-16 (owner): step 2 - the member waits under a minute while the probe reads the account"""
    body = ("<div class=\"pill n\"><i></i>En cours</div>"
            "<p>Nous entrons dans votre compte chez votre courtier et lisons ce qui compte pour le robot. Moins d&#8217;une minute, en g&eacute;n&eacute;ral.</p>"
            "<ul class=\"chk\" id=\"chk\"><li class=\"on\"><i></i>Connexion &agrave; votre compte</li><li><i></i>Le Bitcoin chez ce courtier</li><li><i></i>Le co&ucirc;t par trade</li></ul>"
            "<div class=\"h\" id=\"pm\" style=\"margin-top:14px\">Ne fermez pas cette page.</div>"
            "<script>var J=" + json.dumps(jid) + ",n=0,li=document.querySelectorAll('#chk li');"
            "function step(k){for(var i=0;i<li.length;i++){li[i].className=i<k?'ok':(i===k?'on':'');}for(var i=0;i<k&&i<li.length;i++){li[i].querySelector('i').textContent='\\u2713';}}"
            "function poll(){n++;if(n===4)step(1);if(n===9)step(2);"
            "fetch('/probe?j='+J,{cache:'no-store'}).then(function(r){return r.json()}).then(function(d){"
            "if(d.state==='done'){document.body.innerHTML=d.page;window.scrollTo(0,0);return;}"
            "if(d.state==='gone'){document.getElementById('pm').textContent='La v\\u00e9rification a expir\\u00e9. Recommencez l\\u2019inscription.';return;}"
            "if(n===20){document.getElementById('pm').textContent='Votre courtier met du temps \\u00e0 r\\u00e9pondre. Nous continuons d\\u2019essayer\\u2026';}"
            "setTimeout(poll,3000);}).catch(function(){setTimeout(poll,4000);});}poll();</script>")
    return _flow_page("V&eacute;rification de votre compte", body, step=2, doc_title="OwlNest &middot; V&eacute;rification")


def _probe_card(st, jid):
    """step 2's result: a status pill, the broker, four facts, one plain sentence, one clear next step"""
    import html as _h
    import re as _rx
    v = st.get("verdict") or {}; p = st.get("profile") or {}; b = p.get("btc") or {}
    zone = v.get("zone") or "unknown"
    _comp = p.get("company") or ""
    _m = _rx.search(r"\(([^)]+)\)", _comp)          # "Gain Global Markets, Inc. (FOREX.com Global)" -> the name members know
    broker = _h.escape((_m.group(1) if _m else (_comp or p.get("server") or st.get("server") or "votre courtier").split("-")[0]).replace(" Global", "").strip())
    if "exness" in (p.get("server") or st.get("server") or "").lower():
        broker = "Exness"
    fr = lambda x: ("%.2f" % float(x)).replace(".", ",") if x is not None else "?"
    contact = nest_config().get("contact_url") or "/"
    pills = {"green": ("g", "Pr&ecirc;t pour le robot"), "orange": ("o", "Possible, co&ucirc;t plus haut"), "red": ("r", "Pas chez ce courtier"), "unknown": ("n", "Compte lu")}
    if st.get("error"):
        body = ("<div class=\"pill r\"><i></i>Connexion impossible</div>"
                f"<p class=\"sub\">{_h.escape(st.get('server') or '')}</p>"
                "<p>Nous n&#8217;avons pas pu entrer dans votre compte. Le plus souvent : le mot de passe est celui de l&#8217;application et non le <b>mot de passe principal</b>, ou le nom du serveur a une faute.</p>"
                + ("<p class=\"h\">Le courtier a refus&eacute; le num&eacute;ro de compte ou le mot de passe.</p>" if "uthorization" in str(st["error"]) or "nvalid account" in str(st["error"])
                   else "<p class=\"h\">Le courtier n&#8217;a pas r&eacute;pondu &agrave; temps : v&eacute;rifiez le nom du serveur.</p>" if "timeout" in str(st["error"]).lower() or "IPC" in str(st["error"])
                   else f"<p class=\"h\">R&eacute;ponse du courtier : {_h.escape(str(st['error'])[:140])}</p>")
                +
                f"<a class=\"go\" href=\"/offres?edit={_h.escape(jid)}\">Corriger mes informations</a>"
                f"<a class=\"go sec\" href=\"{_h.escape(contact)}\" target=\"_blank\" rel=\"noopener\">&Eacute;crire au Owl</a>")
        return _flow_page("Votre compte", body, step=2, doc_title="OwlNest &middot; V&eacute;rification")
    cls, lab = pills.get(zone, pills["unknown"])
    # 2026-10-17 (owner: "feels stuffy with texts"): four tiles with an icon, a value and at most three words; the
    # explanations live in the (i) of the sign-up sheet, not here
    _ic = lambda d: f"<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"{d}\"/></svg>"
    I_BTC = "M12 3v18M8 7h6a3 3 0 0 1 0 6H8M8 13h7a3 3 0 0 1 0 6H8"
    I_GAP = "M4 12h16M8 8l-4 4 4 4M16 8l4 4-4 4"
    I_ACC = "M3 7h18v12H3zM3 11h18M7 15h4"
    I_CLK = "M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18zM12 7v5l3 2"
    facts = f"<div class=\"fact\"><div><i>{_ic(I_BTC)}</i><span>Bitcoin</span><b>{_h.escape(str(b.get('name') or '?'))}</b><small>trouv&eacute;</small></div>"
    if v.get("spread") is not None:
        # the buy/sell gap for ONE Bitcoin (1 lot), spread only (owner: "is that the spread? depends on lot size")
        facts += "<div><i>%s</i><span>&Eacute;cart</span><b>%s $</b><small>par Bitcoin &middot; %s $ &agrave; 0,01 lot%s</small></div>" % (
            _ic(I_GAP), fr(v["spread"]), fr(float(v["spread"]) / 100.0), "" if broker == "Exness" else " &middot; hors commission")
    facts += "<div><i>%s</i><span>Compte</span><b>%s</b><small>%s</small></div>" % (_ic(I_ACC), _h.escape(str(p.get("currency") or "?")), "couverture ok" if p.get("margin_mode") == 2 else "une position")
    off = b.get("clock_offset_h")
    facts += "<div><i>%s</i><span>Horloge</span><b>UTC%s</b><small>%s</small></div></div>" % (_ic(I_CLK), ("%+d h" % off) if off else "", "r&eacute;gl&eacute;e" if off else "comme le robot")
    # 2026-10-17 (owner: "are we assuming only BTC?"): the other nest markets at this broker, as chips
    _mks = v.get("markets") or []
    if _mks:
        facts += ("<div class=\"mk\"><span>Autres march&eacute;s</span>"
                  + "".join("<em class=\"%s\">%s %s</em>" % ("ok" if m.get("found") else "no", _h.escape(m["label"]), "&#10003;" if m.get("found") else "&#10007;") for m in _mks)
                  + "<small>Bitcoin seul en argent r&eacute;el ; les autres sont en essai.</small></div>")
    sub = f"<p class=\"sub\">{_h.escape(p.get('server') or st.get('server') or '')}</p>"
    code_block = ""
    if zone != "red":
        _code = ((st.get("form") or {}).get("code") or [""])[0].strip().upper()
        code_block = ("<form method=\"POST\" action=\"/activate\"><input type=\"hidden\" name=\"action\" value=\"continue\">"
                      f"<input type=\"hidden\" name=\"probe\" value=\"{_h.escape(jid)}\">"
                      "<label for=\"ccode\">Code d&#8217;activation</label>"
                      f"<input id=\"ccode\" class=\"code\" name=\"code\" maxlength=\"6\" value=\"{_h.escape(_code)}\" placeholder=\"ABC123\" autocapitalize=\"characters\" autocomplete=\"off\">"
                      "<button class=\"go\">Activer mon compte</button></form>"
                      f"<a class=\"lnk\" href=\"{_h.escape(contact)}\" target=\"_blank\" rel=\"noopener\">Pas de code ? &Eacute;crire au Owl sur Telegram</a>"
                      "<div class=\"h\" style=\"text-align:center;margin-top:4px\">Re&ccedil;u du Owl &middot; valable une heure</div>")
    if zone == "green" and broker == "Exness":
        say = "<div class=\"say g\"><b>Tout est pr&ecirc;t.</b><span>Entrez votre code : le robot d&eacute;marre ici dans quelques minutes.</span></div>"
    elif zone == "green":
        say = f"<div class=\"say g\"><b>&Ccedil;a marche chez {broker}.</b><span>" + \
              (f"Sur 42 jours de test : {fr(v['est_net'])} $ ici, {fr(v['native_net'])} $ &agrave; Exness." if v.get("est_net") is not None else "Le robot y gagne autant qu&#8217;&agrave; Exness.") + "</span></div>"
    elif zone == "orange":
        say = (f"<div class=\"say o\"><b>&Ccedil;a marche, mais moins.</b><span>L&#8217;&eacute;cart est plus haut ici. Sur 42 jours de test : {fr(v['est_net'])} $ ici, {fr(v['native_net'])} $ &agrave; Exness. "
               "Continuez ici, ou ouvrez un compte chez un courtier moins cher et revenez.</span></div>")
    elif zone == "red":
        why = " ".join(_h.escape(r[:1].upper() + r[1:]) + "." for r in (v.get("reasons") or []))
        say = (f"<p><b>Rien ne gagne chez {broker}.</b> {why}</p>"
               "<h2>Trois portes</h2><div class=\"doors\">"
               "<a href=\"/#offres\"><em>1</em><div><b>Signal</b><span>Recevez les signaux et tradez vous-m&ecirc;me, chez n&#8217;importe quel courtier.</span></div></a>"
               "<div><em>2</em><div><b>Un courtier moins cher</b><span>Ouvrez un compte chez Exness, par exemple, et revenez : l&#8217;inscription prend une minute.</span></div></div>"
               f"<a href=\"{_h.escape(contact)}\" target=\"_blank\" rel=\"noopener\"><em>3</em><div><b>&Eacute;crire au Owl</b><span>Nous regardons ensemble ce qui est possible.</span></div></a></div>"
               "<a class=\"go sec\" href=\"/\">Retour &agrave; l&#8217;accueil</a>")
    else:
        say = "<p>Votre compte se lit bien. Le r&eacute;sultat chiffr&eacute; chez ce courtier arrive bient&ocirc;t ; vous pouvez activer d&egrave;s maintenant.</p>"
    robots = ""
    _born = {}
    try:
        _born = {r["id"]: (r.get("born_at") or "Exness") for r in (json.load(open(os.path.join(DIR, "robots", "robots.json"), encoding="utf-8")).get("robots") or [])}
    except Exception:
        pass
    if (v.get("robots") or []) and broker != "Exness":
        # owner 2026-10-16: "the verification should check any existing robot" - every public robot at this cost.
        # 2026-10-17 (owner: "what does it mean? what are the red numbers?"): one comparison per robot, same 42 days,
        # Exness on the left, this broker on the right, and the word "gagne" / "perd" next to the number
        robots = ("<h2>Les robots, avec l&#8217;&eacute;cart de " + _h.escape(broker) + "</h2>"
                  "<p class=\"h\" style=\"margin:-2px 0 8px\">M&ecirc;mes 42 jours, m&ecirc;mes trades : seul le co&ucirc;t de chaque trade change.</p>"
                  "<ul class=\"rl\"><li class=\"hd\"><div></div><em>&agrave; Exness</em><em>chez " + _h.escape(broker) + "</em></li>" + "".join(
            f"<li><div><b>{_h.escape(str(r.get('name') or r.get('id')))}</b></div>"
            f"<em class=\"up\">{('+' if float(r.get('native') or 0) > 0 else '')}{fr(r.get('native'))} $</em>"
            f"<em class=\"{'up' if r.get('pays') else 'dn'}\">{('+' if float(r.get('est') or 0) > 0 else '')}{fr(r.get('est'))} $<small>{'gagne' if r.get('pays') else 'perd'}</small></em></li>"
            for r in v["robots"]) + "</ul>")
    # 2026-10-17 (owner: "verdict first, everything else second"): pill, verdict, the one action; the reading's
    # details (tiles, markets, robot comparison) fold into one panel underneath
    _n = 4 + (1 if v.get("markets") else 0) + (len(v.get("robots") or []) if robots else 0)
    details = ("<details class=\"dt\"><summary><span>D&eacute;tails de la lecture</span><small>%d points</small><i></i></summary>" % _n
               + facts + robots + "</details>")
    body = f"<div class=\"pill {cls}\"><i></i>{lab}</div>" + sub + say + code_block + details
    return _flow_page(broker, body, step=2, doc_title="OwlNest &middot; V&eacute;rification")


