            "padding:8px 20px 28px;z-index:6;max-height:88vh;max-height:calc(100dvh - 56px);overflow:auto;box-shadow:0 -24px 60px rgba(0,0,0,.55);animation:mdup .34s cubic-bezier(.2,.8,.2,1);overscroll-behavior:contain}"
