            ".tile.sig{background:linear-gradient(135deg,#0ea5e9,#2563eb);box-shadow:0 8px 24px rgba(14,165,233,.3)}.tile.str{background:linear-gradient(135deg,#f59e0b,#ec4899);box-shadow:0 8px 24px rgba(245,158,11,.3)}"
            ".tile svg{width:24px;height:24px}"
            "#md h2{margin:0;font-size:1.25rem;letter-spacing:-.015em}.msub{color:var(--tx3);font-size:.82rem;margin-top:2px}"
